        label: guideLabel,
        line: {
          x1: selectedPlanningGuide.anchorStart.x,
          y1: selectedPlanningGuide.anchorStart.y,
          x2: selectedPlanningGuide.anchorEnd.x,
          y2: selectedPlanningGuide.anchorEnd.y,
        },
