  const findHkaLabelByPoint = useCallback(
    (screenPoint) => {
      for (let index = hkaSets.length - 1; index >= 0; index -= 1) {
        const item = hkaSets[index];
        const measurement = getHkaMeasurementResult(item);
        let anchor = null;

        if (item.mode === "fta") {
          if (
            !item.femoralNotch ||
            !item.tibiaMidshaft4cm
          ) {
            continue;
          }
          const notch = imageToScreenPoint(
            item.femoralNotch.x,
            item.femoralNotch.y,
          );
          const tibia4 = imageToScreenPoint(
            item.tibiaMidshaft4cm.x,
            item.tibiaMidshaft4cm.y,
          );
          anchor = {
            x: (notch.x + tibia4.x) / 2,
            y: (notch.y + tibia4.y) / 2,
          };
        } else {
          if (!item.knee) continue;
          anchor = imageToScreenPoint(item.knee.x, item.knee.y);
        }

        const labelX =
          anchor.x +
          (Number.isFinite(item.labelOffsetX)
            ? item.labelOffsetX
            : DEFAULT_HKA_LABEL_OFFSET_X);
        const labelY =
          anchor.y +
          (Number.isFinite(item.labelOffsetY)
            ? item.labelOffsetY
            : DEFAULT_HKA_LABEL_OFFSET_Y);
        const bounds = getTagBounds(
          labelX,
          labelY,
          getHkaCanvasLabelText(measurement, true),
          { fontSize: 9, radius: 4 },
        );
        if (
          screenPoint.x >= bounds.left &&
          screenPoint.x <= bounds.right &&
          screenPoint.y >= bounds.top &&
          screenPoint.y <= bounds.bottom
        ) {
          return item.id;
        }
      }
      return null;
    },
    [hkaSets, imageToScreenPoint],
  );

  const findClosestAngleHandle = useCallback(
    (imagePoint) => {
      const thresholdInImage =
        (isCoarsePointer ? MOBILE_HANDLE_TARGET_SCREEN : 10) / view.scale;
      let picked = null;
      let minDistance = Infinity;

      for (const angle of angles) {
        const handles = [
          { key: "p1", x: angle.p1.x, y: angle.p1.y },
          { key: "p2", x: angle.p2.x, y: angle.p2.y },
          { key: "p3", x: angle.p3.x, y: angle.p3.y },
        ];
        for (const handle of handles) {
          const distance = Math.hypot(
            imagePoint.x - handle.x,
            imagePoint.y - handle.y,
          );
          if (distance <= thresholdInImage && distance < minDistance) {
            minDistance = distance;
            picked = { angleId: angle.id, handleKey: handle.key };
          }
        }
      }
      return picked;
    },
    [angles, isCoarsePointer, view.scale],
  );

  const findClosestAngleId = useCallback(
    (imagePoint) => {
      const thresholdInImage =
        (isCoarsePointer ? MOBILE_TOUCH_TARGET_SCREEN : 10) / view.scale;
      let pickedId = null;
      let minDistance = Infinity;

      for (const angle of angles) {
        const distanceA = distancePointToSegment(imagePoint, {
          x1: angle.p2.x,
          y1: angle.p2.y,
          x2: angle.p1.x,
          y2: angle.p1.y,
        });
        const distanceB = distancePointToSegment(imagePoint, {
          x1: angle.p2.x,
          y1: angle.p2.y,
          x2: angle.p3.x,
          y2: angle.p3.y,
        });
        const distance = Math.min(distanceA, distanceB);
        if (distance <= thresholdInImage && distance < minDistance) {
          minDistance = distance;
          pickedId = angle.id;
        }
      }

      return pickedId;
    },
    [angles, isCoarsePointer, view.scale],
  );

  const findClosestCircleHandle = useCallback(
    (imagePoint) => {
      const centerThreshold =
        (isCoarsePointer ? MOBILE_HANDLE_TARGET_SCREEN : 18) / view.scale;
      const radiusThreshold =
        (isCoarsePointer ? MOBILE_HANDLE_TARGET_SCREEN : 16) / view.scale;

      for (let i = circles.length - 1; i >= 0; i -= 1) {
        const circle = circles[i];
        const centerDistance = Math.hypot(
          imagePoint.x - circle.cx,
          imagePoint.y - circle.cy,
        );
        if (centerDistance <= centerThreshold) {
          return { circleId: circle.id, handleKey: "center" };
        }
        // Check proximity to diameter endpoint handles (takes priority over generic radius)
        const dAngle = ((circle.diameterAngle ?? 0) * Math.PI) / 180;
        const dCos = Math.cos(dAngle);
        const dSin = Math.sin(dAngle);
        const dEnd1 = { x: circle.cx + circle.radius * dCos, y: circle.cy + circle.radius * dSin };
        const dEnd2 = { x: circle.cx - circle.radius * dCos, y: circle.cy - circle.radius * dSin };
        if (Math.hypot(imagePoint.x - dEnd1.x, imagePoint.y - dEnd1.y) <= radiusThreshold) {
          return { circleId: circle.id, handleKey: "diameter" };
        }
        if (Math.hypot(imagePoint.x - dEnd2.x, imagePoint.y - dEnd2.y) <= radiusThreshold) {
          return { circleId: circle.id, handleKey: "diameter" };
        }
        const radiusDistance = Math.abs(centerDistance - circle.radius);
        if (radiusDistance <= radiusThreshold) {
          return { circleId: circle.id, handleKey: "radius" };
        }
        if (centerDistance < Math.max(circle.radius - radiusThreshold, 4)) {
          return { circleId: circle.id, handleKey: "move" };
        }
      }
      return null;
    },
    [circles, isCoarsePointer, view.scale],
  );

  const findClosestCircleId = useCallback(
    (imagePoint) => {
      const thresholdInImage =
        (isCoarsePointer ? MOBILE_TOUCH_TARGET_SCREEN : 14) / view.scale;
      let pickedId = null;
      let minDistance = Infinity;

      for (let index = circles.length - 1; index >= 0; index -= 1) {
        const circle = circles[index];
        const centerDistance = Math.hypot(
          imagePoint.x - circle.cx,
          imagePoint.y - circle.cy,
        );
        const ringDistance = Math.abs(centerDistance - circle.radius);
        const insideDistance = centerDistance <= circle.radius ? 0 : Infinity;
        const distance = Math.min(ringDistance, insideDistance);
        if (distance <= thresholdInImage && distance < minDistance) {
          minDistance = distance;
          pickedId = circle.id;
        }
      }

      return pickedId;
    },
    [circles, isCoarsePointer, view.scale],
  );

  const findCircleLabelByPoint = useCallback(
    (screenPoint) => {
      for (let index = circles.length - 1; index >= 0; index -= 1) {
        const circle = circles[index];
        const center = imageToScreenPoint(circle.cx, circle.cy);
        const edge = imageToScreenPoint(circle.cx + circle.radius, circle.cy);
        const radiusPx = Math.hypot(edge.x - center.x, edge.y - center.y);
        const labelX = center.x + (circle.labelOffsetX ?? 0);
        const labelY = center.y - radiusPx - 12 + (circle.labelOffsetY ?? 0);
        const bounds = getTagBounds(
          labelX,
          labelY,
          getCircleCanvasLabelText(circle, mmPerPixel, measurementUnit, true),
          { fontSize: 9, radius: 4 },
        );
        if (
          screenPoint.x >= bounds.left &&
          screenPoint.x <= bounds.right &&
          screenPoint.y >= bounds.top &&
          screenPoint.y <= bounds.bottom
        ) {
          return circle.id;
        }
      }
      return null;
    },
    [circles, imageToScreenPoint, measurementUnit, mmPerPixel],
  );

  const findClosestHkaHandle = useCallback(
    (imagePoint) => {
      const thresholdInImage =
        (isCoarsePointer ? MOBILE_HANDLE_TARGET_SCREEN : 10) / view.scale;
      let picked = null;
      let minDistance = Infinity;

      for (const item of hkaSets) {
        const handles = getHkaPointEntries(item).map((entry) => ({
          key: entry.key,
          x: entry.point.x,
          y: entry.point.y,
        }));
        for (const handle of handles) {
          const distance = Math.hypot(
            imagePoint.x - handle.x,
            imagePoint.y - handle.y,
          );
          if (distance <= thresholdInImage && distance < minDistance) {
            minDistance = distance;
            picked = { hkaId: item.id, handleKey: handle.key };
          }
        }
      }

      return picked;
    },
    [hkaSets, isCoarsePointer, view.scale],
  );

  const findClosestHkaId = useCallback(
    (imagePoint) => {
      const thresholdInImage =
        (isCoarsePointer ? MOBILE_TOUCH_TARGET_SCREEN : 10) / view.scale;
      let pickedId = null;
      let minDistance = Infinity;

      for (const item of hkaSets) {
        const segments =
          item.mode === "fta"
            ? item.femurMidshaft10cm &&
              item.femoralNotch &&
              item.tibiaMidshaft4cm &&
              item.tibiaMidshaft10cm
              ? [
                  {
                    x1: item.femurMidshaft10cm.x,
                    y1: item.femurMidshaft10cm.y,
                    x2: item.femoralNotch.x,
                    y2: item.femoralNotch.y,
                  },
                  {
                    x1: item.tibiaMidshaft4cm.x,
                    y1: item.tibiaMidshaft4cm.y,
                    x2: item.tibiaMidshaft10cm.x,
                    y2: item.tibiaMidshaft10cm.y,
                  },
                ]
              : []
            : item.hip && item.knee && item.ankle
              ? [
                  {
                    x1: item.knee.x,
                    y1: item.knee.y,
                    x2: item.hip.x,
                    y2: item.hip.y,
                  },
                  {
                    x1: item.knee.x,
                    y1: item.knee.y,
                    x2: item.ankle.x,
                    y2: item.ankle.y,
                  },
                ]
              : [];

        for (const segment of segments) {
          const distance = distancePointToSegment(imagePoint, segment);
          if (distance <= thresholdInImage && distance < minDistance) {
            minDistance = distance;
            pickedId = item.id;
          }
        }
      }

      return pickedId;
    },
    [hkaSets, isCoarsePointer, view.scale],
  );

  const findFreeLinePointHandle = useCallback(
    (imagePoint) => {
      if (!isEditableMaskLayer(selectedCutLayer)) {
        return null;
      }
      const thresholdInImage =
        (isCoarsePointer ? MOBILE_HANDLE_TARGET_SCREEN : 12) / view.scale;
      let picked = null;
      let minDistance = Infinity;

      for (const point of getFreeLineVertexPoints(selectedCutLayer)) {
        const distance = Math.hypot(
          imagePoint.x - point.x,
          imagePoint.y - point.y,
        );
        if (distance <= thresholdInImage && distance < minDistance) {
          minDistance = distance;
          picked = {
            layerId: selectedCutLayer.id,
            pointIndex: point.pointIndex,
          };
        }
      }

      return picked;
    },
    [isCoarsePointer, selectedCutLayer, view.scale],
  );

  const findFreeLineCurveHandle = useCallback(
    (imagePoint) => {
      if (
        !isEditableMaskLayer(selectedCutLayer) ||
        selectedFreeLinePointIndex === null
      ) {
        return null;
      }

      const thresholdInImage =
        (isCoarsePointer ? MOBILE_HANDLE_TARGET_SCREEN : 13) / view.scale;
      let picked = null;
      let minDistance = Infinity;

      for (const handle of getFreeLineCurveHandles(
        selectedCutLayer,
        selectedFreeLinePointIndex,
      )) {
        const distance = Math.hypot(
          imagePoint.x - handle.x,
          imagePoint.y - handle.y,
        );
        if (distance <= thresholdInImage && distance < minDistance) {
          minDistance = distance;
          picked = {
            layerId: selectedCutLayer.id,
            pointIndex: handle.pointIndex,
            handleKey: handle.handleKey,
          };
        }
      }

      return picked;
    },
    [isCoarsePointer, selectedCutLayer, selectedFreeLinePointIndex, view.scale],
  );

  const snapCandidates = useMemo(() => {
    const candidates = [];
    const segments = [];

    const pushCandidate = (candidate) => {
      if (
        !Number.isFinite(candidate?.x) ||
        !Number.isFinite(candidate?.y) ||
        !candidate?.type
      ) {
        return;
      }
      const duplicate = candidates.some(
        (item) =>
          item.type === candidate.type &&
          Math.hypot(item.x - candidate.x, item.y - candidate.y) <= 0.6,
      );
      if (duplicate) return;
      candidates.push(candidate);
    };

    if (snapSettings.endpoint) {
      for (const line of lines) {
        pushCandidate({
          type: "endpoint",
          x: line.x1,
          y: line.y1,
          sourceRefs: [`line:${line.id}`],
        });
        pushCandidate({
          type: "endpoint",
          x: line.x2,
          y: line.y2,
          sourceRefs: [`line:${line.id}`],
        });
      }

      for (const guide of planningGuides) {
        pushCandidate({
          type: "endpoint",
          x: guide.anchorStart.x,
          y: guide.anchorStart.y,
          sourceRefs: [`guide:${guide.id}`],
        });
        pushCandidate({
          type: "endpoint",
          x: guide.anchorEnd.x,
          y: guide.anchorEnd.y,
          sourceRefs: [`guide:${guide.id}`],
        });
      }

      for (const angle of angles) {
        for (const entry of getAnglePointEntries(angle)) {
          pushCandidate({
            type: "endpoint",
            x: entry.point.x,
            y: entry.point.y,
            sourceRefs: [`angle:${angle.id}`],
          });
        }
      }

      for (const item of hkaSets) {
        for (const entry of getHkaPointEntries(item)) {
          pushCandidate({
            type: "endpoint",
            x: entry.point.x,
            y: entry.point.y,
            sourceRefs: [`hka:${item.id}`],
          });
        }
      }
    }

    if (snapSettings.midpoint || snapSettings.intersection) {
      for (const line of lines) {
        const segment = {
          x1: line.x1,
          y1: line.y1,
          x2: line.x2,
          y2: line.y2,
          sourceRef: `line:${line.id}`,
        };
        segments.push(segment);
        if (snapSettings.midpoint) {
          const midpoint = getSegmentMidpoint(
            { x: line.x1, y: line.y1 },
            { x: line.x2, y: line.y2 },
          );
          pushCandidate({
            type: "midpoint",
            x: midpoint.x,
            y: midpoint.y,
            sourceRefs: [segment.sourceRef],
          });
        }
      }

      for (const guide of planningGuides) {
        const segment = {
          x1: guide.anchorStart.x,
          y1: guide.anchorStart.y,
          x2: guide.anchorEnd.x,
          y2: guide.anchorEnd.y,
          sourceRef: `guide:${guide.id}`,
        };
        segments.push(segment);
        if (snapSettings.midpoint) {
          const midpoint = getSegmentMidpoint(guide.anchorStart, guide.anchorEnd);
          pushCandidate({
            type: "midpoint",
            x: midpoint.x,
            y: midpoint.y,
            sourceRefs: [segment.sourceRef],
          });
        }
      }
    }

    if (snapSettings.center) {
      for (const circle of circles) {
        pushCandidate({
          type: "center",
          x: circle.cx,
          y: circle.cy,
          sourceRefs: [`circle:${circle.id}`],
        });
      }
    }

    if (snapSettings.intersection && segments.length > 1) {
      for (let index = 0; index < segments.length; index += 1) {
        for (let nextIndex = index + 1; nextIndex < segments.length; nextIndex += 1) {
          const segmentA = segments[index];
          const segmentB = segments[nextIndex];
          if (segmentA.sourceRef === segmentB.sourceRef) continue;
          const intersection = getSegmentIntersectionPoint(segmentA, segmentB);
          if (!intersection) continue;
          pushCandidate({
            type: "intersection",
            x: intersection.x,
            y: intersection.y,
            sourceRefs: [segmentA.sourceRef, segmentB.sourceRef],
          });
        }
      }
    }

    return candidates;
  }, [angles, circles, hkaSets, lines, planningGuides, snapSettings]);

  const resolveSnappedImagePoint = useCallback(
    (rawPoint, { excludeRefs = [], thresholdPx } = {}) => {
      const allowSnapByModifier =
        !snapSettings.shiftOnlyDesktop ||
        isCoarsePointer ||
        snapModifierPressedRef.current;

      if (!snapToLandmarks || !allowSnapByModifier) {
        return { point: rawPoint, candidate: null };
      }

      const thresholdInImage =
        (thresholdPx ?? (isCoarsePointer ? MOBILE_TOUCH_TARGET_SCREEN : 12)) /
        view.scale;
      let nearest = null;
      let nearestDistance = Infinity;

      const evaluateCandidate = (candidate) => {
        if (!candidate) return;
        if (
          excludeRefs.length > 0 &&
          candidate.sourceRefs?.some((ref) => excludeRefs.includes(ref))
        ) {
          return;
        }
        const distance = Math.hypot(rawPoint.x - candidate.x, rawPoint.y - candidate.y);
        if (distance <= thresholdInImage && distance < nearestDistance) {
          nearest = candidate;
          nearestDistance = distance;
        }
      };

      for (const candidate of snapCandidates) {
        evaluateCandidate(candidate);
      }

      if (snapSettings.perpendicular) {
        for (const line of lines) {
          const projection = projectPointToInfiniteLine(rawPoint, line);
          if (!projection) continue;
          evaluateCandidate({
            type: "perpendicular",
            x: projection.x,
            y: projection.y,
            sourceRefs: [`line:${line.id}`],
            hintSegments: [
              {
                x1: rawPoint.x,
                y1: rawPoint.y,
                x2: projection.x,
                y2: projection.y,
              },
            ],
          });
        }
        for (const guide of planningGuides) {
          const projection = projectPointToInfiniteLine(rawPoint, {
            x1: guide.anchorStart.x,
            y1: guide.anchorStart.y,
            x2: guide.anchorEnd.x,
            y2: guide.anchorEnd.y,
          });
          if (!projection) continue;
          evaluateCandidate({
            type: "perpendicular",
            x: projection.x,
            y: projection.y,
            sourceRefs: [`guide:${guide.id}`],
            hintSegments: [
              {
                x1: rawPoint.x,
                y1: rawPoint.y,
                x2: projection.x,
                y2: projection.y,
              },
            ],
          });
        }
      }

      if (snapSettings.tangent) {
        for (const circle of circles) {
          const tangentPoints = getCircleTangentPointsFromExternalPoint(
            rawPoint,
            circle,
          );
          for (const tangentPoint of tangentPoints) {
            evaluateCandidate({
              type: "tangent",
              x: tangentPoint.x,
              y: tangentPoint.y,
              sourceRefs: [`circle:${circle.id}`],
              hintSegments: [
                {
                  x1: rawPoint.x,
                  y1: rawPoint.y,
                  x2: tangentPoint.x,
                  y2: tangentPoint.y,
                },
                {
                  x1: circle.cx,
                  y1: circle.cy,
                  x2: tangentPoint.x,
                  y2: tangentPoint.y,
                },
              ],
            });
          }
        }
      }

      if (!nearest) {
        return { point: rawPoint, candidate: null };
      }

      return {
        point: { x: nearest.x, y: nearest.y },
        candidate: {
          ...nearest,
          label: getSnapTypeShortLabel(nearest.type),
        },
      };
    },
    [
      circles,
      isCoarsePointer,
      lines,
      planningGuides,
      snapCandidates,
      snapSettings.perpendicular,
      snapSettings.shiftOnlyDesktop,
      snapSettings.tangent,
      snapToLandmarks,
      view.scale,
    ],
  );

  const resolveSnapWithPreview = useCallback(
    (rawPoint, options = {}) => {
      const result = resolveSnappedImagePoint(rawPoint, options);
      const nextCandidate = result.candidate || null;
      const nextSignature = getSnapTargetSignature(nextCandidate);
      if (activeSnapTargetSignatureRef.current !== nextSignature) {
        activeSnapTargetRef.current = nextCandidate;
        activeSnapTargetSignatureRef.current = nextSignature;
        setActiveSnapTarget(nextCandidate);
      }
      return result;
    },
    [resolveSnappedImagePoint],
  );

  const clearSnapPreview = useCallback(() => {
    if (!activeSnapTargetRef.current) return;
    activeSnapTargetRef.current = null;
    activeSnapTargetSignatureRef.current = getSnapTargetSignature(null);
    setActiveSnapTarget(null);
  }, []);

  const findCutLayerHandle = useCallback(
    (imagePoint) => {
      const thresholdInImage =
        (isCoarsePointer ? MOBILE_ROTATE_HANDLE_TARGET_SCREEN : 14) / view.scale;

      for (let i = cutLayers.length - 1; i >= 0; i -= 1) {
        const layer = cutLayers[i];
        if (layer.hidden) continue;
        const controlPoints = getLayerControlPoints(layer);

        for (const controlPoint of controlPoints) {
          const distance = Math.hypot(
            imagePoint.x - controlPoint.x,
            imagePoint.y - controlPoint.y,
          );
          if (distance <= thresholdInImage) {
            return {
              layerId: layer.id,
              handleKey: controlPoint.key,
              handleType: controlPoint.type,
            };
          }
        }
      }

      return null;
    },
    [cutLayers, isCoarsePointer, view.scale],
  );

  const findCutLayerByPoint = useCallback(
    (imagePoint) => {
      for (let i = cutLayers.length - 1; i >= 0; i -= 1) {
        const layer = cutLayers[i];
        if (layer.hidden) continue;
        const maskPoints = getLayerMaskDisplayPoints(layer);
        if (maskPoints) {
          const local = toLayerShapeLocal(imagePoint, layer);
          if (pointInPolygon(local, maskPoints)) {
            return layer.id;
          }
          continue;
        }

        const local = toLayerLocal(imagePoint, layer);
        const size = getLayerDisplaySize(layer);
        if (
          Math.abs(local.x) <= size.width / 2 &&
          Math.abs(local.y) <= size.height / 2
        ) {
          return layer.id;
        }
      }
      return null;
    },
    [cutLayers],
  );

  const renderLayers = useCallback(() => {
    const imageCanvas = imageCanvasRef.current;
    const overlayCanvas = overlayCanvasRef.current;
    if (!imageCanvas || !overlayCanvas || !viewport.width || !viewport.height) {
      return;
    }

    const ratio = window.devicePixelRatio || 1;
    const targetWidth = Math.floor(viewport.width * ratio);
    const targetHeight = Math.floor(viewport.height * ratio);

    for (const canvas of [imageCanvas, overlayCanvas]) {
      if (canvas.width !== targetWidth || canvas.height !== targetHeight) {
        canvas.width = targetWidth;
        canvas.height = targetHeight;
      }
      canvas.style.width = `${viewport.width}px`;
      canvas.style.height = `${viewport.height}px`;
    }
    const activeImageProcessingMode =
      normalizeImageProcessingMode(imageProcessingMode);
    const filterValue = `contrast(${contrast}%) brightness(${level}%)${invertImage ? " invert(1)" : ""}`;
    imageCanvas.style.filter = "none";
    overlayCanvas.style.filter = "none";

    const imageCtx = imageCanvas.getContext("2d");
    const overlayCtx = overlayCanvas.getContext("2d");

    if (!imageCtx || !overlayCtx) return;

    imageCtx.setTransform(ratio, 0, 0, ratio, 0, 0);
    imageCtx.clearRect(0, 0, viewport.width, viewport.height);

    if (
      image &&
      imageWidth > 0 &&
      imageHeight > 0 &&
      modelWidth > 0 &&
      modelHeight > 0
    ) {
      const sourceX = cropRect?.x || 0;
      const sourceY = cropRect?.y || 0;
      const sourceW = cropRect?.width || imageWidth;
      const sourceH = cropRect?.height || imageHeight;

      const p0 = orientPoint(
        0,
        0,
        modelWidth,
        modelHeight,
        rotation,
        flipX,
        flipY,
      );
      const p1 = orientPoint(
        1,
        0,
        modelWidth,
        modelHeight,
        rotation,
        flipX,
        flipY,
      );
      const p2 = orientPoint(
        0,
        1,
        modelWidth,
        modelHeight,
        rotation,
        flipX,
        flipY,
      );
      const a = p1.x - p0.x;
      const b = p1.y - p0.y;
      const c = p2.x - p0.x;
      const d = p2.y - p0.y;
      const e = p0.x;
      const f = p0.y;

      imageCtx.save();
      imageCtx.translate(view.x, view.y);
      imageCtx.scale(view.scale, view.scale);
      imageCtx.transform(a, b, c, d, e, f);
      const processedXrayCanvas =
        activeImageProcessingMode !== "normal"
          ? processedXrayCanvasRef.current
          : null;
      imageCtx.filter = filterValue;
      imageCtx.imageSmoothingEnabled = true;
      if (processedXrayCanvas) {
        imageCtx.drawImage(processedXrayCanvas, 0, 0, modelWidth, modelHeight);
      } else {
        imageCtx.drawImage(
          image,
          sourceX,
          sourceY,
          sourceW,
          sourceH,
          0,
          0,
          modelWidth,
          modelHeight,
        );
      }

      for (const layer of cutLayers) {
        if (layer.hidden) continue;
        const cachedLayerData = layerDisplayData.get(layer.id);
        const displaySize = cachedLayerData?.displaySize ?? getLayerDisplaySize(layer);
        const cachedMaskPoints = cachedLayerData?.maskPoints ?? null;

        imageCtx.save();
        imageCtx.translate(layer.centerX, layer.centerY);
        imageCtx.rotate((layer.rotation * Math.PI) / 180);
        imageCtx.scale(layer.flipX ? -1 : 1, layer.flipY ? -1 : 1);
        imageCtx.globalAlpha = clamp(layer.opacity ?? 1, 0.05, 1);
        imageCtx.filter = "none";

        if (layer.kind === "free-line") {
          const localMaskPoints = cachedMaskPoints ?? getLayerMaskDisplayPoints(layer);
          if (localMaskPoints?.length >= MIN_FREE_CUT_POINTS) {
            const curveStrength = getFreeLineCurveStrength(layer);
            imageCtx.fillStyle = layer.fillColor || DEFAULT_FREE_LINE_COLOR;
            imageCtx.strokeStyle = layer.fillColor || DEFAULT_FREE_LINE_COLOR;
            imageCtx.lineWidth = Math.max(1 / view.scale, 1.15);
            traceSmoothClosedPath(imageCtx, localMaskPoints, curveStrength);
            imageCtx.fill();
            imageCtx.stroke();
          }
        } else {
          const isImageBacked = isImageBackedLayerKind(layer.kind);
          const srcX = isImageBacked ? layer.sourceX : sourceX + layer.sourceX;
          const srcY = isImageBacked ? layer.sourceY : sourceY + layer.sourceY;
          const sourceImage = isImageBacked ? layer.image : image;
          if (!sourceImage) {
            imageCtx.restore();
            continue;
          }
          imageCtx.filter = isImageBacked
            ? getLayerFilterValue(layer)
            : "none";
          const localMaskPoints = cachedMaskPoints ?? getLayerMaskDisplayPoints(layer);
          if (localMaskPoints?.length >= MIN_FREE_CUT_POINTS && layer.kind !== "free-cut") {
            traceSmoothClosedPath(
              imageCtx,
              localMaskPoints,
              getFreeLineCurveStrength(layer),
            );
            imageCtx.clip();
          }
          const didDrawWarped = drawWarpedImageLayer(
            imageCtx,
            layer,
            sourceImage,
            srcX,
            srcY,
            layer.sourceWidth,
            layer.sourceHeight,
            displaySize.width,
            displaySize.height,
          );
          if (!didDrawWarped) {
            imageCtx.drawImage(
              sourceImage,
              srcX,
              srcY,
              layer.sourceWidth,
              layer.sourceHeight,
              -displaySize.width / 2,
              -displaySize.height / 2,
              displaySize.width,
              displaySize.height,
            );
          }
        }

        if (selectedCutLayerIdsSet.has(layer.id)) {
          const layerPalette = getLayerPalette(layer.id);
          imageCtx.strokeStyle = layerPalette.border;
          imageCtx.lineWidth = Math.max(
            1 / view.scale,
            layer.id === selectedCutLayerId ? 1.2 : 0.8,
          );
          imageCtx.setLineDash(
            layer.id === selectedCutLayerId
              ? [10 / view.scale, 6 / view.scale]
              : [6 / view.scale, 5 / view.scale],
          );
          imageCtx.strokeRect(
            -displaySize.width / 2,
            -displaySize.height / 2,
            displaySize.width,
            displaySize.height,
          );
          imageCtx.setLineDash([]);
        }
        imageCtx.restore();
      }

      imageCtx.filter = "none";
      imageCtx.restore();
    }

    overlayCtx.setTransform(ratio, 0, 0, ratio, 0, 0);
    overlayCtx.clearRect(0, 0, viewport.width, viewport.height);

    if (
      !image ||
      imageWidth <= 0 ||
      imageHeight <= 0 ||
      modelWidth <= 0 ||
      modelHeight <= 0
    ) {
      overlayCtx.fillStyle = "rgba(15, 23, 42, 0.8)";
      overlayCtx.font = "15px Inter, sans-serif";
      overlayCtx.textAlign = "center";
      overlayCtx.fillText(
        "Belum ada gambar. Upload screenshot X-ray terlebih dahulu.",
        viewport.width / 2,
        viewport.height / 2,
      );
      return;
    }

    const topLeft = imageToScreenPoint(0, 0);
    overlayCtx.strokeStyle = "rgba(148, 163, 184, 0.7)";
    overlayCtx.lineWidth = 1;
    overlayCtx.strokeRect(
      topLeft.x,
      topLeft.y,
      orientedSize.width * view.scale,
      orientedSize.height * view.scale,
    );

    const drawLine = (line, opts = {}) => {
      const start = imageToScreenPoint(line.x1, line.y1);
      const end = imageToScreenPoint(line.x2, line.y2);
      const assistGeometry = opts.assistHandleKey
        ? getMobileHandleAssistGeometry(line, opts.assistHandleKey)
        : null;

      overlayCtx.save();
      if (assistGeometry) {
        overlayCtx.fillStyle = "rgba(226, 232, 240, 0.34)";
        overlayCtx.beginPath();
        overlayCtx.arc(
          assistGeometry.centerX,
          assistGeometry.centerY,
          MOBILE_LINE_HANDLE_ASSIST_RADIUS_SCREEN,
          0,
          Math.PI * 2,
        );
        overlayCtx.fill();
        overlayCtx.strokeStyle = "rgba(248, 250, 252, 0.65)";
        overlayCtx.lineWidth = 1.5;
        overlayCtx.beginPath();
        overlayCtx.arc(
          assistGeometry.centerX,
          assistGeometry.centerY,
          MOBILE_LINE_HANDLE_ASSIST_RADIUS_SCREEN,
          0,
          Math.PI * 2,
        );
        overlayCtx.stroke();
      }
      if (opts.showTouchHalo) {
        overlayCtx.strokeStyle = "rgba(248, 250, 252, 0.22)";
        overlayCtx.lineWidth = (opts.width || 2) + 18;
        overlayCtx.lineCap = "round";
        overlayCtx.beginPath();
        overlayCtx.moveTo(start.x, start.y);
        overlayCtx.lineTo(end.x, end.y);
        overlayCtx.stroke();
      }
      if (opts.calibrationReference) {
        overlayCtx.strokeStyle = opts.calibrationSaved
          ? "rgba(34, 197, 94, 0.2)"
          : "rgba(14, 165, 233, 0.22)";
        overlayCtx.lineWidth = (opts.width || 2) + 10;
        overlayCtx.lineCap = "round";
        overlayCtx.beginPath();
        overlayCtx.moveTo(start.x, start.y);
        overlayCtx.lineTo(end.x, end.y);
        overlayCtx.stroke();
      }
      if (opts.pulse) {
        overlayCtx.strokeStyle = "rgba(248, 250, 252, 0.4)";
        overlayCtx.lineWidth = (opts.width || 2) + 6;
        overlayCtx.lineCap = "round";
        overlayCtx.beginPath();
        overlayCtx.moveTo(start.x, start.y);
        overlayCtx.lineTo(end.x, end.y);
        overlayCtx.stroke();
      }
      overlayCtx.strokeStyle = opts.color;
      overlayCtx.lineWidth = opts.width || 2;
      overlayCtx.lineCap = "round";
      overlayCtx.setLineDash(
        Array.isArray(opts.dashPattern)
          ? opts.dashPattern
          : opts.dashed
            ? [6, 4]
            : [],
      );
      overlayCtx.beginPath();
      overlayCtx.moveTo(start.x, start.y);
      overlayCtx.lineTo(end.x, end.y);
      overlayCtx.stroke();

      const shouldDrawEndpointCaps =
        opts.endpointCaps || opts.calibrationReference || line.type === "ruler";
      if (shouldDrawEndpointCaps) {
        const dx = end.x - start.x;
        const dy = end.y - start.y;
        const length = Math.hypot(dx, dy);
        if (length > 1) {
          const nx = -dy / length;
          const ny = dx / length;
          const capLength = opts.calibrationReference ? 18 : opts.highlightHandles ? 16 : 13;
          const capHalf = capLength * 0.5;
          const capPoints = [
            {
              x: start.x,
              y: start.y,
              x1: start.x - nx * capHalf,
              y1: start.y - ny * capHalf,
              x2: start.x + nx * capHalf,
              y2: start.y + ny * capHalf,
            },
            {
              x: end.x,
              y: end.y,
              x1: end.x - nx * capHalf,
              y1: end.y - ny * capHalf,
              x2: end.x + nx * capHalf,
              y2: end.y + ny * capHalf,
            },
          ];

          overlayCtx.setLineDash([]);
          overlayCtx.lineCap = "round";
          overlayCtx.strokeStyle = "rgba(248, 250, 252, 0.92)";
          overlayCtx.lineWidth = Math.max(3.2, (opts.width || 2) + 1.6);
          overlayCtx.beginPath();
          capPoints.forEach((point) => {
            overlayCtx.moveTo(point.x1, point.y1);
            overlayCtx.lineTo(point.x2, point.y2);
          });
          overlayCtx.stroke();

          overlayCtx.strokeStyle = opts.color;
          overlayCtx.lineWidth = Math.max(1.5, (opts.width || 2) * 0.8);
          overlayCtx.beginPath();
          capPoints.forEach((point) => {
            overlayCtx.moveTo(point.x1, point.y1);
            overlayCtx.lineTo(point.x2, point.y2);
          });
          overlayCtx.stroke();

          overlayCtx.fillStyle = "rgba(248, 250, 252, 0.96)";
          fillCircleMarkers(
            overlayCtx,
            capPoints.map((point) => ({ x: point.x, y: point.y, radius: 3.8 })),
          );
          overlayCtx.fillStyle = opts.color;
          fillCircleMarkers(
            overlayCtx,
            capPoints.map((point) => ({ x: point.x, y: point.y, radius: 2.1 })),
          );
        }
      }

      if (line.type === "ruler" && Number.isFinite(line.presetMm)) {
        const dx = end.x - start.x;
        const dy = end.y - start.y;
        const length = Math.hypot(dx, dy);
        if (length > 1) {
          const ux = dx / length;
          const uy = dy / length;
          const nx = -uy;
          const ny = ux;
          const tickCount = clamp(Math.round(line.presetMm / 10), 5, 100);
          overlayCtx.strokeStyle = opts.color;
          overlayCtx.lineWidth = Math.max(1, (opts.width || 2) * 0.7);
          overlayCtx.beginPath();
          for (let index = 0; index <= tickCount; index += 1) {
            const t = index / tickCount;
            const px = start.x + dx * t;
            const py = start.y + dy * t;
            const tickLength =
              index === 0 || index === tickCount
                ? 16
                : index % 5 === 0
                  ? 12
                  : 8;
            overlayCtx.moveTo(
              px - nx * (tickLength * 0.5),
              py - ny * (tickLength * 0.5),
            );
            overlayCtx.lineTo(
              px + nx * (tickLength * 0.5),
              py + ny * (tickLength * 0.5),
            );
          }
          overlayCtx.stroke();
        }
      }

      if (opts.showTouchHalo) {
        overlayCtx.fillStyle = "rgba(248, 250, 252, 0.18)";
        fillCircleMarkers(overlayCtx, [
          { x: start.x, y: start.y, radius: 16 },
          { x: end.x, y: end.y, radius: 16 },
        ]);
      }

      overlayCtx.fillStyle = opts.color;
      fillCircleMarkers(overlayCtx, [
        {
          x: start.x,
          y: start.y,
          radius: (opts.handleRadius || 3) + (opts.calibrationReference ? 0.7 : 0),
        },
        {
          x: end.x,
          y: end.y,
          radius: (opts.handleRadius || 3) + (opts.calibrationReference ? 0.7 : 0),
        },
      ]);

      if (opts.highlightHandles) {
        overlayCtx.strokeStyle = "#f8fafc";
        overlayCtx.lineWidth = opts.calibrationReference ? 1.9 : 1.5;
        strokeCircleMarkers(overlayCtx, [
          {
            x: start.x,
            y: start.y,
            radius:
              (opts.handleRadius || 3) +
              1.2 +
              (opts.calibrationReference ? 0.8 : 0),
          },
          {
            x: end.x,
            y: end.y,
            radius:
              (opts.handleRadius || 3) +
              1.2 +
              (opts.calibrationReference ? 0.8 : 0),
          },
        ]);
      }

      overlayCtx.restore();

      // ── headDiameter: 2 lingkaran konsentris + HRC crosshair ────────
      if (line.type === "headDiameter") {
        const mx = (start.x + end.x) / 2;
        const my = (start.y + end.y) / 2;
        const rInner = Math.hypot(end.x - start.x, end.y - start.y) / 2;

        if (rInner > 2) {
          // Hitung offset 2mm ke screen pixels
          const imagePx = getLineLength(line);
          const screenPerImg = imagePx > 0 ? rInner / (imagePx / 2) : 1;
          const offsetMm = 2;
          const rOuter = rInner + (mmPerPixel ? (offsetMm / mmPerPixel) * screenPerImg : 7);

          overlayCtx.save();
          overlayCtx.lineCap = "round";

          // Lingkaran dalam — solid, full opacity
          overlayCtx.strokeStyle = opts.color;
          overlayCtx.lineWidth = opts.width || 2;
          overlayCtx.setLineDash([]);
          overlayCtx.globalAlpha = 0.9;
          overlayCtx.beginPath();
          overlayCtx.arc(mx, my, rInner, 0, Math.PI * 2);
          overlayCtx.stroke();

          // Lingkaran luar — dash, 50% opacity (2mm gap)
          overlayCtx.lineWidth = (opts.width || 2) * 0.75;
          overlayCtx.setLineDash([5, 3]);
          overlayCtx.globalAlpha = 0.5;
          overlayCtx.beginPath();
          overlayCtx.arc(mx, my, rOuter, 0, Math.PI * 2);
          overlayCtx.stroke();

          // HRC crosshair di tengah
          overlayCtx.setLineDash([]);
          overlayCtx.globalAlpha = 1;
          overlayCtx.lineWidth = 1.5;
          const cs = 7;
          overlayCtx.beginPath();
          overlayCtx.moveTo(mx - cs, my); overlayCtx.lineTo(mx + cs, my);
          overlayCtx.moveTo(mx, my - cs); overlayCtx.lineTo(mx, my + cs);
          overlayCtx.stroke();

          // Titik pusat
          overlayCtx.fillStyle = opts.color;
          overlayCtx.beginPath();
          overlayCtx.arc(mx, my, 2.5, 0, Math.PI * 2);
          overlayCtx.fill();

          overlayCtx.restore();

          // Label HRC di atas lingkaran luar
          drawTag(overlayCtx, mx, my - rOuter - 10, "HRC", opts.color, {
            bgOpacity: 0.9, fontSize: 8, paddingX: 3, paddingY: 1.5, radius: 3,
          });
        }
      }

      // ── femurAxis: arrowheads at both ends ────────────────────────────
      if (line.type === "femurAxis") {
        const dx = end.x - start.x;
        const dy = end.y - start.y;
        const len = Math.hypot(dx, dy);
        if (len > 24) {
          const ux = dx / len;
          const uy = dy / len;
          const aLen = 10;
          const aW = 5;
          overlayCtx.save();
          overlayCtx.strokeStyle = opts.color;
          overlayCtx.lineWidth = (opts.width || 2) * 0.85;
          overlayCtx.lineCap = "round";
          overlayCtx.setLineDash([]);
          // Arrow at start (backward)
          overlayCtx.beginPath();
          overlayCtx.moveTo(start.x, start.y);
          overlayCtx.lineTo(start.x + ux * aLen - uy * aW, start.y + uy * aLen + ux * aW);
          overlayCtx.moveTo(start.x, start.y);
          overlayCtx.lineTo(start.x + ux * aLen + uy * aW, start.y + uy * aLen - ux * aW);
          overlayCtx.stroke();
          // Arrow at end (forward)
          overlayCtx.beginPath();
          overlayCtx.moveTo(end.x, end.y);
          overlayCtx.lineTo(end.x - ux * aLen - uy * aW, end.y - uy * aLen + ux * aW);
          overlayCtx.moveTo(end.x, end.y);
          overlayCtx.lineTo(end.x - ux * aLen + uy * aW, end.y - uy * aLen - ux * aW);
          overlayCtx.stroke();
          overlayCtx.restore();
        }
      }

      const label = getLineLabelText(line);
      const lineMidX = (start.x + end.x) / 2;
      const lineMidY = (start.y + end.y) / 2;
      const midX = lineMidX + (line.labelOffsetX ?? DEFAULT_LINE_LABEL_OFFSET_X);
      const midY = lineMidY + (line.labelOffsetY ?? DEFAULT_LINE_LABEL_OFFSET_Y);

      const offsetX = line.labelOffsetX ?? DEFAULT_LINE_LABEL_OFFSET_X;
      const offsetY = line.labelOffsetY ?? DEFAULT_LINE_LABEL_OFFSET_Y;
      if (Math.abs(offsetX) > 2 || Math.abs(offsetY) > 2) {
        overlayCtx.save();
        overlayCtx.beginPath();
        overlayCtx.moveTo(lineMidX, lineMidY);
        overlayCtx.lineTo(midX, midY);
        overlayCtx.setLineDash([3, 4]);
        overlayCtx.lineWidth = 1;
        overlayCtx.strokeStyle = opts.color;
        overlayCtx.globalAlpha = 0.45;
        overlayCtx.stroke();
        overlayCtx.restore();
      }

      drawTag(overlayCtx, midX, midY, label, opts.color, {
        bgOpacity: Math.max(
          0.2,
          Math.min(
            1,
            (line.labelOpacity ?? DEFAULT_LABEL_OPACITY) +
              (opts.highlightHandles ? 0.1 : 0),
          ),
        ),
        fontSize: 9,
        paddingX: 4,
        paddingY: 2,
        radius: 4,
      });
      if (opts.calibrationReference) {
        drawTag(
          overlayCtx,
          midX,
          midY - 18,
          opts.calibrationSaved ? "CAL AKTIF" : "REF KALIBRASI",
          opts.color,
          {
            bgOpacity: opts.calibrationSaved ? 0.8 : 0.68,
            borderOpacity: 0.98,
            fontSize: 8,
            paddingX: 4,
            paddingY: 1.5,
            radius: 999,
          },
        );
      }
    };

    for (const line of lines) {
      const isSelected = line.id === selectedLineId;
      const isPulsing =
        selectionPulse?.type === "line" && selectionPulse.id === line.id;
      const isCalibration = line.id === calibrationLineId;
      const isCalibrationReference =
        calibrationMode === "line" && calibrationReferenceLine?.id === line.id;
      const isLocked = isLineLocked(line.id);
      const style = getLineVisualStyle(line, {
        isSelected,
        isPulsing,
        isLocked,
        isCalibration,
        isCalibrationReference,
      });

      drawLine(line, {
        color: style.color,
        width: style.width,
        dashPattern: style.dashPattern,
        handleRadius:
          (isSelected || isPulsing) && !isLocked
            ? isCoarsePointer
              ? 6.6
              : 4.9
            : 3,
        highlightHandles: (isSelected || isPulsing) && !isLocked,
        dashed: isLocked,
        showTouchHalo: isSelected && !isLocked && isCoarsePointer,
        pulse: isPulsing,
        endpointCaps: (isSelected || isPulsing) && !isLocked,
        calibrationReference: isCalibrationReference,
        calibrationSaved: isCalibration,
        assistHandleKey:
          mobileHandleAssist?.lineId === line.id
            ? mobileHandleAssist.handleKey
            : null,
      });
    }

    for (const angle of angles) {
      const p1 = imageToScreenPoint(angle.p1.x, angle.p1.y);
      const p2 = imageToScreenPoint(angle.p2.x, angle.p2.y);
      const p3 = imageToScreenPoint(angle.p3.x, angle.p3.y);
      const value = getAngleDegrees(angle.p1, angle.p2, angle.p3);
      const isSelected = angle.id === selectedAngleId;
      const isHovered =
        hoveredMeasurementInfo?.type === "angle" &&
        hoveredMeasurementInfo.id === angle.id;
      const isPulsing =
        selectionPulse?.type === "angle" && selectionPulse.id === angle.id;
      const isEmphasized = isSelected || isPulsing;
      const showExpandedInfo = isSelected || isHovered;
      const color = angle.color || DEFAULT_ANGLE_COLOR;
      const strokeWidth = Math.max(
        1.5,
        Number.isFinite(angle.strokeWidth)
          ? angle.strokeWidth
          : DEFAULT_ANGLE_STROKE_WIDTH,
      );
      const labelOffsetX = Number.isFinite(angle.labelOffsetX)
        ? angle.labelOffsetX
        : DEFAULT_ANGLE_LABEL_OFFSET_X;
      const labelOffsetY = Number.isFinite(angle.labelOffsetY)
        ? angle.labelOffsetY
        : DEFAULT_ANGLE_LABEL_OFFSET_Y;
      const resultOpacity = getAngleResultOpacity(angle);
      const arcGeometry = getAngleArcGeometry(p1, p2, p3);
      const assistGeometry =
        mobileAngleHandleAssist?.angleId === angle.id
          ? getMobileAngleHandleAssistGeometry(
              angle,
              mobileAngleHandleAssist.handleKey,
            )
          : null;

      overlayCtx.save();
      if (assistGeometry) {
        overlayCtx.fillStyle = "rgba(226, 232, 240, 0.34)";
        overlayCtx.beginPath();
        overlayCtx.arc(
          assistGeometry.centerX,
          assistGeometry.centerY,
          MOBILE_LINE_HANDLE_ASSIST_RADIUS_SCREEN,
          0,
          Math.PI * 2,
        );
        overlayCtx.fill();
        overlayCtx.strokeStyle = "rgba(248, 250, 252, 0.65)";
        overlayCtx.lineWidth = 1.5;
        overlayCtx.beginPath();
        overlayCtx.arc(
          assistGeometry.centerX,
          assistGeometry.centerY,
          MOBILE_LINE_HANDLE_ASSIST_RADIUS_SCREEN,
          0,
          Math.PI * 2,
        );
        overlayCtx.stroke();
      }
      if (isPulsing) {
        overlayCtx.strokeStyle = "rgba(248, 250, 252, 0.38)";
        overlayCtx.lineWidth = strokeWidth + 5.2;
        overlayCtx.lineCap = "round";
        overlayCtx.lineJoin = "round";
        overlayCtx.beginPath();
        overlayCtx.moveTo(p2.x, p2.y);
        overlayCtx.lineTo(p1.x, p1.y);
        overlayCtx.moveTo(p2.x, p2.y);
        overlayCtx.lineTo(p3.x, p3.y);
        overlayCtx.stroke();
      }
      overlayCtx.strokeStyle = color;
      overlayCtx.lineWidth = strokeWidth + (isEmphasized ? 0.35 : 0);
      overlayCtx.lineCap = "round";
      overlayCtx.lineJoin = "round";
      overlayCtx.beginPath();
      overlayCtx.moveTo(p2.x, p2.y);
      overlayCtx.lineTo(p1.x, p1.y);
      overlayCtx.moveTo(p2.x, p2.y);
      overlayCtx.lineTo(p3.x, p3.y);
      overlayCtx.stroke();

      if (arcGeometry) {
        overlayCtx.beginPath();
        overlayCtx.lineWidth = Math.max(1.2, strokeWidth - 0.35);
        overlayCtx.arc(
          p2.x,
          p2.y,
          arcGeometry.radius,
          arcGeometry.startAngle,
          arcGeometry.endAngle,
          arcGeometry.counterclockwise,
        );
        overlayCtx.stroke();
      }

      overlayCtx.fillStyle = color;
      fillCircleMarkers(overlayCtx, [
        { x: p1.x, y: p1.y, radius: isEmphasized ? 4.4 : 3.8 },
        { x: p2.x, y: p2.y, radius: isEmphasized ? 5.1 : 4.5 },
        { x: p3.x, y: p3.y, radius: isEmphasized ? 4.4 : 3.8 },
      ]);
      overlayCtx.restore();

      drawTag(
        overlayCtx,
        p2.x + labelOffsetX,
        p2.y + labelOffsetY,
        getAngleCanvasLabelText(angle, showExpandedInfo),
        color,
        {
          bgOpacity: Math.max(
            0.08,
            Math.min(1, resultOpacity + (showExpandedInfo ? 0.14 : 0)),
          ),
          borderOpacity: Math.max(
            0.42,
            Math.min(
              0.96,
              resultOpacity +
                (isEmphasized ? 0.28 : 0.2) +
                (isHovered ? 0.08 : 0),
            ),
          ),
          fontSize: 9,
          paddingX: 4,
          paddingY: 2,
          radius: 4,
        },
      );
    }

    for (const circle of circles) {
      const center = imageToScreenPoint(circle.cx, circle.cy);
      const edge = imageToScreenPoint(circle.cx + circle.radius, circle.cy);
      const radiusPx = Math.hypot(edge.x - center.x, edge.y - center.y);
      const isSelected = circle.id === selectedCircleId;
      const isHovered =
        hoveredMeasurementInfo?.type === "circle" &&
        hoveredMeasurementInfo.id === circle.id;
      const isPulsing =
        selectionPulse?.type === "circle" && selectionPulse.id === circle.id;
      const isEmphasized = isSelected || isPulsing;
      const showExpandedInfo = isSelected || isHovered;
      const color = circle.color || (isSelected ? "#a78bfa" : DEFAULT_CIRCLE_COLOR);
      const strokeWidth = Math.max(
        1.2,
        Number.isFinite(circle.strokeWidth)
          ? circle.strokeWidth
          : DEFAULT_CIRCLE_STROKE_WIDTH,
      );

      overlayCtx.save();
      if (isPulsing) {
        overlayCtx.strokeStyle = "rgba(248, 250, 252, 0.38)";
        overlayCtx.lineWidth = 7;
        overlayCtx.beginPath();
        overlayCtx.arc(center.x, center.y, radiusPx, 0, Math.PI * 2);
        overlayCtx.stroke();
      }
      overlayCtx.strokeStyle = color;
      overlayCtx.lineWidth = strokeWidth + (isEmphasized ? 0.6 : 0);
      overlayCtx.beginPath();
      overlayCtx.arc(center.x, center.y, radiusPx, 0, Math.PI * 2);
      overlayCtx.stroke();
      // Diameter line at user-defined angle
      const dAngleRad = ((circle.diameterAngle ?? 0) * Math.PI) / 180;
      const dCos = Math.cos(dAngleRad);
      const dSin = Math.sin(dAngleRad);
      // Always show diameter line (faint when not emphasized)
      overlayCtx.save();
      overlayCtx.setLineDash([6, 4]);
      overlayCtx.lineWidth = isEmphasized ? strokeWidth : Math.max(0.8, strokeWidth * 0.5);
      overlayCtx.strokeStyle = color;
      overlayCtx.globalAlpha = isEmphasized ? 1 : 0.4;
      overlayCtx.beginPath();
      overlayCtx.moveTo(center.x - radiusPx * dCos, center.y - radiusPx * dSin);
      overlayCtx.lineTo(center.x + radiusPx * dCos, center.y + radiusPx * dSin);
      overlayCtx.stroke();
      overlayCtx.restore();
      overlayCtx.setLineDash([]);

      overlayCtx.fillStyle = color;
      overlayCtx.beginPath();
      overlayCtx.arc(center.x, center.y, isEmphasized ? 4.6 : 4, 0, Math.PI * 2);
      overlayCtx.fill();
      if (isEmphasized) {
        // 2 diameter endpoint handles (rotatable) + 2 perpendicular radius handles
        const perpCos = Math.cos(dAngleRad + Math.PI / 2);
        const perpSin = Math.sin(dAngleRad + Math.PI / 2);
        const handles = [
          { x: center.x + radiusPx * dCos,    y: center.y + radiusPx * dSin,    isDia: true },
          { x: center.x - radiusPx * dCos,    y: center.y - radiusPx * dSin,    isDia: true },
          { x: center.x + radiusPx * perpCos, y: center.y + radiusPx * perpSin, isDia: false },
          { x: center.x - radiusPx * perpCos, y: center.y - radiusPx * perpSin, isDia: false },
        ];
        overlayCtx.lineWidth = 1.5;
        for (const handle of handles) {
          overlayCtx.fillStyle = handle.isDia ? color : "#f8fafc";
          overlayCtx.strokeStyle = color;
          overlayCtx.beginPath();
          overlayCtx.arc(handle.x, handle.y, 4.8, 0, Math.PI * 2);
          overlayCtx.fill();
          overlayCtx.stroke();
        }
      }
      overlayCtx.restore();

      const labelAnchorX = center.x;
      const labelAnchorY = center.y - radiusPx - 12;
      const labelX = labelAnchorX + (circle.labelOffsetX ?? 0);
      const labelY = labelAnchorY + (circle.labelOffsetY ?? 0);
      const hasLabelOffset = Math.abs(circle.labelOffsetX ?? 0) > 2 || Math.abs(circle.labelOffsetY ?? 0) > 2;
      if (hasLabelOffset) {
        overlayCtx.save();
        overlayCtx.beginPath();
        overlayCtx.moveTo(labelAnchorX, center.y - radiusPx);
        overlayCtx.lineTo(labelX, labelY);
        overlayCtx.setLineDash([3, 4]);
        overlayCtx.lineWidth = 1;
        overlayCtx.strokeStyle = color;
        overlayCtx.globalAlpha = 0.45;
        overlayCtx.stroke();
        overlayCtx.restore();
      }
      drawTag(
        overlayCtx,
        labelX,
        labelY,
        getCircleCanvasLabelText(
          circle,
          mmPerPixel,
          measurementUnit,
          showExpandedInfo,
        ),
        color,
        {
          bgOpacity: showExpandedInfo ? 0.72 : 0.34,
          borderOpacity: showExpandedInfo ? 0.96 : 0.82,
          fontSize: 9,
          paddingX: 4,
          paddingY: 2,
          radius: 4,
        },
      );
    }

    for (const item of hkaSets) {
      const measurement = getHkaMeasurementResult(item);
      const isSelected = item.id === selectedHkaId;
      const isHovered =
        hoveredMeasurementInfo?.type === "hka" &&
        hoveredMeasurementInfo.id === item.id;
      const isPulsing =
        selectionPulse?.type === "hka" && selectionPulse.id === item.id;
      const isEmphasized = isSelected || isPulsing;
      const showExpandedInfo = isSelected || isHovered;
      const lineColor = getHkaLineColor(item);
      const color = lineColor;
      if (item.mode === "fta") {
        if (
          !item.femurMidshaft10cm ||
          !item.femoralNotch ||
          !item.tibiaMidshaft4cm ||
          !item.tibiaMidshaft10cm
        ) {
          continue;
        }
        const femurShaft = imageToScreenPoint(
          item.femurMidshaft10cm.x,
          item.femurMidshaft10cm.y,
        );
        const notch = imageToScreenPoint(
          item.femoralNotch.x,
          item.femoralNotch.y,
        );
        const tibia4 = imageToScreenPoint(
          item.tibiaMidshaft4cm.x,
          item.tibiaMidshaft4cm.y,
        );
        const tibia10 = imageToScreenPoint(
          item.tibiaMidshaft10cm.x,
          item.tibiaMidshaft10cm.y,
        );
        const baseStrokeWidth = Math.max(
          1.2,
          Number.isFinite(item.strokeWidth)
            ? item.strokeWidth
            : DEFAULT_HKA_STROKE_WIDTH,
        );
        const strokeWidth = baseStrokeWidth + (isEmphasized ? 0.55 : 0);
        const labelAnchor = {
          x: (notch.x + tibia4.x) / 2,
          y: (notch.y + tibia4.y) / 2,
        };
        const labelOffsetX = Number.isFinite(item.labelOffsetX)
          ? item.labelOffsetX
          : DEFAULT_HKA_LABEL_OFFSET_X;
        const labelOffsetY = Number.isFinite(item.labelOffsetY)
          ? item.labelOffsetY
          : DEFAULT_HKA_LABEL_OFFSET_Y;

        overlayCtx.save();
        if (isPulsing) {
          overlayCtx.strokeStyle = "rgba(248, 250, 252, 0.38)";
          overlayCtx.lineWidth = strokeWidth + 5.2;
          overlayCtx.lineCap = "round";
          overlayCtx.lineJoin = "round";
          overlayCtx.beginPath();
          overlayCtx.moveTo(femurShaft.x, femurShaft.y);
          overlayCtx.lineTo(notch.x, notch.y);
          overlayCtx.moveTo(tibia4.x, tibia4.y);
          overlayCtx.lineTo(tibia10.x, tibia10.y);
          overlayCtx.stroke();
        }
        overlayCtx.strokeStyle = color;
        overlayCtx.fillStyle = color;
        overlayCtx.lineWidth = strokeWidth;
        overlayCtx.lineCap = "round";
        overlayCtx.lineJoin = "round";
        overlayCtx.beginPath();
        overlayCtx.moveTo(femurShaft.x, femurShaft.y);
        overlayCtx.lineTo(notch.x, notch.y);
        overlayCtx.moveTo(tibia4.x, tibia4.y);
        overlayCtx.lineTo(tibia10.x, tibia10.y);
        overlayCtx.stroke();
        fillCircleMarkers(overlayCtx, [
          { x: femurShaft.x, y: femurShaft.y, radius: isEmphasized ? 4.2 : 3.6 },
          { x: notch.x, y: notch.y, radius: isEmphasized ? 4.8 : 4.2 },
          { x: tibia4.x, y: tibia4.y, radius: isEmphasized ? 4.8 : 4.2 },
          { x: tibia10.x, y: tibia10.y, radius: isEmphasized ? 4.2 : 3.6 },
        ]);
        overlayCtx.restore();

        drawTag(
          overlayCtx,
          labelAnchor.x + labelOffsetX,
          labelAnchor.y + labelOffsetY,
          getHkaCanvasLabelText(measurement, showExpandedInfo),
          color,
          {
            bgOpacity: showExpandedInfo ? 0.72 : 0.34,
            borderOpacity: showExpandedInfo ? 0.96 : 0.82,
            fontSize: 9,
            paddingX: 4,
            paddingY: 2,
            radius: 4,
          },
        );
        continue;
      }

      // ── JLA mode rendering ─────────────────────────────────────────────────
      if (item.mode === "jla") {
        if (!item.hip || !item.knee || !item.ankle) continue;
        const jlaHip   = imageToScreenPoint(item.hip.x,   item.hip.y);
        const jlaKnee  = imageToScreenPoint(item.knee.x,  item.knee.y);
        const jlaAnkle = imageToScreenPoint(item.ankle.x, item.ankle.y);
        const jlaMFC = item.femCondyleMedial  ? imageToScreenPoint(item.femCondyleMedial.x,  item.femCondyleMedial.y)  : null;
        const jlaLFC = item.femCondyleLateral ? imageToScreenPoint(item.femCondyleLateral.x, item.femCondyleLateral.y) : null;
        const jlaMTP = item.tibPlateauMedial  ? imageToScreenPoint(item.tibPlateauMedial.x,  item.tibPlateauMedial.y)  : null;
        const jlaLTP = item.tibPlateauLateral ? imageToScreenPoint(item.tibPlateauLateral.x, item.tibPlateauLateral.y) : null;
        const baseStrokeWidth = Math.max(1.2, Number.isFinite(item.strokeWidth) ? item.strokeWidth : DEFAULT_HKA_STROKE_WIDTH);
        const strokeWidth = baseStrokeWidth + (isEmphasized ? 0.55 : 0);
        const labelOffsetX = Number.isFinite(item.labelOffsetX) ? item.labelOffsetX : DEFAULT_HKA_LABEL_OFFSET_X;
        const labelOffsetY = Number.isFinite(item.labelOffsetY) ? item.labelOffsetY : DEFAULT_HKA_LABEL_OFFSET_Y;

        overlayCtx.save();
        overlayCtx.lineCap = "round";
        overlayCtx.lineJoin = "round";

        // Femoral mechanical axis
        overlayCtx.strokeStyle = "#facc15";
        overlayCtx.lineWidth = strokeWidth;
        overlayCtx.beginPath();
        overlayCtx.moveTo(jlaHip.x, jlaHip.y);
        overlayCtx.lineTo(jlaKnee.x, jlaKnee.y);
        overlayCtx.stroke();

        // Tibial mechanical axis
        overlayCtx.strokeStyle = "#22c55e";
        overlayCtx.lineWidth = strokeWidth;
        overlayCtx.beginPath();
        overlayCtx.moveTo(jlaKnee.x, jlaKnee.y);
        overlayCtx.lineTo(jlaAnkle.x, jlaAnkle.y);
        overlayCtx.stroke();

        // Condyle line dashed (MFC–LFC extended)
        if (jlaMFC && jlaLFC) {
          const condExt = jlaExtendLine(jlaMFC, jlaLFC, 100);
          overlayCtx.strokeStyle = "#38bdf8";
          overlayCtx.lineWidth = Math.max(1, strokeWidth - 0.5);
          overlayCtx.setLineDash([5, 4]);
          overlayCtx.beginPath();
          overlayCtx.moveTo(condExt.a.x, condExt.a.y);
          overlayCtx.lineTo(condExt.b.x, condExt.b.y);
          overlayCtx.stroke();
          overlayCtx.setLineDash([]);
        }

        // Plateau line dashed (MTP–LTP extended)
        if (jlaMTP && jlaLTP) {
          const platExt = jlaExtendLine(jlaMTP, jlaLTP, 100);
          overlayCtx.strokeStyle = "#14b8a6";
          overlayCtx.lineWidth = Math.max(1, strokeWidth - 0.5);
          overlayCtx.setLineDash([5, 4]);
          overlayCtx.beginPath();
          overlayCtx.moveTo(platExt.a.x, platExt.a.y);
          overlayCtx.lineTo(platExt.b.x, platExt.b.y);
          overlayCtx.stroke();
          overlayCtx.setLineDash([]);
        }

        // LDFA arc at femoral axis × condyle line intersection
        if (jlaMFC && jlaLFC) {
          const condFar = jlaExtendLine(jlaMFC, jlaLFC, 500);
          const ldfaV = jlaLineIntersect(jlaHip, jlaKnee, condFar.a, condFar.b);
          if (ldfaV) {
            const cDir = { x: jlaLFC.x - jlaMFC.x, y: jlaLFC.y - jlaMFC.y };
            const fDir = { x: jlaHip.x - jlaKnee.x, y: jlaHip.y - jlaKnee.y };
            const r = Math.max(16, Math.min(36, Math.hypot(cDir.x, cDir.y) * 0.22));
            jlaDrawAngleArc(overlayCtx, ldfaV,
              { x: ldfaV.x + cDir.x * 0.5, y: ldfaV.y + cDir.y * 0.5 },
              { x: ldfaV.x + fDir.x * 0.5, y: ldfaV.y + fDir.y * 0.5 },
              r, "LDFA", "#38bdf8");
          }
        }

        // MPTA arc at tibial axis × plateau line intersection
        if (jlaMTP && jlaLTP) {
          const platFar = jlaExtendLine(jlaMTP, jlaLTP, 500);
          const mptaV = jlaLineIntersect(jlaKnee, jlaAnkle, platFar.a, platFar.b);
          if (mptaV) {
            const pDir = { x: jlaMTP.x - jlaLTP.x, y: jlaMTP.y - jlaLTP.y };
            const tDir = { x: jlaAnkle.x - jlaKnee.x, y: jlaAnkle.y - jlaKnee.y };
            const r = Math.max(16, Math.min(36, Math.hypot(pDir.x, pDir.y) * 0.22));
            jlaDrawAngleArc(overlayCtx, mptaV,
              { x: mptaV.x + pDir.x * 0.5, y: mptaV.y + pDir.y * 0.5 },
              { x: mptaV.x + tDir.x * 0.5, y: mptaV.y + tDir.y * 0.5 },
              r, "MPTA", "#14b8a6");
          }
        }

        // JLCA arc at condyle × plateau intersection
        if (jlaMFC && jlaLFC && jlaMTP && jlaLTP) {
          const jlcaV = jlaLineIntersect(jlaMFC, jlaLFC, jlaMTP, jlaLTP);
          if (jlcaV) {
            const cDir = { x: jlaLFC.x - jlaMFC.x, y: jlaLFC.y - jlaMFC.y };
            const pDir = { x: jlaLTP.x - jlaMTP.x, y: jlaLTP.y - jlaMTP.y };
            jlaDrawAngleArc(overlayCtx, jlcaV,
              { x: jlcaV.x + cDir.x * 0.3, y: jlcaV.y + cDir.y * 0.3 },
              { x: jlcaV.x + pDir.x * 0.3, y: jlcaV.y + pDir.y * 0.3 },
              20, "JLCA", "#e879f9");
          }
        }

        // Circle markers
        overlayCtx.fillStyle = "#facc15";
        fillCircleMarkers(overlayCtx, [{ x: jlaHip.x,   y: jlaHip.y,   radius: isEmphasized ? 4.2 : 3.6 }]);
        overlayCtx.fillStyle = "#f97316";
        fillCircleMarkers(overlayCtx, [{ x: jlaKnee.x,  y: jlaKnee.y,  radius: isEmphasized ? 5   : 4.4 }]);
        overlayCtx.fillStyle = "#22c55e";
        fillCircleMarkers(overlayCtx, [{ x: jlaAnkle.x, y: jlaAnkle.y, radius: isEmphasized ? 4.2 : 3.6 }]);
        if (jlaMFC) { overlayCtx.fillStyle = "#38bdf8"; fillCircleMarkers(overlayCtx, [{ x: jlaMFC.x, y: jlaMFC.y, radius: 3.0 }]); }
        if (jlaLFC) { overlayCtx.fillStyle = "#38bdf8"; fillCircleMarkers(overlayCtx, [{ x: jlaLFC.x, y: jlaLFC.y, radius: 3.0 }]); }
        if (jlaMTP) { overlayCtx.fillStyle = "#14b8a6"; fillCircleMarkers(overlayCtx, [{ x: jlaMTP.x, y: jlaMTP.y, radius: 3.0 }]); }
        if (jlaLTP) { overlayCtx.fillStyle = "#14b8a6"; fillCircleMarkers(overlayCtx, [{ x: jlaLTP.x, y: jlaLTP.y, radius: 3.0 }]); }

        overlayCtx.restore();

        drawTag(
          overlayCtx,
          jlaKnee.x + labelOffsetX,
          jlaKnee.y + labelOffsetY,
          getHkaCanvasLabelText(measurement, showExpandedInfo),
          color,
          { bgOpacity: showExpandedInfo ? 0.72 : 0.34, borderOpacity: showExpandedInfo ? 0.96 : 0.82, fontSize: 9, paddingX: 4, paddingY: 2, radius: 4 },
        );
        continue;
      }

      if (!item.hip || !item.knee || !item.ankle) continue;
      const hip = imageToScreenPoint(item.hip.x, item.hip.y);
      const knee = imageToScreenPoint(item.knee.x, item.knee.y);
      const ankle = imageToScreenPoint(item.ankle.x, item.ankle.y);
      const angleDeg = measurement.absoluteDeviation;
      const arcGeometry = getAngleArcGeometry(hip, knee, ankle);
      const showArc = item.showArc !== false;
      const labelOffsetX = Number.isFinite(item.labelOffsetX)
        ? item.labelOffsetX
        : DEFAULT_HKA_LABEL_OFFSET_X;
      const labelOffsetY = Number.isFinite(item.labelOffsetY)
        ? item.labelOffsetY
        : DEFAULT_HKA_LABEL_OFFSET_Y;
      const baseStrokeWidth = Math.max(
        1.2,
        Number.isFinite(item.strokeWidth)
          ? item.strokeWidth
          : DEFAULT_HKA_STROKE_WIDTH,
      );
      const strokeWidth = baseStrokeWidth + (isEmphasized ? 0.55 : 0);
      const kneeGap = isEmphasized ? 10 : 7;
      const hipVector = { x: hip.x - knee.x, y: hip.y - knee.y };
      const ankleVector = { x: ankle.x - knee.x, y: ankle.y - knee.y };
      const hipLength = Math.hypot(hipVector.x, hipVector.y) || 1;
      const ankleLength = Math.hypot(ankleVector.x, ankleVector.y) || 1;
      const hipNearKnee = {
        x:
          knee.x +
          (hipVector.x / hipLength) * Math.min(kneeGap, hipLength * 0.35),
        y:
          knee.y +
          (hipVector.y / hipLength) * Math.min(kneeGap, hipLength * 0.35),
      };
      const ankleNearKnee = {
        x:
          knee.x +
          (ankleVector.x / ankleLength) * Math.min(kneeGap, ankleLength * 0.35),
        y:
          knee.y +
          (ankleVector.y / ankleLength) * Math.min(kneeGap, ankleLength * 0.35),
      };
      const assistGeometry =
        mobileHkaHandleAssist?.hkaId === item.id
          ? getMobileHkaHandleAssistGeometry(
              item,
              mobileHkaHandleAssist.handleKey,
            )
          : null;

      overlayCtx.save();
      if (assistGeometry) {
        overlayCtx.fillStyle = "rgba(226, 232, 240, 0.34)";
        overlayCtx.beginPath();
        overlayCtx.arc(
          assistGeometry.centerX,
          assistGeometry.centerY,
          MOBILE_LINE_HANDLE_ASSIST_RADIUS_SCREEN,
          0,
          Math.PI * 2,
        );
        overlayCtx.fill();
        overlayCtx.strokeStyle = "rgba(248, 250, 252, 0.65)";
        overlayCtx.lineWidth = 1.5;
        overlayCtx.beginPath();
        overlayCtx.arc(
          assistGeometry.centerX,
          assistGeometry.centerY,
          MOBILE_LINE_HANDLE_ASSIST_RADIUS_SCREEN,
          0,
          Math.PI * 2,
        );
        overlayCtx.stroke();
      }
      if (isPulsing) {
        overlayCtx.strokeStyle = "rgba(248, 250, 252, 0.38)";
        overlayCtx.lineWidth = strokeWidth + 5.2;
        overlayCtx.lineCap = "round";
        overlayCtx.lineJoin = "round";
        overlayCtx.beginPath();
        overlayCtx.moveTo(hipNearKnee.x, hipNearKnee.y);
        overlayCtx.lineTo(hip.x, hip.y);
        overlayCtx.moveTo(ankleNearKnee.x, ankleNearKnee.y);
        overlayCtx.lineTo(ankle.x, ankle.y);
        overlayCtx.stroke();
      }
      overlayCtx.strokeStyle = color;
      overlayCtx.lineWidth = strokeWidth;
      overlayCtx.lineCap = "round";
      overlayCtx.lineJoin = "round";
      overlayCtx.beginPath();
      overlayCtx.moveTo(hipNearKnee.x, hipNearKnee.y);
      overlayCtx.lineTo(hip.x, hip.y);
      overlayCtx.moveTo(ankleNearKnee.x, ankleNearKnee.y);
      overlayCtx.lineTo(ankle.x, ankle.y);
      overlayCtx.stroke();

      if (showArc && arcGeometry) {
        overlayCtx.beginPath();
        overlayCtx.lineWidth = Math.max(
          1.05,
          strokeWidth - (isSelected ? 0.45 : 0.7),
        );
        overlayCtx.globalAlpha = isEmphasized ? 1 : 0.68;
        overlayCtx.arc(
          knee.x,
          knee.y,
          arcGeometry.radius,
          arcGeometry.startAngle,
          arcGeometry.endAngle,
          arcGeometry.counterclockwise,
        );
        overlayCtx.stroke();
        overlayCtx.globalAlpha = 1;
      }
      overlayCtx.fillStyle = color;
      fillCircleMarkers(overlayCtx, [
        { x: hip.x, y: hip.y, radius: isEmphasized ? 4.2 : 3.6 },
        { x: knee.x, y: knee.y, radius: isEmphasized ? 5 : 4.4 },
        { x: ankle.x, y: ankle.y, radius: isEmphasized ? 4.2 : 3.6 },
      ]);
      overlayCtx.restore();

      drawTag(
        overlayCtx,
        knee.x + labelOffsetX,
        knee.y + labelOffsetY,
        getHkaCanvasLabelText(measurement, showExpandedInfo),
        color,
        {
          bgOpacity: showExpandedInfo ? 0.72 : 0.34,
          borderOpacity: showExpandedInfo ? 0.96 : 0.82,
          fontSize: 9,
          paddingX: 4,
          paddingY: 2,
          radius: 4,
        },
      );
    }

    for (let index = 0; index < planningGuides.length; index += 1) {
      const guide = planningGuides[index];
      if (guide.hidden) continue;

      const anchorStart = imageToScreenPoint(
        guide.anchorStart.x,
        guide.anchorStart.y,
      );
      const anchorEnd = imageToScreenPoint(
        guide.anchorEnd.x,
        guide.anchorEnd.y,
      );
      const color = guide.color || getPlanningGuideAutoColor(guide);

      const geometry =
        guide.kind === "valgusCut"
          ? buildValgusCutGeometry(guide.anchorStart, guide.anchorEnd, guide)
          : guide.kind === "tibialSlope"
            ? buildTibialSlopeGeometry(
                guide.anchorStart,
                guide.anchorEnd,
                guide,
              )
            : buildTibialCutGeometry(guide.anchorStart, guide.anchorEnd, guide);

      if (!geometry) continue;

      const baseA = imageToScreenPoint(geometry.baseA.x, geometry.baseA.y);
      const baseB = imageToScreenPoint(geometry.baseB.x, geometry.baseB.y);
      const cutA = imageToScreenPoint(geometry.cutA.x, geometry.cutA.y);
      const cutB = imageToScreenPoint(geometry.cutB.x, geometry.cutB.y);
      const cutCenter = imageToScreenPoint(
        geometry.cutCenter.x,
        geometry.cutCenter.y,
      );
      const cutImgLenPx = Math.hypot(
        geometry.cutA.x - geometry.cutB.x,
        geometry.cutA.y - geometry.cutB.y,
      );
      const cutLenMm =
        mmPerPixel && cutImgLenPx > 0
          ? Math.round(cutImgLenPx * mmPerPixel)
          : null;
      const label = getPlanningGuideLabelText(guide, index, cutLenMm);
      const isSelectedGuide = guide.id === selectedPlanningGuideId;
      const isPulsingGuide =
        selectionPulse?.type === "planning" &&
        selectionPulse.id === guide.id;
      const isEmphasizedGuide = isSelectedGuide || isPulsingGuide;
      const guideStyle = getPlanningGuideVisualStyle(guide);
      const baseStrokeWidth = Math.max(
        1.2,
        Number.isFinite(guide.strokeWidth)
          ? guide.strokeWidth
          : DEFAULT_PLANNING_GUIDE_STROKE_WIDTH,
      );
      const strokeWidth = baseStrokeWidth + (isEmphasizedGuide ? 0.6 : 0);

      overlayCtx.save();
      if (isPulsingGuide) {
        overlayCtx.strokeStyle = "rgba(248, 250, 252, 0.34)";
        overlayCtx.lineWidth = strokeWidth + 4.4;
        overlayCtx.setLineDash(guideStyle.anchorDash);
        overlayCtx.beginPath();
        overlayCtx.moveTo(anchorStart.x, anchorStart.y);
        overlayCtx.lineTo(anchorEnd.x, anchorEnd.y);
        overlayCtx.stroke();
      }
      overlayCtx.strokeStyle = color;
      overlayCtx.fillStyle = color;
      overlayCtx.lineWidth = strokeWidth;
      overlayCtx.setLineDash(guideStyle.anchorDash);
      overlayCtx.beginPath();
      overlayCtx.moveTo(anchorStart.x, anchorStart.y);
      overlayCtx.lineTo(anchorEnd.x, anchorEnd.y);
      overlayCtx.stroke();

      overlayCtx.setLineDash(guideStyle.baseDash);
      overlayCtx.beginPath();
      overlayCtx.moveTo(baseA.x, baseA.y);
      overlayCtx.lineTo(baseB.x, baseB.y);
      overlayCtx.lineWidth = Math.max(1.1, strokeWidth - 0.2);
      overlayCtx.stroke();

      // Arc indicator showing the cut angle between baseline and cut line
      {
        const baseAngle = Math.atan2(baseB.y - baseA.y, baseB.x - baseA.x);
        const cutAngle = Math.atan2(cutB.y - cutA.y, cutB.x - cutA.x);
        const cutScreenLen = Math.hypot(cutB.x - cutA.x, cutB.y - cutA.y);
        const arcR = Math.max(11, Math.min(24, cutScreenLen * 0.17));
        let diff = cutAngle - baseAngle;
        while (diff > Math.PI) diff -= 2 * Math.PI;
        while (diff < -Math.PI) diff += 2 * Math.PI;
        overlayCtx.save();
        overlayCtx.strokeStyle = color;
        overlayCtx.lineWidth = Math.max(0.9, strokeWidth - 0.6);
        overlayCtx.setLineDash([]);
        overlayCtx.globalAlpha = isEmphasizedGuide ? 0.78 : 0.48;
        overlayCtx.beginPath();
        overlayCtx.arc(cutCenter.x, cutCenter.y, arcR, baseAngle, cutAngle, diff < 0);
        overlayCtx.stroke();
        overlayCtx.restore();
      }

      overlayCtx.setLineDash([]);
      overlayCtx.lineWidth = strokeWidth + 0.35;
      overlayCtx.beginPath();
      overlayCtx.moveTo(cutA.x, cutA.y);
      overlayCtx.lineTo(cutB.x, cutB.y);
      overlayCtx.stroke();

      overlayCtx.beginPath();
      overlayCtx.arc(
        anchorStart.x,
        anchorStart.y,
        isEmphasizedGuide ? 4.8 : 3.8,
        0,
        Math.PI * 2,
      );
      overlayCtx.arc(
        anchorEnd.x,
        anchorEnd.y,
        isEmphasizedGuide ? 4.8 : 3.8,
        0,
        Math.PI * 2,
      );
      overlayCtx.fill();
      const assistGeometry =
        mobilePlanningGuideHandleAssist?.guideId === guide.id
          ? getMobilePlanningGuideHandleAssistGeometry(
              guide,
              mobilePlanningGuideHandleAssist.handleKey,
            )
          : null;
      if (assistGeometry) {
        overlayCtx.fillStyle = "rgba(226, 232, 240, 0.34)";
        overlayCtx.beginPath();
        overlayCtx.arc(
          assistGeometry.centerX,
          assistGeometry.centerY,
          MOBILE_LINE_HANDLE_ASSIST_RADIUS_SCREEN,
          0,
          Math.PI * 2,
        );
        overlayCtx.fill();
        overlayCtx.strokeStyle = "rgba(248, 250, 252, 0.65)";
        overlayCtx.lineWidth = 1.5;
        overlayCtx.beginPath();
        overlayCtx.arc(
          assistGeometry.centerX,
          assistGeometry.centerY,
          MOBILE_LINE_HANDLE_ASSIST_RADIUS_SCREEN,
          0,
          Math.PI * 2,
        );
        overlayCtx.stroke();
        overlayCtx.fillStyle = color;
      }
      overlayCtx.restore();

      drawTag(
        overlayCtx,
        cutCenter.x + (guide.labelOffsetX ?? DEFAULT_GUIDE_LABEL_OFFSET_X),
        cutCenter.y + (guide.labelOffsetY ?? DEFAULT_GUIDE_LABEL_OFFSET_Y),
        label,
        color,
        {
          bgOpacity: Math.max(
            0.2,
            Math.min(
              1,
              (guide.labelOpacity ?? DEFAULT_LABEL_OPACITY) +
                (isEmphasizedGuide ? 0.14 : 0),
            ),
          ),
          fontSize: 9,
          paddingX: 4,
          paddingY: 2,
          radius: 4,
        },
      );
    }

    for (const annotation of annotations) {
      const anchor = imageToScreenPoint(annotation.x, annotation.y);
      const color = annotation.color || DEFAULT_ANNOTATION_COLOR;
      const isSelectedAnnotation = annotation.id === selectedAnnotationId;
      const isPulsingAnnotation =
        selectionPulse?.type === "annotation" &&
        selectionPulse.id === annotation.id;
      const text = annotation.text || `Anotasi #${annotation.id}`;
      overlayCtx.save();
      if (isSelectedAnnotation || isPulsingAnnotation) {
        const bounds = getTagBounds(anchor.x, anchor.y, text, {
          fontSize: annotation.fontSize || 11,
          paddingX: 7,
          paddingY: 4,
          radius: 7,
        });
        overlayCtx.strokeStyle = "rgba(248, 250, 252, 0.7)";
        overlayCtx.lineWidth = isPulsingAnnotation ? 5 : 3;
        overlayCtx.beginPath();
        overlayCtx.roundRect(
          bounds.left - 3,
          bounds.top - 3,
          bounds.right - bounds.left + 6,
          bounds.bottom - bounds.top + 6,
          10,
        );
        overlayCtx.stroke();
      }
      overlayCtx.restore();
      drawTag(overlayCtx, anchor.x, anchor.y, text, color, {
        bgOpacity: Math.max(
          0.12,
          Math.min(
            1,
            (annotation.labelOpacity ?? DEFAULT_LABEL_OPACITY) +
              (isSelectedAnnotation ? 0.18 : 0),
          ),
        ),
        borderOpacity: isSelectedAnnotation ? 1 : 0.9,
        fontSize: annotation.fontSize || 11,
        paddingX: 7,
        paddingY: 4,
        radius: 7,
      });
      if (annotation.px != null && annotation.py != null) {
        const tip = imageToScreenPoint(annotation.px, annotation.py);
        const tagBounds = getTagBounds(anchor.x, anchor.y, text, {
          fontSize: annotation.fontSize || 11,
          paddingX: 7,
          paddingY: 4,
        });
        const tw = tagBounds.right - tagBounds.left;
        const th = tagBounds.bottom - tagBounds.top;
        drawLeaderLine(overlayCtx, anchor.x, anchor.y, tw, th, tip.x, tip.y, color, isSelectedAnnotation);
      }
    }

    const activeCutLayer =
      selectedCutLayerId !== null
        ? cutLayers.find((layer) => layer.id === selectedCutLayerId) || null
        : null;
    const secondarySelectedCutLayers = cutLayers.filter(
      (layer) =>
        !layer.hidden &&
        selectedCutLayerIdsSet.has(layer.id) &&
        layer.id !== selectedCutLayerId,
    );
    for (const layer of secondarySelectedCutLayers) {
      const corners = getLayerCorners(layer);
      const layerPalette = getLayerPalette(layer.id);
      overlayCtx.save();
      overlayCtx.strokeStyle = `${layerPalette.border}cc`;
      overlayCtx.lineWidth = 1.35;
      overlayCtx.setLineDash([6, 4]);
      overlayCtx.beginPath();
      const firstCorner = imageToScreenPoint(corners[0].x, corners[0].y);
      overlayCtx.moveTo(firstCorner.x, firstCorner.y);
      for (let index = 1; index < corners.length; index += 1) {
        const nextCorner = imageToScreenPoint(
          corners[index].x,
          corners[index].y,
        );
        overlayCtx.lineTo(nextCorner.x, nextCorner.y);
      }
      overlayCtx.closePath();
      overlayCtx.stroke();
      overlayCtx.restore();
    }
    if (activeCutLayer && !activeCutLayer.hidden) {
      const isPulsingLayer =
        selectionPulse?.type === "layer" &&
        selectionPulse.id === activeCutLayer.id;
      const corners = getLayerCorners(activeCutLayer);
      const controlPoints = getLayerControlPoints(activeCutLayer);
      const edgePoints = controlPoints.filter((point) => point.type === "edge");
      const rotatePoint = controlPoints.find((point) => point.key === "rotate");
      overlayCtx.save();
      if (isPulsingLayer) {
        overlayCtx.strokeStyle = "rgba(248, 250, 252, 0.4)";
        overlayCtx.lineWidth = 8;
        overlayCtx.setLineDash([]);
        overlayCtx.beginPath();
        const pulseFirstCorner = imageToScreenPoint(corners[0].x, corners[0].y);
        overlayCtx.moveTo(pulseFirstCorner.x, pulseFirstCorner.y);
        for (let index = 1; index < corners.length; index += 1) {
          const nextCorner = imageToScreenPoint(
            corners[index].x,
            corners[index].y,
          );
          overlayCtx.lineTo(nextCorner.x, nextCorner.y);
        }
        overlayCtx.closePath();
        overlayCtx.stroke();
      }
      overlayCtx.strokeStyle = "#a855f7";
      overlayCtx.lineWidth = isPulsingLayer ? 2.8 : 2.2;
      overlayCtx.setLineDash([]);
      overlayCtx.beginPath();
      const firstCorner = imageToScreenPoint(corners[0].x, corners[0].y);
      overlayCtx.moveTo(firstCorner.x, firstCorner.y);
      for (let index = 1; index < corners.length; index += 1) {
        const nextCorner = imageToScreenPoint(
          corners[index].x,
          corners[index].y,
        );
        overlayCtx.lineTo(nextCorner.x, nextCorner.y);
      }
      overlayCtx.closePath();
      overlayCtx.stroke();

      overlayCtx.fillStyle = "#ffffff";
      overlayCtx.strokeStyle = "#a855f7";
      overlayCtx.lineWidth = 1.8;
      for (const corner of corners) {
        const screen = imageToScreenPoint(corner.x, corner.y);
        overlayCtx.beginPath();
        overlayCtx.arc(
          screen.x,
          screen.y,
          isPulsingLayer ? 8.2 : 7.4,
          0,
          Math.PI * 2,
        );
        overlayCtx.fill();
        overlayCtx.stroke();
      }
      for (const edgePoint of edgePoints) {
        const screen = imageToScreenPoint(edgePoint.x, edgePoint.y);
        overlayCtx.save();
        overlayCtx.translate(screen.x, screen.y);
        overlayCtx.rotate((activeCutLayer.rotation * Math.PI) / 180);
        const isVertical = edgePoint.key === "ml" || edgePoint.key === "mr";
        const width = isVertical ? 8 : 20;
        const height = isVertical ? 20 : 8;
        overlayCtx.beginPath();
        overlayCtx.roundRect(-width / 2, -height / 2, width, height, 4);
        overlayCtx.fill();
        overlayCtx.stroke();
        overlayCtx.restore();
      }
      if (rotatePoint) {
        const bottomMiddle = imageToScreenPoint(
          controlPoints.find((point) => point.key === "bm").x,
          controlPoints.find((point) => point.key === "bm").y,
        );
        const rotateScreen = imageToScreenPoint(rotatePoint.x, rotatePoint.y);
        overlayCtx.beginPath();
        overlayCtx.moveTo(bottomMiddle.x, bottomMiddle.y);
        overlayCtx.lineTo(rotateScreen.x, rotateScreen.y - 16);
        overlayCtx.stroke();
        overlayCtx.beginPath();
        overlayCtx.arc(rotateScreen.x, rotateScreen.y, 16, 0, Math.PI * 2);
        overlayCtx.fill();
        overlayCtx.stroke();
        overlayCtx.save();
        overlayCtx.translate(rotateScreen.x, rotateScreen.y);
        overlayCtx.rotate(((activeCutLayer.rotation || 0) * Math.PI) / 180);
        overlayCtx.strokeStyle = "#111827";
        overlayCtx.lineWidth = 1.8;
        overlayCtx.beginPath();
        overlayCtx.arc(0, 0, 6.2, Math.PI * 0.15, Math.PI * 1.3);
        overlayCtx.stroke();
        overlayCtx.beginPath();
        overlayCtx.moveTo(4.5, -5.2);
        overlayCtx.lineTo(7.2, -8);
        overlayCtx.lineTo(7.6, -3.8);
        overlayCtx.stroke();
        overlayCtx.restore();
      }
      const maskScreenPoints = getLayerMaskScreenPoints(activeCutLayer);
      if (maskScreenPoints) {
        const screenMaskPoints = maskScreenPoints.map((point) =>
          imageToScreenPoint(point.x, point.y),
        );
        overlayCtx.strokeStyle = "rgba(168, 85, 247, 0.55)";
        overlayCtx.lineWidth = 1.4;
        overlayCtx.setLineDash([4, 4]);
        traceSmoothClosedPath(
          overlayCtx,
          screenMaskPoints,
          activeCutLayer.kind === "free-line"
            ? getFreeLineCurveStrength(activeCutLayer)
            : 0,
        );
        overlayCtx.stroke();

        if (activeCutLayer.kind === "free-line") {
          const vertexPoints = getFreeLineVertexPoints(activeCutLayer);
          const curveHandles =
            selectedFreeLinePointIndex !== null
              ? getFreeLineCurveHandles(
                  activeCutLayer,
                  selectedFreeLinePointIndex,
                )
              : [];
          overlayCtx.setLineDash([]);
          for (const point of vertexPoints) {
            const screen = imageToScreenPoint(point.x, point.y);
            const isActivePoint =
              point.pointIndex === selectedFreeLinePointIndex;
            overlayCtx.fillStyle = isActivePoint ? "#fef3c7" : "#ffffff";
            overlayCtx.strokeStyle = isActivePoint ? "#d97706" : "#a855f7";
            overlayCtx.lineWidth = isActivePoint ? 2 : 1.6;
            overlayCtx.beginPath();
            overlayCtx.arc(
              screen.x,
              screen.y,
              isActivePoint ? 6.2 : 5.4,
              0,
              Math.PI * 2,
            );
            overlayCtx.fill();
            overlayCtx.stroke();
          }
          overlayCtx.strokeStyle = "rgba(249, 115, 22, 0.75)";
          overlayCtx.lineWidth = 1.2;
          for (const handle of curveHandles) {
            const anchor = imageToScreenPoint(handle.anchorX, handle.anchorY);
            const screen = imageToScreenPoint(handle.x, handle.y);
            overlayCtx.beginPath();
            overlayCtx.moveTo(anchor.x, anchor.y);
            overlayCtx.lineTo(screen.x, screen.y);
            overlayCtx.stroke();
            overlayCtx.fillStyle =
              handle.handleKey === "in" ? "#fde68a" : "#fdba74";
            overlayCtx.strokeStyle = "#c2410c";
            overlayCtx.lineWidth = 1.5;
            overlayCtx.beginPath();
            overlayCtx.arc(screen.x, screen.y, 4.8, 0, Math.PI * 2);
            overlayCtx.fill();
            overlayCtx.stroke();
          }
        }
      }
      overlayCtx.restore();
    }

    if (snapToLandmarks && activeSnapTarget) {
      const snapPoint = imageToScreenPoint(activeSnapTarget.x, activeSnapTarget.y);
      overlayCtx.save();
      if (Array.isArray(activeSnapTarget.hintSegments)) {
        overlayCtx.strokeStyle = "rgba(245, 158, 11, 0.72)";
        overlayCtx.lineWidth = 1;
        overlayCtx.setLineDash(
          activeSnapTarget.type === "tangent" ? [5, 4] : [3, 4],
        );
        for (const segment of activeSnapTarget.hintSegments) {
          if (
            !Number.isFinite(segment?.x1) ||
            !Number.isFinite(segment?.y1) ||
            !Number.isFinite(segment?.x2) ||
            !Number.isFinite(segment?.y2)
          ) {
            continue;
          }
          const start = imageToScreenPoint(segment.x1, segment.y1);
          const end = imageToScreenPoint(segment.x2, segment.y2);
          overlayCtx.beginPath();
          overlayCtx.moveTo(start.x, start.y);
          overlayCtx.lineTo(end.x, end.y);
          overlayCtx.stroke();
        }
      }
      overlayCtx.strokeStyle = "#f59e0b";
      overlayCtx.fillStyle = "rgba(245, 158, 11, 0.14)";
      overlayCtx.lineWidth = 1.4;
      overlayCtx.setLineDash([4, 4]);
      overlayCtx.beginPath();
      overlayCtx.arc(snapPoint.x, snapPoint.y, isCoarsePointer ? 16 : 12, 0, Math.PI * 2);
      overlayCtx.fill();
      overlayCtx.stroke();
      overlayCtx.setLineDash([]);
      overlayCtx.beginPath();
      overlayCtx.moveTo(snapPoint.x - 10, snapPoint.y);
      overlayCtx.lineTo(snapPoint.x + 10, snapPoint.y);
      overlayCtx.moveTo(snapPoint.x, snapPoint.y - 10);
      overlayCtx.lineTo(snapPoint.x, snapPoint.y + 10);
      overlayCtx.stroke();
      drawTag(
        overlayCtx,
        snapPoint.x,
        snapPoint.y - (isCoarsePointer ? 22 : 18),
        `SNAP ${activeSnapTarget.label}`,
        "#f59e0b",
        {
          bgOpacity: 0.78,
          borderOpacity: 0.96,
          fontSize: 8,
          paddingX: 4,
          paddingY: 1.5,
          radius: 999,
        },
      );
      overlayCtx.restore();
    }

    if (draftLine) {
      drawLine(draftLine, { color: "#fb7185", dashed: true, width: 2 });
      const dx = (draftLine.x2 || 0) - (draftLine.x1 || 0);
      const dy = (draftLine.y2 || 0) - (draftLine.y1 || 0);
      const pxLen = Math.hypot(dx, dy);
      if (pxLen > 3 && (draftLine.x2 !== undefined)) {
        const liveLabel =
          mmPerPixel !== null
            ? `${(pxLen * mmPerPixel).toFixed(1)} mm`
            : `${pxLen.toFixed(0)} px`;
        const midX = ((draftLine.x1 || 0) + (draftLine.x2 || 0)) / 2;
        const midY = ((draftLine.y1 || 0) + (draftLine.y2 || 0)) / 2;
        const sm = imageToScreenPoint(midX, midY);
        overlayCtx.save();
        overlayCtx.font = "bold 12px Inter, system-ui, sans-serif";
        const tw = overlayCtx.measureText(liveLabel).width;
        overlayCtx.fillStyle = "rgba(15,23,42,0.78)";
        overlayCtx.beginPath();
        overlayCtx.roundRect(sm.x - tw / 2 - 7, sm.y - 22, tw + 14, 20, 5);
        overlayCtx.fill();
        overlayCtx.fillStyle = "#fb7185";
        overlayCtx.textAlign = "center";
        overlayCtx.textBaseline = "middle";
        overlayCtx.fillText(liveLabel, sm.x, sm.y - 12);
        overlayCtx.restore();
      }
    }

    if (draftFreeLine?.points?.length) {
      const color = draftFreeLine.fillColor || DEFAULT_FREE_LINE_COLOR;
      const isPointMode = draftFreeLine.drawMode === "point";
      const curveStrength = getFreeLineCurveStrength(draftFreeLine);
      const polygonPoints = Array.isArray(draftFreeLine.points)
        ? draftFreeLine.points
        : [];
      const hoverPoint = draftFreeLine.hoverPoint || null;
      const previewPoints = [...polygonPoints];
      const lastPoint = polygonPoints[polygonPoints.length - 1] || null;
      if (
        isPointMode &&
        hoverPoint &&
        lastPoint &&
        getDistance(lastPoint, hoverPoint) > 0.6
      ) {
        previewPoints.push(hoverPoint);
      }
      const canClose =
        isPointMode &&
        polygonPoints.length >= MIN_FREE_CUT_POINTS &&
        hoverPoint &&
        getDistance(polygonPoints[0], hoverPoint) <=
          FREE_CUT_CLOSE_RADIUS_SCREEN / view.scale;
      const screenPoints = previewPoints.map((point) =>
        imageToScreenPoint(point.x, point.y),
      );
      overlayCtx.save();
      overlayCtx.fillStyle = color;
      overlayCtx.strokeStyle = color;
      overlayCtx.globalAlpha = canClose ? 0.18 : 0.12;
      if (
        screenPoints.length >= MIN_FREE_CUT_POINTS &&
        (!isPointMode || canClose)
      ) {
        traceSmoothClosedPath(overlayCtx, screenPoints, curveStrength);
        overlayCtx.fill();
      }
      overlayCtx.globalAlpha = 1;
      overlayCtx.lineWidth = 1.8;
      if (screenPoints.length > 0) {
        if (isPointMode && !canClose) {
          overlayCtx.beginPath();
          overlayCtx.moveTo(screenPoints[0].x, screenPoints[0].y);
          for (let index = 1; index < screenPoints.length; index += 1) {
            overlayCtx.lineTo(screenPoints[index].x, screenPoints[index].y);
          }
        } else {
          traceSmoothClosedPath(overlayCtx, screenPoints, curveStrength);
        }
        overlayCtx.stroke();
      }
      overlayCtx.fillStyle = color;
      for (let index = 0; index < polygonPoints.length; index += 1) {
        const point = imageToScreenPoint(
          polygonPoints[index].x,
          polygonPoints[index].y,
        );
        const isStartPoint = isPointMode && index === 0;
        overlayCtx.beginPath();
        overlayCtx.arc(
          point.x,
          point.y,
          isStartPoint ? 4.8 : 2.8,
          0,
          Math.PI * 2,
        );
        overlayCtx.fill();
        if (isStartPoint) {
          overlayCtx.strokeStyle = "#f8fafc";
          overlayCtx.lineWidth = 1.4;
          overlayCtx.stroke();
          overlayCtx.strokeStyle = color;
          overlayCtx.lineWidth = 1.8;
        }
      }
      overlayCtx.restore();

      if (isPointMode) {
        const labelSource =
          hoverPoint ||
          polygonPoints[polygonPoints.length - 1] ||
          polygonPoints[0];
        if (labelSource) {
          const labelAnchor = imageToScreenPoint(labelSource.x, labelSource.y);
          drawTag(
            overlayCtx,
            labelAnchor.x,
            labelAnchor.y - 16,
            canClose
              ? "Free Line: klik titik awal"
              : `Free Line: ${polygonPoints.length} titik`,
            color,
          );
        }
      }
    }

    if (draftAnglePoints.length > 0) {
      overlayCtx.save();
      overlayCtx.strokeStyle = "#fb923c";
      overlayCtx.fillStyle = "#fb923c";
      overlayCtx.lineWidth = 1.8;
      for (let i = 0; i < draftAnglePoints.length; i += 1) {
        const pointItem = imageToScreenPoint(
          draftAnglePoints[i].x,
          draftAnglePoints[i].y,
        );
        overlayCtx.beginPath();
        overlayCtx.arc(pointItem.x, pointItem.y, 3.5, 0, Math.PI * 2);
        overlayCtx.fill();
        if (i > 0) {
          const prev = imageToScreenPoint(
            draftAnglePoints[i - 1].x,
            draftAnglePoints[i - 1].y,
          );
          overlayCtx.beginPath();
          overlayCtx.moveTo(prev.x, prev.y);
          overlayCtx.lineTo(pointItem.x, pointItem.y);
          overlayCtx.stroke();
        }
      }
      overlayCtx.restore();
    }

    if (draftCirclePoints.length > 0) {
      overlayCtx.save();
      overlayCtx.strokeStyle = "#8b5cf6";
      overlayCtx.fillStyle = "#8b5cf6";
      overlayCtx.lineWidth = 2;
      const center = imageToScreenPoint(
        draftCirclePoints[0].x,
        draftCirclePoints[0].y,
      );
      overlayCtx.beginPath();
      overlayCtx.arc(center.x, center.y, 4.2, 0, Math.PI * 2);
      overlayCtx.fill();

      if (draftCirclePoints.length >= 2) {
        const edge = imageToScreenPoint(
          draftCirclePoints[1].x,
          draftCirclePoints[1].y,
        );
        const previewRadius = Math.hypot(edge.x - center.x, edge.y - center.y);
        overlayCtx.setLineDash([6, 4]);
        overlayCtx.beginPath();
        overlayCtx.arc(center.x, center.y, previewRadius, 0, Math.PI * 2);
        overlayCtx.stroke();
        overlayCtx.setLineDash([]);
        overlayCtx.beginPath();
        overlayCtx.arc(edge.x, edge.y, 4.2, 0, Math.PI * 2);
        overlayCtx.fill();
        drawTag(
          overlayCtx,
          center.x,
          center.y - previewRadius - 12,
          `Draft DIA: ${(getDistance(draftCirclePoints[0], draftCirclePoints[1]) * 2).toFixed(1)} px`,
          "#8b5cf6",
        );
      } else {
        const p = imageToScreenPoint(
          draftCirclePoints[0].x,
          draftCirclePoints[0].y,
        );
        overlayCtx.beginPath();
        overlayCtx.arc(p.x, p.y, 3.8, 0, Math.PI * 2);
        overlayCtx.fill();
      }
      overlayCtx.restore();
    }

    if (draftCenterFinderPoints.length > 0) {
      overlayCtx.save();
      overlayCtx.strokeStyle = "#0f766e";
      overlayCtx.fillStyle = "#0f766e";
      overlayCtx.lineWidth = 1.8;
      for (let i = 0; i < draftCenterFinderPoints.length; i += 1) {
        const pointItem = imageToScreenPoint(
          draftCenterFinderPoints[i].x,
          draftCenterFinderPoints[i].y,
        );
        overlayCtx.beginPath();
        overlayCtx.arc(pointItem.x, pointItem.y, 3.8, 0, Math.PI * 2);
        overlayCtx.fill();
        if (i > 0) {
          const prev = imageToScreenPoint(
            draftCenterFinderPoints[i - 1].x,
            draftCenterFinderPoints[i - 1].y,
          );
          overlayCtx.beginPath();
          overlayCtx.moveTo(prev.x, prev.y);
          overlayCtx.lineTo(pointItem.x, pointItem.y);
          overlayCtx.stroke();
        }
      }
      overlayCtx.restore();

      const anchor = draftCenterFinderPoints[draftCenterFinderPoints.length - 1];
      const screenAnchor = imageToScreenPoint(anchor.x, anchor.y);
      drawTag(
        overlayCtx,
        screenAnchor.x,
        screenAnchor.y - 16,
        `Center Finder: ${draftCenterFinderPoints.length}/3 titik`,
        "#0f766e",
      );
    }

    if (draftAxisBuilderPoints.length > 0) {
      overlayCtx.save();
      overlayCtx.strokeStyle = "#0ea5e9";
      overlayCtx.fillStyle = "#0ea5e9";
      overlayCtx.lineWidth = 1.8;
      for (let i = 0; i < draftAxisBuilderPoints.length; i += 1) {
        const pointItem = imageToScreenPoint(
          draftAxisBuilderPoints[i].x,
          draftAxisBuilderPoints[i].y,
        );
        overlayCtx.beginPath();
        overlayCtx.arc(pointItem.x, pointItem.y, 3.8, 0, Math.PI * 2);
        overlayCtx.fill();
      }
      if (draftAxisBuilderPoints.length >= 2) {
        const a = imageToScreenPoint(
          draftAxisBuilderPoints[0].x,
          draftAxisBuilderPoints[0].y,
        );
        const b = imageToScreenPoint(
          draftAxisBuilderPoints[1].x,
          draftAxisBuilderPoints[1].y,
        );
        overlayCtx.beginPath();
        overlayCtx.moveTo(a.x, a.y);
        overlayCtx.lineTo(b.x, b.y);
        overlayCtx.stroke();
      }
      if (draftAxisBuilderPoints.length >= 4) {
        const c = imageToScreenPoint(
          draftAxisBuilderPoints[2].x,
          draftAxisBuilderPoints[2].y,
        );
        const d = imageToScreenPoint(
          draftAxisBuilderPoints[3].x,
          draftAxisBuilderPoints[3].y,
        );
        overlayCtx.beginPath();
        overlayCtx.moveTo(c.x, c.y);
        overlayCtx.lineTo(d.x, d.y);
        overlayCtx.stroke();
      } else if (draftAxisBuilderPoints.length === 3) {
        const c = imageToScreenPoint(
          draftAxisBuilderPoints[2].x,
          draftAxisBuilderPoints[2].y,
        );
        overlayCtx.beginPath();
        overlayCtx.arc(c.x, c.y, 4.4, 0, Math.PI * 2);
        overlayCtx.stroke();
      }
      overlayCtx.restore();

      const anchor = draftAxisBuilderPoints[draftAxisBuilderPoints.length - 1];
      const screenAnchor = imageToScreenPoint(anchor.x, anchor.y);
      drawTag(
        overlayCtx,
        screenAnchor.x,
        screenAnchor.y - 16,
        `Axis Builder: ${draftAxisBuilderPoints.length}/4 titik`,
        "#0ea5e9",
      );
    }

    if (draftHkaPoints.length > 0) {
      const draftDef = getHkaModeDefinition(hkaInputMode);
      overlayCtx.save();
      overlayCtx.lineWidth = 1.8;
      for (let i = 0; i < draftHkaPoints.length; i += 1) {
        const ptDef = draftDef.points[i];
        const ptHint = ptDef ? (HKA_POINT_HINTS[ptDef.key] || {}) : {};
        const ptColor = ptHint.color || "#0d9488";
        const pointItem = imageToScreenPoint(draftHkaPoints[i].x, draftHkaPoints[i].y);
        // Dot with label
        overlayCtx.fillStyle = ptColor;
        overlayCtx.strokeStyle = "rgba(0,0,0,0.45)";
        overlayCtx.lineWidth = 1;
        overlayCtx.beginPath();
        overlayCtx.arc(pointItem.x, pointItem.y, 4.5, 0, Math.PI * 2);
        overlayCtx.fill();
        overlayCtx.stroke();
        // Short label above dot
        if (ptHint.label) {
          overlayCtx.font = "bold 9px Arial";
          overlayCtx.strokeStyle = "rgba(0,0,0,0.65)";
          overlayCtx.lineWidth = 2.5;
          overlayCtx.strokeText(ptHint.label, pointItem.x + 6, pointItem.y - 5);
          overlayCtx.fillStyle = ptColor;
          overlayCtx.fillText(ptHint.label, pointItem.x + 6, pointItem.y - 5);
        }
        // Connector line to previous dot
        if (i > 0) {
          const prevPtDef = draftDef.points[i - 1];
          const prevHint = prevPtDef ? (HKA_POINT_HINTS[prevPtDef.key] || {}) : {};
          const prevColor = prevHint.color || "#0d9488";
          const prev = imageToScreenPoint(draftHkaPoints[i - 1].x, draftHkaPoints[i - 1].y);
          const grad = overlayCtx.createLinearGradient(prev.x, prev.y, pointItem.x, pointItem.y);
          grad.addColorStop(0, prevColor);
          grad.addColorStop(1, ptColor);
          overlayCtx.strokeStyle = grad;
          overlayCtx.lineWidth = 1.6;
          overlayCtx.setLineDash([4, 3]);
          overlayCtx.beginPath();
          overlayCtx.moveTo(prev.x, prev.y);
          overlayCtx.lineTo(pointItem.x, pointItem.y);
          overlayCtx.stroke();
          overlayCtx.setLineDash([]);
        }
      }
      overlayCtx.restore();
    }

    if (guideBuilderPreviewPoint && guideBuilderReference?.line) {
      const previewLine = buildGuideLineFromReference(
        guideBuilderReference.line,
        guideBuilderPreviewPoint,
        guideBuilderMode,
      );
      if (previewLine) {
        const start = imageToScreenPoint(previewLine.x1, previewLine.y1);
        const end = imageToScreenPoint(previewLine.x2, previewLine.y2);
        const anchor = imageToScreenPoint(
          guideBuilderPreviewPoint.x,
          guideBuilderPreviewPoint.y,
        );
        overlayCtx.save();
        overlayCtx.strokeStyle =
          guideBuilderMode === "parallel" ? "#0ea5e9" : "#f59e0b";
        overlayCtx.lineWidth = 1.6;
        overlayCtx.setLineDash(guideBuilderMode === "parallel" ? [10, 4] : [4, 5]);
        overlayCtx.beginPath();
        overlayCtx.moveTo(start.x, start.y);
        overlayCtx.lineTo(end.x, end.y);
        overlayCtx.stroke();
        overlayCtx.setLineDash([]);
        overlayCtx.fillStyle =
          guideBuilderMode === "parallel" ? "#0ea5e9" : "#f59e0b";
        overlayCtx.beginPath();
        overlayCtx.arc(anchor.x, anchor.y, 4.2, 0, Math.PI * 2);
        overlayCtx.fill();
        overlayCtx.restore();
        drawTag(
          overlayCtx,
          anchor.x,
          anchor.y - 18,
          `${guideBuilderMode === "parallel" ? "Parallel" : "Perpendicular"} Guide`,
          guideBuilderMode === "parallel" ? "#0ea5e9" : "#f59e0b",
        );
      }
    }

    if (draftCut) {
      const polygonPoints = Array.isArray(draftCut.points)
        ? draftCut.points
        : [];
      const hoverPoint = draftCut.hoverPoint || null;
      const previewPoints = [...polygonPoints];
      const lastPoint = polygonPoints[polygonPoints.length - 1] || null;
      if (hoverPoint && lastPoint && getDistance(lastPoint, hoverPoint) > 0.6) {
        previewPoints.push(hoverPoint);
      }

      const canClose =
        polygonPoints.length >= MIN_FREE_CUT_POINTS &&
        hoverPoint &&
        getDistance(polygonPoints[0], hoverPoint) <=
          FREE_CUT_CLOSE_RADIUS_SCREEN / view.scale;

      overlayCtx.save();
      overlayCtx.strokeStyle = "#22d3ee";
      overlayCtx.fillStyle = canClose
        ? "rgba(34, 211, 238, 0.16)"
        : "rgba(34, 211, 238, 0.08)";
      overlayCtx.lineWidth = 1.5;
      overlayCtx.setLineDash([6, 4]);

      if (previewPoints.length > 0) {
        const firstPoint = imageToScreenPoint(
          previewPoints[0].x,
          previewPoints[0].y,
        );
        overlayCtx.beginPath();
        overlayCtx.moveTo(firstPoint.x, firstPoint.y);
        for (let index = 1; index < previewPoints.length; index += 1) {
          const nextPoint = imageToScreenPoint(
            previewPoints[index].x,
            previewPoints[index].y,
          );
          overlayCtx.lineTo(nextPoint.x, nextPoint.y);
        }
        if (canClose) {
          overlayCtx.closePath();
          overlayCtx.fill();
        }
        overlayCtx.stroke();
      }

      overlayCtx.setLineDash([]);
      for (let index = 0; index < polygonPoints.length; index += 1) {
        const pointItem = imageToScreenPoint(
          polygonPoints[index].x,
          polygonPoints[index].y,
        );
        const isStartPoint = index === 0;
        overlayCtx.fillStyle = isStartPoint ? "#ecfeff" : "#22d3ee";
        overlayCtx.strokeStyle = "#22d3ee";
        overlayCtx.lineWidth = isStartPoint ? 2 : 1.4;
        overlayCtx.beginPath();
        overlayCtx.arc(
          pointItem.x,
          pointItem.y,
          isStartPoint ? 5.2 : 4,
          0,
          Math.PI * 2,
        );
        overlayCtx.fill();
        overlayCtx.stroke();
      }
      overlayCtx.restore();

      const labelAnchor = imageToScreenPoint(
        (
          hoverPoint ||
          polygonPoints[polygonPoints.length - 1] ||
          polygonPoints[0]
        ).x,
        (
          hoverPoint ||
          polygonPoints[polygonPoints.length - 1] ||
          polygonPoints[0]
        ).y,
      );
      drawTag(
        overlayCtx,
        labelAnchor.x,
        labelAnchor.y - 16,
        canClose
          ? "Free Cut: klik titik awal"
          : `Free Cut: ${polygonPoints.length} titik`,
        "#22d3ee",
      );
    }

    // ── Cup Assessment canvas overlay ───────────────────────────────────────
    if (showCupAssessment && canvasCup) {
      const { cx, cy, a, b, angle } = canvasCup;
      const center = imageToScreenPoint(cx, cy);
      const cosA = Math.cos(angle);
      const sinA = Math.sin(angle);
      const scale = view.scale;
      const sa = a * scale; // semi-major in screen px
      const sb = b * scale; // semi-minor in screen px

      // inclination & anteversion labels
      const rawDeg = ((angle * 180 / Math.PI) % 180 + 180) % 180;
      const inclination = rawDeg > 90 ? 180 - rawDeg : rawDeg;
      const ratio = a > 0 ? Math.min(0.9999, Math.abs(b / a)) : 0;
      const anteversion = (Math.asin(ratio) * 180) / Math.PI;

      overlayCtx.save();

      // horizontal reference line
      overlayCtx.strokeStyle = "rgba(148,163,184,0.45)";
      overlayCtx.lineWidth = 1;
      overlayCtx.setLineDash([6, 5]);
      overlayCtx.beginPath();
      overlayCtx.moveTo(center.x - sa - 18, center.y);
      overlayCtx.lineTo(center.x + sa + 18, center.y);
      overlayCtx.stroke();
      overlayCtx.setLineDash([]);

      // major axis line (green)
      overlayCtx.strokeStyle = "#4ade80";
      overlayCtx.lineWidth = 1.5;
      overlayCtx.beginPath();
      overlayCtx.moveTo(center.x - cosA * sa, center.y - sinA * sa);
      overlayCtx.lineTo(center.x + cosA * sa, center.y + sinA * sa);
      overlayCtx.stroke();

      // minor axis line (cyan dashed)
      overlayCtx.strokeStyle = "#22d3ee";
      overlayCtx.lineWidth = 1;
      overlayCtx.setLineDash([4, 4]);
      overlayCtx.beginPath();
      overlayCtx.moveTo(center.x - sinA * sb, center.y + cosA * sb);
      overlayCtx.lineTo(center.x + sinA * sb, center.y - cosA * sb);
      overlayCtx.stroke();
      overlayCtx.setLineDash([]);

      // outer ellipse (orange)
      overlayCtx.save();
      overlayCtx.translate(center.x, center.y);
      overlayCtx.rotate(angle);
      overlayCtx.strokeStyle = "#f97316";
      overlayCtx.lineWidth = 2;
      overlayCtx.beginPath();
      overlayCtx.ellipse(0, 0, sa, sb, 0, 0, Math.PI * 2);
      overlayCtx.stroke();
      // inner ellipse (cyan dashed)
      overlayCtx.strokeStyle = "#22d3ee";
      overlayCtx.lineWidth = 1;
      overlayCtx.setLineDash([5, 5]);
      overlayCtx.beginPath();
      overlayCtx.ellipse(0, 0, sa * 0.72, sb * 0.72, 0, 0, Math.PI * 2);
      overlayCtx.stroke();
      overlayCtx.setLineDash([]);
      overlayCtx.restore();

      // handles — depan (lebih terang) vs belakang (lebih gelap) agar mudah dibedakan
      const handleR = cupHandleCompact ? 3.5 : 6;
      const handles = [
        { x: center.x, y: center.y, color: "#f8fafc" }, // center
        { x: center.x - cosA * sa, y: center.y - sinA * sa, color: "#4ade80" }, // major — depan
        { x: center.x + cosA * sa, y: center.y + sinA * sa, color: "#15803d" }, // major — belakang
        { x: center.x + sinA * sb, y: center.y - cosA * sb, color: "#22d3ee" }, // minor — depan
        { x: center.x - sinA * sb, y: center.y + cosA * sb, color: "#0e7490" }, // minor — belakang
      ];
      for (const h of handles) {
        overlayCtx.beginPath();
        overlayCtx.arc(h.x, h.y, handleR, 0, Math.PI * 2);
        overlayCtx.fillStyle = h.color;
        overlayCtx.fill();
        overlayCtx.strokeStyle = "#0f172a";
        overlayCtx.lineWidth = cupHandleCompact ? 1 : 1.5;
        overlayCtx.stroke();
      }

      // result label pill
      const lblText = `INC ${inclination.toFixed(1)}°  AV ${anteversion.toFixed(1)}°  ${canvasCupSide === "left" ? "◁ Kiri" : "Kanan ▷"}`;
      const pillX = center.x;
      const pillY = center.y - sa - 22;
      overlayCtx.font = "bold 11px Inter, sans-serif";
      const tw = overlayCtx.measureText(lblText).width;
      const ph = 18; const pw = tw + 20; const pr = 9;
      overlayCtx.fillStyle = "rgba(15,23,42,0.82)";
      overlayCtx.beginPath();
      overlayCtx.roundRect(pillX - pw / 2, pillY - ph / 2, pw, ph, pr);
      overlayCtx.fill();
      overlayCtx.fillStyle = "#f97316";
      overlayCtx.textAlign = "center";
      overlayCtx.textBaseline = "middle";
      overlayCtx.fillText(lblText, pillX, pillY);

      overlayCtx.restore();
    }

    // ── Crop selection draft overlay ────────────────────────────────────────
    if (cropDraftPoints) {
      const s1 = imageToScreenPoint(cropDraftPoints.startX, cropDraftPoints.startY);
      const s2 = imageToScreenPoint(cropDraftPoints.endX, cropDraftPoints.endY);
      const rx = Math.min(s1.x, s2.x);
      const ry = Math.min(s1.y, s2.y);
      const rw = Math.abs(s2.x - s1.x);
      const rh = Math.abs(s2.y - s1.y);
      overlayCtx.save();
      overlayCtx.strokeStyle = "#22d3ee";
      overlayCtx.lineWidth = 1.5;
      overlayCtx.setLineDash([7, 4]);
      overlayCtx.strokeRect(rx, ry, rw, rh);
      overlayCtx.fillStyle = "rgba(34,211,238,0.08)";
      overlayCtx.fillRect(rx, ry, rw, rh);
      overlayCtx.setLineDash([]);
      overlayCtx.restore();
      drawTag(overlayCtx, rx + rw / 2, ry - 8, "Potong area ini", "#22d3ee");
    }
  }, [
    activeSnapTarget,
    annotations,
    angles,
    calibrationMode,
    calibrationLineId,
    calibrationReferenceLine,
    circles,
    contrast,
    cropDraftPoints,
    cropRect,
    invertImage,
    draftAnglePoints,
    draftAxisBuilderPoints,
    draftCenterFinderPoints,
    draftCirclePoints,
    draftCut,
    draftFreeLine,
    draftHkaPoints,
    draftLine,
    freeLineMode,
    guideBuilderMode,
    guideBuilderPreviewPoint,
    guideBuilderReference,
    flipX,
    flipY,
    hkaSets,
    image,
    imageHeight,
    imageProcessingMode,
    imageToScreenPoint,
    imageWidth,
    isCoarsePointer,
    planningGuides,
    level,
    lineTypeColor,
    lineTypeLabel,
    lines,
    cutLayers,
    layerDisplayData,
    getLineLabelText,
    getMobileAngleHandleAssistGeometry,
    getMobileHandleAssistGeometry,
    getMobileHkaHandleAssistGeometry,
    getMobilePlanningGuideHandleAssistGeometry,
    getLineVisualStyle,
    getPlanningGuideVisualStyle,
    getPlanningGuideAutoColor,
    getPlanningGuideLabelText,
    isLineLocked,
    measurementUnit,
    mmPerPixel,
    mobileHandleAssist,
    mobileAngleHandleAssist,
    mobileHkaHandleAssist,
    mobilePlanningGuideHandleAssist,
    modelHeight,
    modelWidth,
    orientedSize.height,
    orientedSize.width,
    processedXrayVersion,
    rotation,
    selectionPulse,
    selectedAngleId,
    selectedAnnotationId,
    selectedCircleId,
    selectedCutLayerId,
    selectedCutLayerIdsSet,
    selectedHkaId,
    selectedLineId,
    selectedPlanningGuideId,
    view.x,
    view.y,
    view.scale,
    viewport.height,
    viewport.width,
    showCupAssessment,
    canvasCup,
    canvasCupSide,
    cupHandleCompact,
  ]);

  useEffect(() => {
    renderLayers();
  }, [renderLayers]);

  useEffect(() => {
    let cancelled = false;

    const loadCompare = async () => {
      if (!compareImageSrc) {
        setCompareImage(null);
        return;
      }

      try {
        const img = await loadImageFromSrc(compareImageSrc);
        if (!cancelled) {
          setCompareImage(img);
        }
      } catch {
        if (!cancelled) {
          setCompareImage(null);
        }
      }
    };

    loadCompare();
    return () => {
      cancelled = true;
    };
  }, [compareImageSrc]);

  useEffect(() => {
    const canvas = compareCanvasRef.current;
    if (
      !canvas ||
      !compareMode ||
      !compareViewport.width ||
      !compareViewport.height
    )
      return;

    const ratio = window.devicePixelRatio || 1;
    const targetWidth = Math.floor(compareViewport.width * ratio);
    const targetHeight = Math.floor(compareViewport.height * ratio);
    if (canvas.width !== targetWidth || canvas.height !== targetHeight) {
      canvas.width = targetWidth;
      canvas.height = targetHeight;
    }
    canvas.style.width = `${compareViewport.width}px`;
    canvas.style.height = `${compareViewport.height}px`;

    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
    ctx.clearRect(0, 0, compareViewport.width, compareViewport.height);
    ctx.fillStyle = "#020617";
    ctx.fillRect(0, 0, compareViewport.width, compareViewport.height);

    if (!compareImage) {
      ctx.fillStyle = "rgba(148, 163, 184, 0.9)";
      ctx.font = "14px Inter, sans-serif";
      ctx.textAlign = "center";
      ctx.fillText(
        "Upload gambar compare (pre-op/post-op)",
        compareViewport.width / 2,
        compareViewport.height / 2,
      );
      return;
    }

    const iw = compareImage.naturalWidth || compareImage.width || 0;
    const ih = compareImage.naturalHeight || compareImage.height || 0;
    if (!iw || !ih) return;

    const oriented = getOrientedSize(iw, ih, rotation);
    const scale = Math.min(
      (compareViewport.width - 20) / Math.max(oriented.width, 1),
      (compareViewport.height - 20) / Math.max(oriented.height, 1),
    );
    const drawScale = clamp(scale, 0.05, 8);
    const drawW = oriented.width * drawScale;
    const drawH = oriented.height * drawScale;
    const offsetX = (compareViewport.width - drawW) / 2;
    const offsetY = (compareViewport.height - drawH) / 2;

    const p0 = orientPoint(0, 0, iw, ih, rotation, flipX, flipY);
    const p1 = orientPoint(1, 0, iw, ih, rotation, flipX, flipY);
    const p2 = orientPoint(0, 1, iw, ih, rotation, flipX, flipY);
    const a = p1.x - p0.x;
    const b = p1.y - p0.y;
    const c = p2.x - p0.x;
    const d = p2.y - p0.y;
    const e = p0.x;
    const f = p0.y;

    ctx.save();
    ctx.translate(offsetX, offsetY);
    ctx.scale(drawScale, drawScale);
    ctx.transform(a, b, c, d, e, f);
    ctx.filter = `contrast(${contrast}%) brightness(${level}%)`;
    ctx.drawImage(compareImage, 0, 0, iw, ih, 0, 0, iw, ih);
    ctx.restore();

    drawTag(
      ctx,
      compareViewport.width / 2,
      compareViewport.height - 18,
      compareImageName ? `COMPARE: ${compareImageName}` : "COMPARE",
      "#22d3ee",
    );
  }, [
    compareImage,
    compareImageName,
    compareMode,
    compareViewport.height,
    compareViewport.width,
    contrast,
    flipX,
    flipY,
    level,
    rotation,
  ]);

  const applyMainImageToWorkspace = useCallback(
    ({ nextImage, nextImageName, noticeText }) => {
      const width = nextImage?.naturalWidth || nextImage?.width || 0;
      const height = nextImage?.naturalHeight || nextImage?.height || 0;

      if (!width || !height) {
        setNotice("Gambar gagal diproses. Dimensi file tidak valid.");
        return false;
      }

      nextLineIdRef.current = 1;
      nextAngleIdRef.current = 1;
      nextCircleIdRef.current = 1;
      nextHkaIdRef.current = 1;
      nextCutLayerIdRef.current = 1;
      setImage(nextImage);
      setImageName(nextImageName || "xray-image");
      setLines([]);
      setAngles([]);
      setCircles([]);
      setHkaSets([]);
      setDraftAnglePoints([]);
      setDraftCirclePoints([]);
      setDraftCenterFinderPoints([]);
      setDraftAxisBuilderPoints([]);
      setDraftHkaPoints([]);
      setDraftFreeLine(null);
      setDraftFreeLineTargetLayerId(null);
      setGuideBuilderPreviewPoint(null);
      setGuideBuilderMode("parallel");
      setDraftLine(null);
      setDraftCut(null);
      setCutLayers([]);
      setSelectedCutLayerId(null);
      setSelectedLineId(null);
      setSelectedAngleId(null);
      setSelectedCircleId(null);
      setSelectedHkaId(null);
      setCalibrationLineId(null);
      setLockedLineIds(new Set());
      setMmPerPixel(null);
      setCalibrationMode("line");
      setSourceZoomPercent("100");
      setMmPerPixelAt100Input("0.63");
      setContrast(100);
      setLevel(100);
      setImageProcessingMode("normal");
      setImageProcessingModalOpen(false);
      setImageProcessingBusy(false);
      setRotation(0);
      setFlipX(false);
      setFlipY(false);
      setCropRect({ x: 0, y: 0, width, height });
      setActualMmInput("13");
      setActualUnit("cm");
      setTemplateRealSizeInput("");
      setTemplateRealSizeUnit("cm");
      setTemplateRealSizeAxis("height");
      setMeasurementUnit("cm");
      setLinePreset("normal");
      setPlanNote("");
      setPlanSteps([]);
      setPlanningGuides([]);
      setSelectedPlanningGuideId(null);
      setAnnotations([]);
      setSelectedAnnotationId(null);
      setPlanningGuideMode("valgusCut");
      setValgusCutAngleDeg(5);
      setValgusCutSide("Right");
      setValgusCutOffsetPx(10);
      setValgusCutLineLengthPx(100);
      setTibialSlopeDeg(7);
      setTibialPosteriorSide("Right");
      setTibialSlopeOffsetPx(10);
      setTibialSlopeLineLengthPx(90);
      setTibialCutAngleDeg(0);
      setTibialCutDirection("Valgus");
      setTibialCutOffsetPx(10);
      setTibialCutLineLengthPx(90);
      setPlanningGuideLabelOffsetX(DEFAULT_GUIDE_LABEL_OFFSET_X);
      setPlanningGuideLabelOffsetY(DEFAULT_GUIDE_LABEL_OFFSET_Y);
      setPlanningGuideLabelOpacity(DEFAULT_LABEL_OPACITY);
      setTool(getIdleTool());
      setMobilePanelMode("workspace");
      setMobileControlsOpen(false);
      resetHistoryStacks();
      setNotice(
        noticeText ||
          "X-ray aktif. Langkah berikutnya: buka Kalibrasi, pilih Garis Ruler atau Head Ref, lalu Simpan Kalibrasi untuk memulai measurement/templating.",
      );
      return true;
    },
    [getIdleTool, resetHistoryStacks],
  );

  const addImageAsWorkspaceLayer = useCallback(
    ({
      layerImage,
      imageSrc,
      name,
      noticeText,
      opacity = DEFAULT_TEMPLATE_LAYER_OPACITY,
      sizeMode = "template",
      autoScaleFromCalibration = false,
      physicalSize = null,
      physicalWidthMm = null,
      physicalHeightMm = null,
      transparentWhiteBackground = false,
      implantViewMode = null,
    }) => {
      if (!image || !modelWidth || !modelHeight) {
        setNotice(
          "Upload gambar layer bawah dulu sebelum menambahkan layer kedua.",
        );
        return false;
      }

      let workingLayerImage = layerImage;
      let workingImageSrc = imageSrc;
      let transparentBackgroundApplied = false;

      if (transparentWhiteBackground) {
        const transparentImage = makeWhiteBackgroundTransparent(layerImage);
        if (transparentImage?.image) {
          workingLayerImage = transparentImage.image;
          workingImageSrc = transparentImage.imageSrc || workingImageSrc;
          transparentBackgroundApplied = true;
        }
      }

      let rawW =
        workingLayerImage?.naturalWidth || workingLayerImage?.width || 0;
      let rawH =
        workingLayerImage?.naturalHeight || workingLayerImage?.height || 0;
      if (!rawW || !rawH) {
        setNotice("Layer gagal diproses. Dimensi file tidak valid.");
        return false;
      }

      const shouldMatchBase = sizeMode === "match-base";
      let physicalTemplateSize = resolveTemplatePhysicalSize({
        physicalSize,
        physicalWidthMm,
        physicalHeightMm,
        width: rawW,
        height: rawH,
      });

      if (physicalTemplateSize) {
        const normalizedImage = normalizeImageToPhysicalAspect(
          workingLayerImage,
          physicalTemplateSize,
        );
        if (normalizedImage?.image) {
          workingLayerImage = normalizedImage.image;
          workingImageSrc = normalizedImage.imageSrc || workingImageSrc;
          rawW =
            workingLayerImage?.naturalWidth || workingLayerImage?.width || 0;
          rawH =
            workingLayerImage?.naturalHeight || workingLayerImage?.height || 0;
          physicalTemplateSize = resolveTemplatePhysicalSize({
            physicalSize,
            physicalWidthMm,
            physicalHeightMm,
            width: rawW,
            height: rawH,
          });
        }
      }

      const contentBounds = shouldMatchBase || physicalTemplateSize
        ? null
        : getImageContentBounds(workingLayerImage);
      const srcX = contentBounds?.x || 0;
      const srcY = contentBounds?.y || 0;
      const srcW = contentBounds?.width || rawW;
      const srcH = contentBounds?.height || rawH;
      const templateSizeSource =
        sizeMode === "inherit-template"
          ? selectedCutLayer?.kind === "upload"
            ? selectedCutLayer
            : [...cutLayers]
                .reverse()
                .find((layer) => layer.kind === "upload") || null
          : null;
      const rawInheritedTemplateSize = templateSizeSource
        ? getLayerDisplaySize(templateSizeSource)
        : null;
      const inheritedLooksLikeBackground =
        rawInheritedTemplateSize &&
        rawInheritedTemplateSize.width >= modelWidth * 0.86 &&
        rawInheritedTemplateSize.height >= modelHeight * 0.86;
      const inheritedTemplateSize = inheritedLooksLikeBackground
        ? null
        : rawInheritedTemplateSize;
      const sameCanvasSize =
        !contentBounds &&
        Math.abs(rawW - modelWidth) <= 2 &&
        Math.abs(rawH - modelHeight) <= 2;
      const targetMax =
        Math.min(modelWidth, modelHeight) * TEMPLATE_INITIAL_MAX_FRACTION;
      const targetMaxWidth = modelWidth * 0.42;
      const targetMaxHeight = modelHeight * 0.42;
      const detectedTemplateRulerScale =
        autoScaleFromCalibration && !shouldMatchBase
          ? estimateTemplateRulerPxPerMm(workingLayerImage)
          : null;
      const templateRulerScale =
        detectedTemplateRulerScale && mmPerPixel !== null
          ? detectedTemplateRulerScale
          : null;
      const calibratedDisplayWidth = templateRulerScale
        ? clamp(
            srcW / templateRulerScale.pxPerMm / mmPerPixel,
            18,
            Math.max(18, modelWidth * 3),
          )
        : null;
      const physicalDisplayWidth =
        !templateRulerScale && physicalTemplateSize && mmPerPixel !== null
          ? clamp(
              physicalTemplateSize.widthMm / mmPerPixel,
              18,
              Math.max(18, modelWidth * 3),
            )
          : null;
      const physicalDisplayHeight =
        !templateRulerScale && physicalTemplateSize && mmPerPixel !== null
          ? clamp(
              physicalTemplateSize.heightMm / mmPerPixel,
              18,
              Math.max(18, modelHeight * 3),
            )
          : null;
      const calibratedDisplayHeight = templateRulerScale
        ? clamp(
            srcH / templateRulerScale.pxPerMm / mmPerPixel,
            18,
            Math.max(18, modelHeight * 3),
          )
        : null;
      const scale = shouldMatchBase
        ? 1
        : sameCanvasSize
          ? Math.min(modelWidth / srcW, modelHeight / srcH)
          : Math.min(
              targetMax / srcW,
              targetMax / srcH,
              targetMaxWidth / srcW,
              targetMaxHeight / srcH,
              1,
            );
      const displayWidth =
        physicalDisplayWidth !== null
          ? physicalDisplayWidth
          : calibratedDisplayWidth !== null
          ? calibratedDisplayWidth
          : inheritedTemplateSize
            ? Math.max(18, inheritedTemplateSize.width)
            : shouldMatchBase || sameCanvasSize
              ? modelWidth
              : Math.max(18, srcW * scale);
      const displayHeight =
        physicalDisplayHeight !== null
          ? physicalDisplayHeight
          : calibratedDisplayHeight !== null
          ? calibratedDisplayHeight
          : inheritedTemplateSize
            ? Math.max(18, inheritedTemplateSize.height)
            : shouldMatchBase || sameCanvasSize
              ? modelHeight
              : Math.max(18, srcH * scale);

      const nextLayer = {
        id: nextCutLayerIdRef.current,
        kind: "upload",
        image: workingLayerImage,
        imageSrc: workingImageSrc,
        name: name || `Layer ${nextCutLayerIdRef.current}`,
        sourceX: srcX,
        sourceY: srcY,
        sourceWidth: srcW,
        sourceHeight: srcH,
        displayWidth,
        displayHeight,
        centerX: modelWidth / 2,
        centerY: modelHeight / 2,
        rotation: 0,
        flipX: false,
        flipY: false,
        opacity:
          shouldMatchBase || sameCanvasSize ? Math.min(opacity, 0.6) : opacity,
        contrast: 100,
        level: 100,
        lockScale: false,
        hidden: false,
        autoScaleFromCalibration: Boolean(autoScaleFromCalibration),
        rulerPxPerMm: detectedTemplateRulerScale?.pxPerMm || null,
        physicalSize: physicalTemplateSize ? physicalSize || "custom" : null,
        physicalSizeLabel: physicalTemplateSize?.label || "",
        physicalWidthMm: physicalTemplateSize?.widthMm || null,
        physicalHeightMm: physicalTemplateSize?.heightMm || null,
        transparentWhiteBackground: Boolean(transparentWhiteBackground),
        implantViewMode,
      };

      nextCutLayerIdRef.current += 1;
      setCutLayers((prev) => [...prev, nextLayer]);
      focusLayerSettings(nextLayer.id);
      setSelectedLineId(null);
      setSelectedAngleId(null);
      setSelectedCircleId(null);
      setSelectedHkaId(null);
      setTool(getIdleTool());
      setMobileControlsOpen(!isMobileViewport);
      const trimText = contentBounds
        ? " Margin kosong template otomatis di-trim."
        : "";
      const calibrationText = autoScaleFromCalibration
        ? mmPerPixel === null
          ? detectedTemplateRulerScale
            ? ` Ruler template ${detectedTemplateRulerScale.axis} terdeteksi; layer akan auto-scale setelah kalibrasi aktif.`
            : " Kalibrasi belum aktif: klik Calib/Ruler, pilih atau buat garis kalibrasi, isi nilai real, lalu Simpan Kalibrasi."
          : templateRulerScale
            ? ` Scale implant otomatis mengikuti garis kalibrasi aktif dari ruler template ${templateRulerScale.axis}.`
          : physicalTemplateSize
            ? ` Template diset ${physicalTemplateSize.label} dan otomatis mengikuti skala kalibrasi.`
            : " Ruler template tidak terbaca otomatis; pilih layer lalu pakai Ruler atau isi Scale real manual."
        : "";
      const transparentText = transparentBackgroundApplied
        ? " Background putih template dibuat transparan."
        : "";
      setNotice(
        (noticeText ||
          `Layer "${nextLayer.name}" ditambahkan di atas layer bawah.`) +
          trimText +
          transparentText +
          calibrationText,
      );
      return true;
    },
    [
      cutLayers,
      focusLayerSettings,
      getIdleTool,
      image,
      isMobileViewport,
      mmPerPixel,
      modelHeight,
      modelWidth,
      selectedCutLayer,
    ],
  );

  // Derived key: only changes when physical-scaling-relevant properties change on
  // image-backed layers.  Free-line / free-cut warp layers are excluded because
  // normalizeFreeLineLayerBounds mutates sourceWidth/sourceHeight on every drag
  // frame, which would cause the effect below to call setCutLayers on every frame,
  // stacking up renders until React throws "Maximum update depth exceeded".
  const physicalScaleTrigger = useMemo(
    () =>
      cutLayers
        .filter((layer) => {
          if (!layer.autoScaleFromCalibration || layer.lockScale) return false;
          if (layer.kind === "free-line" || layer.kind === "free-cut") return false;
          const rulerPxPerMm = Number(layer.rulerPxPerMm);
          const hasRulerScale = Number.isFinite(rulerPxPerMm) && rulerPxPerMm > 0;
          const hasPhysicalSize =
            Number.isFinite(Number(layer.physicalWidthMm)) &&
            Number(layer.physicalWidthMm) > 0 &&
            Number.isFinite(Number(layer.physicalHeightMm)) &&
            Number(layer.physicalHeightMm) > 0;
          return hasRulerScale || hasPhysicalSize;
        })
        .map(
          (layer) =>
            `${layer.id}:${layer.rulerPxPerMm}:${layer.physicalWidthMm}:${layer.physicalHeightMm}:${layer.sourceWidth}:${layer.sourceHeight}:${layer.lockScale}`,
        )
        .join("|"),
    [cutLayers],
  );

  useEffect(() => {
    if (!physicalScaleTrigger || mmPerPixel === null || !modelWidth || !modelHeight) return;

    const signature = `${mmPerPixel}:${modelWidth}:${modelHeight}:${physicalScaleTrigger}`;
    if (physicalTemplateScaleSignatureRef.current === signature) return;
    physicalTemplateScaleSignatureRef.current = signature;

    setCutLayers((prev) => {
      let changed = false;
      const nextLayers = prev.map((layer) => {
        if (!layer.autoScaleFromCalibration || layer.lockScale) {
          return layer;
        }

        const rulerPxPerMm = Number(layer.rulerPxPerMm);
        const hasRulerScale =
          Number.isFinite(rulerPxPerMm) && rulerPxPerMm > 0;
        const physicalWidthMm = Number(layer.physicalWidthMm);
        const physicalHeightMm = Number(layer.physicalHeightMm);
        const hasPhysicalSize =
          Number.isFinite(physicalWidthMm) &&
          physicalWidthMm > 0 &&
          Number.isFinite(physicalHeightMm) &&
          physicalHeightMm > 0;

        if (!hasRulerScale && !hasPhysicalSize) return layer;

        const nextDisplayWidth = hasRulerScale
          ? clamp(
              Number(layer.sourceWidth || layer.displayWidth || 18) /
                rulerPxPerMm /
                mmPerPixel,
              18,
              Math.max(18, modelWidth * 3),
            )
          : clamp(
              physicalWidthMm / mmPerPixel,
              18,
              Math.max(18, modelWidth * 3),
            );
        const nextDisplayHeight = hasRulerScale
          ? clamp(
              Number(layer.sourceHeight || layer.displayHeight || 18) /
                rulerPxPerMm /
                mmPerPixel,
              18,
              Math.max(18, modelHeight * 3),
            )
          : clamp(
              physicalHeightMm / mmPerPixel,
              18,
              Math.max(18, modelHeight * 3),
            );

        if (
          Math.abs(Number(layer.displayWidth || 0) - nextDisplayWidth) < 0.5 &&
          Math.abs(Number(layer.displayHeight || 0) - nextDisplayHeight) < 0.5
        ) {
          return layer;
        }

        changed = true;
        return {
          ...layer,
          displayWidth: nextDisplayWidth,
          displayHeight: nextDisplayHeight,
        };
      });
      return changed ? nextLayers : prev;
    });
  }, [physicalScaleTrigger, mmPerPixel, modelHeight, modelWidth]);

  const useSheetImageAsMain = useCallback(
    async (imageItem) => {
      const candidateSources = buildDriveImageCandidates(
        imageItem?.imageSrc,
        imageItem?.driveId,
      );
      if (candidateSources.length === 0) {
        setNotice("Gambar Google Drive belum valid.");
        return;
      }

      try {
        const loaded = await loadImageFromCandidates(candidateSources);
        if (objectUrlRef.current) {
          URL.revokeObjectURL(objectUrlRef.current);
          objectUrlRef.current = null;
        }
        const applied = applyMainImageToWorkspace({
          nextImage: loaded.image,
          nextImageName: imageItem.name || "sheet-drive-image",
          noticeText: `X-ray "${imageItem.name || "Google Sheet Image"}" dimuat. Lanjutkan dengan Kalibrasi agar measurement dan implant mengikuti skala nyata.`,
        });
        if (applied) {
          mainImageFileRef.current = null;
          setMainImageSrc(loaded.src);
          setHasTemporaryMainImage(false);
          if (isSimpleUiMode) openSimpleCalibrationModal();
        }
      } catch {
        setNotice("Gagal memuat gambar dari Google Drive.");
      }
    },
    [applyMainImageToWorkspace, isSimpleUiMode, openSimpleCalibrationModal],
  );

  const useSelectedSheetImageAsMain = useCallback(() => {
    const selectedItem =
      sheetMainImages.find(
        (item) => String(item.id) === String(selectedSheetMainImageId),
      ) || null;
    if (!selectedItem) {
      setNotice("Pilih gambar Google Sheet/Drive terlebih dulu.");
      return;
    }
    void useSheetImageAsMain(selectedItem);
  }, [sheetMainImages, selectedSheetMainImageId, useSheetImageAsMain]);

  const handleImageUpload = useCallback(
    (event) => {
      const input = event.currentTarget;
      const file = input.files?.[0];
      if (!file) return;

      const nextObjectUrl = URL.createObjectURL(file);
      const nextImage = new Image();

      nextImage.onload = () => {
        if (objectUrlRef.current) {
          URL.revokeObjectURL(objectUrlRef.current);
        }

        const applied = applyMainImageToWorkspace({
          nextImage,
          nextImageName: file.name,
          noticeText: `X-ray "${file.name}" aktif. Lanjutkan dengan Kalibrasi agar measurement dan implant mengikuti skala nyata.`,
        });
        if (applied) {
          objectUrlRef.current = nextObjectUrl;
          mainImageFileRef.current = file;
          setMainImageSrc(nextObjectUrl);
          setHasTemporaryMainImage(true);
          readFileAsDataUrl(file).then((dataUrl) =>
            saveImageToIDB(dataUrl, file.name),
          ).catch(() => {});
          if (isSimpleUiMode) openSimpleCalibrationModal();
        } else {
          URL.revokeObjectURL(nextObjectUrl);
        }
      };

      nextImage.onerror = () => {
        URL.revokeObjectURL(nextObjectUrl);
        setNotice("Gagal membaca file gambar. Coba file lain.");
      };

      nextImage.src = nextObjectUrl;
      input.value = "";
    },
    [applyMainImageToWorkspace, isSimpleUiMode, openSimpleCalibrationModal],
  );

  const handlePointerDown = useCallback(
    (event) => {
      if (!image) return;

      event.preventDefault();
      captureMobilePointer(event);
      interactionCanvasRectRef.current =
        overlayCanvasRef.current?.getBoundingClientRect() || null;
      interactionStartedAtRef.current = Date.now();
      const point = getLocalPoint(event);
      const imagePoint = screenToImagePoint(point.x, point.y);
      const boundedPoint = clampToImageBounds(imagePoint);
      const snappedPlacementPoint =
        resolveSnappedImagePoint(boundedPoint).point;
      const isTouchLikePointer =
        event.pointerType === "touch" ||
        (isCoarsePointer && event.button === 0);
      const isAdditiveLayerSelection =
        !isTouchLikePointer &&
        (event.shiftKey || event.metaKey || event.ctrlKey);

      if (event.button === 1 || event.button === 2) {
        interactionRef.current = {
          mode: "pan",
          startX: point.x,
          startY: point.y,
          startPanX: view.panX,
          startPanY: view.panY,
        };
        return;
      }

      if (event.button !== 0) return;

      // ── Cup Assessment canvas drag ──────────────────────────────────────────
      if (showCupAssessment && canvasCup) {
        const { cx, cy, a, b, angle } = canvasCup;
        const center = { x: point.x, y: point.y };
        const cScr = imageToScreenPoint(cx, cy);
        const cosA = Math.cos(angle);
        const sinA = Math.sin(angle);
        const sc = view.scale;
        const sa = a * sc;
        const sb = b * sc;
        const HIT = 12;
        const handles = [
          { key: "center", x: cScr.x, y: cScr.y },
          { key: "top",    x: cScr.x - cosA * sa, y: cScr.y - sinA * sa },
          { key: "bottom", x: cScr.x + cosA * sa, y: cScr.y + sinA * sa },
          { key: "sideR",  x: cScr.x + sinA * sb, y: cScr.y - cosA * sb },
          { key: "sideL",  x: cScr.x - sinA * sb, y: cScr.y + cosA * sb },
        ];
        const hit = handles.find(h => Math.hypot(center.x - h.x, center.y - h.y) < HIT);
        if (hit) {
          canvasCupDragRef.current = {
            handle: hit.key,
            startScrX: point.x,
            startScrY: point.y,
            startCup: { ...canvasCup },
          };
          interactionRef.current = { mode: "cupDrag", startX: point.x, startY: point.y };
          return;
        }
      }

      // ── Crop selection tool ─────────────────────────────────────────────────
      if (cropToolActive) {
        interactionRef.current = {
          mode: "cropSelect",
          startX: imagePoint.x,
          startY: imagePoint.y,
          endX: imagePoint.x,
          endY: imagePoint.y,
        };
        setCropDraftPoints({ startX: imagePoint.x, startY: imagePoint.y, endX: imagePoint.x, endY: imagePoint.y });
        return;
      }

      // ── Brush tool ──────────────────────────────────────────────────────────
      if (tool === "brush") {
        const hitLayerId = findCutLayerByPoint(imagePoint) ?? selectedCutLayerId;
        if (hitLayerId) {
          const targetLayer = cutLayers.find((l) => l.id === hitLayerId);
          if (targetLayer && isImageBackedLayerKind(targetLayer.kind) && targetLayer.image) {
            const sw = Math.max(1, targetLayer.sourceWidth);
            const sh = Math.max(1, targetLayer.sourceHeight);
            const workCanvas = document.createElement("canvas");
            workCanvas.width = sw;
            workCanvas.height = sh;
            const wCtx = workCanvas.getContext("2d");
            const srcX = targetLayer.sourceX || 0;
            const srcY = targetLayer.sourceY || 0;
            wCtx.drawImage(targetLayer.image, srcX, srcY, sw, sh, 0, 0, sw, sh);
            brushWorkCanvasRef.current = workCanvas;
            brushWorkLayerIdRef.current = hitLayerId;
            const canvasPt = imagePointToLayerCanvasPoint(imagePoint, targetLayer);
            const radiusInImage = brushSize / view.scale;
            const canvasRadius = radiusInImage * (targetLayer.sourceWidth / Math.max(1, getLayerDisplaySize(targetLayer).width));
            applyBrushToCanvas(workCanvas, canvasPt, canvasRadius, brushMode, brushStrength, brushColor);
            setCutLayers((prev) => prev.map((l) => {
              if (l.id !== hitLayerId) return l;
              const copyCanvas = document.createElement("canvas");
              copyCanvas.width = workCanvas.width;
              copyCanvas.height = workCanvas.height;
              copyCanvas.getContext("2d").drawImage(workCanvas, 0, 0);
              return { ...l, image: copyCanvas, sourceX: 0, sourceY: 0 };
            }));
            setHistoryPaused(true);
            interactionRef.current = { mode: "brush-stroke", layerId: hitLayerId, layer: targetLayer };
          }
        }
        return;
      }

      if (
        isSimpleUiMode &&
        isMobileViewport &&
        isTouchLikePointer &&
        Number.isFinite(event.pointerId)
      ) {
        const pointerId = event.pointerId;
        trackMobileGesturePointer(pointerId, point);
        clearMobileLongPress();

        if (consumeMobileDoubleTap(point)) {
          clearMobileGesturePointers();
          interactionRef.current = { mode: null, startX: 0, startY: 0 };
          fitImageToViewport();
          setNotice("Zoom canvas di-reset.");
          return;
        }

          const gestureSnapshot = getMobileGestureSnapshot();
          if (gestureSnapshot) {
            const gestureImagePoint = screenToImagePoint(
              gestureSnapshot.centerX,
              gestureSnapshot.centerY,
            );
            const gestureLayerId = findCutLayerByPoint(gestureImagePoint);
            const gestureTargetLayer =
              (gestureLayerId !== null
                ? cutLayers.find((layer) => layer.id === gestureLayerId)
                : null) ||
              selectedCutLayer ||
              null;
            if (gestureTargetLayer && !gestureTargetLayer.hidden) {
              const selectedGestureLayerIds = selectedCutLayerIdsSet.has(
                gestureTargetLayer.id,
              )
                ? selectedCutLayerIds
                : getRelatedLayerIds(gestureTargetLayer.id, {
                    includeGroup: true,
                  });
              const gestureLayerIds = selectedGestureLayerIds.filter((layerId) =>
                cutLayers.some((item) => item.id === layerId),
              );
              if (gestureLayerIds.length > 0) {
                selectLayerFromCanvas(gestureTargetLayer.id, {
                  includeGroup: true,
                  openPanel: false,
                });
                setMobileCanvasMode("edit");
                setTool("pan");
                setMobileToolMode("move");
                setHistoryPaused(true);
                interactionRef.current = {
                  mode: "layer-gesture",
                  layerIds: gestureLayerIds,
                  startCenterImageX: gestureImagePoint.x,
                  startCenterImageY: gestureImagePoint.y,
                  startDistance: gestureSnapshot.distance,
                  startAngle: gestureSnapshot.angle,
                  origins: gestureLayerIds.map((layerId) => {
                    const layer = cutLayers.find((item) => item.id === layerId);
                    return {
                      layerId,
                      originCenterX: Number(layer?.centerX || 0),
                      originCenterY: Number(layer?.centerY || 0),
                      originDisplayWidth: Number(layer?.displayWidth || 16),
                      originDisplayHeight: Number(layer?.displayHeight || 16),
                      originRotation: Number(layer?.rotation || 0),
                      lockScale: Boolean(layer?.lockScale),
                    };
                  }),
                };
                setNotice("Edit langsung: 1 jari geser, 2 jari scale/rotate layer.");
                return;
              }
            }
            if (mobileCanvasLocked) {
              setNotice(
                "Canvas terkunci. Gunakan tombol Lock Canvas untuk mengaktifkan pan/pinch lagi.",
              );
              return;
            }
          const anchor = screenToImagePoint(
              gestureSnapshot.centerX,
            gestureSnapshot.centerY,
          );
          startMobilePinchGesture({
            snapshot: gestureSnapshot,
            anchor,
            scale: view.scale,
          });
          interactionRef.current = {
            mode: "gesture",
            startX: gestureSnapshot.centerX,
            startY: gestureSnapshot.centerY,
            startPanX: view.panX,
            startPanY: view.panY,
          };
          setMobileCanvasMode("pan");
          return;
        }

        const longPressAnnotationId = findAnnotationByPoint(point);
        const longPressLayerId = findCutLayerByPoint(imagePoint);
        const longPressHkaId = findClosestHkaId(imagePoint);
        const longPressCircleId = findClosestCircleId(imagePoint);
        const longPressAngleId = findClosestAngleId(imagePoint);
        const longPressLineId = findClosestLineId(imagePoint);
        const longPressPlanningGuideId = findClosestPlanningGuideId(imagePoint);
        const hasMobileLongPressTarget =
          tool === "pan" &&
          mobileCanvasMode === "pan" &&
          (longPressAnnotationId !== null ||
            longPressLayerId !== null ||
            longPressHkaId !== null ||
            longPressCircleId !== null ||
            longPressAngleId !== null ||
            longPressLineId !== null ||
            longPressPlanningGuideId !== null);

        if (hasMobileLongPressTarget) {
          startMobileLongPress(pointerId, point, ({ point: currentPoint }) => {
            const hitImagePoint = clampToImageBounds(
              screenToImagePoint(currentPoint.x, currentPoint.y),
            );
            const annotationId = longPressAnnotationId;
            const layerId = longPressLayerId;
            const hkaId = longPressHkaId;
            const circleId = longPressCircleId;
            const angleId = longPressAngleId;
            const lineId = longPressLineId;
            const planningGuideId = longPressPlanningGuideId;
            const targetAnnotation = annotations.find(
              (annotation) => annotation.id === annotationId,
            );
            const targetLayer = cutLayers.find(
              (layer) => layer.id === layerId,
            );
            const targetLine = lines.find((line) => line.id === lineId);
            const targetCircle = circles.find(
              (circle) => circle.id === circleId,
            );
            const targetPlanningGuide = planningGuides.find(
              (guide) => guide.id === planningGuideId,
            );

            setMobileCanvasMode("edit");
            setTool("pan");
            setMobileToolMode("move");
            setMobileObjectSettingsOpen(false);
            if (annotationId !== null && targetAnnotation) {
              selectAnnotationFromCanvas(annotationId, { openPanel: false });
              setHistoryPaused(true);
              interactionRef.current = {
                mode: "move-annotation",
                annotationId,
                startImageX: hitImagePoint.x,
                startImageY: hitImagePoint.y,
                originX: targetAnnotation.x,
                originY: targetAnnotation.y,
              };
              setNotice("Anotasi dipilih. Tetap tahan dan geser untuk move.");
              return;
            }
            if (layerId !== null && targetLayer) {
              selectLayerFromCanvas(layerId, { openPanel: false });
              const selectedMoveLayerIds = getRelatedLayerIds(targetLayer.id, {
                includeGroup: true,
              });
              const movableLayerIds = selectedMoveLayerIds.filter((moveLayerId) =>
                cutLayers.some((item) => item.id === moveLayerId),
              );
              if (!movableLayerIds.length) {
                setNotice("Layer dipilih, tapi layer terkait tidak ditemukan.");
                return;
              }
              setHistoryPaused(true);
              interactionRef.current = {
                mode: "move-cut-layer",
                layerIds: movableLayerIds,
                startImageX: hitImagePoint.x,
                startImageY: hitImagePoint.y,
                origins: movableLayerIds.map((moveLayerId) => {
                  const layer = cutLayers.find(
                    (item) => item.id === moveLayerId,
                  );
                  return {
                    layerId: moveLayerId,
                    originCenterX: Number(layer?.centerX || 0),
                    originCenterY: Number(layer?.centerY || 0),
                  };
                }),
              };
              setNotice("Layer dipilih. Tetap tahan dan geser untuk move.");
              return;
            }
            if (hkaId !== null) {
              setSelectedHkaId(hkaId);
              setSelectedLineId(null);
              setSelectedAngleId(null);
              setSelectedCircleId(null);
              setSelectedCutLayerId(null);
              setSelectedAnnotationId(null);
              setSelectedPlanningGuideId(null);
              triggerSelectionPulse("hka", hkaId);
              setNotice("HKA dipilih. Tekan Setting untuk pengaturan.");
              return;
            }
            if (circleId !== null && targetCircle) {
              setSelectedCircleId(circleId);
              setSelectedLineId(null);
              setSelectedAngleId(null);
              setSelectedHkaId(null);
              setSelectedCutLayerId(null);
              setSelectedAnnotationId(null);
              setSelectedPlanningGuideId(null);
              triggerSelectionPulse("circle", circleId);
              setHistoryPaused(true);
              interactionRef.current = {
                mode: "move-circle-center",
                circleId,
                startImageX: hitImagePoint.x,
                startImageY: hitImagePoint.y,
                originCenterX: targetCircle.cx,
                originCenterY: targetCircle.cy,
              };
              setNotice("Circle dipilih. Tetap tahan dan geser untuk move.");
              return;
            }
            if (angleId !== null) {
              setSelectedAngleId(angleId);
              setSelectedLineId(null);
              setSelectedCircleId(null);
              setSelectedHkaId(null);
              setSelectedCutLayerId(null);
              setSelectedAnnotationId(null);
              setSelectedPlanningGuideId(null);
              triggerSelectionPulse("angle", angleId);
              setNotice("Angle dipilih. Tekan Setting untuk pengaturan.");
              return;
            }
            if (lineId !== null && targetLine) {
              setSelectedLineId(lineId);
              setSelectedAngleId(null);
              setSelectedCircleId(null);
              setSelectedHkaId(null);
              setSelectedCutLayerId(null);
              setSelectedAnnotationId(null);
              setSelectedPlanningGuideId(null);
              triggerSelectionPulse("line", lineId);
              if (isLineLocked(lineId)) {
                setNotice("Line dipilih. Line terkunci, buka lock dari Setting.");
                return;
              }
              setHistoryPaused(true);
              interactionRef.current = {
                mode: "move-line",
                lineId,
                startImageX: hitImagePoint.x,
                startImageY: hitImagePoint.y,
                origin: {
                  x1: targetLine.x1,
                  y1: targetLine.y1,
                  x2: targetLine.x2,
                  y2: targetLine.y2,
                },
              };
              setNotice("Line dipilih. Tetap tahan dan geser untuk move.");
              return;
            }
            if (planningGuideId !== null && targetPlanningGuide) {
              selectPlanningGuideForEdit(planningGuideId, { openPanel: false });
              setHistoryPaused(true);
              interactionRef.current = {
                mode: "move-planning-guide",
                guideId: planningGuideId,
                startImageX: hitImagePoint.x,
                startImageY: hitImagePoint.y,
                origin: {
                  startX: targetPlanningGuide.anchorStart.x,
                  startY: targetPlanningGuide.anchorStart.y,
                  endX: targetPlanningGuide.anchorEnd.x,
                  endY: targetPlanningGuide.anchorEnd.y,
                },
              };
              setNotice("Guide dipilih. Tetap tahan dan geser untuk move.");
            }
          }, { allowMovement: true });
          interactionRef.current = {
            mode: "mobile-long-press-pending",
            startX: point.x,
            startY: point.y,
            startPanX: view.panX,
            startPanY: view.panY,
          };
          return;
        }
      }

      if (
        isSimpleUiMode &&
          isMobileViewport &&
          isTouchLikePointer &&
          mobileCanvasMode === "pan" &&
          tool === "pan"
        ) {
          const directLayerId = findCutLayerByPoint(imagePoint);
          if (directLayerId !== null) {
            const targetLayer = cutLayers.find(
              (layer) => layer.id === directLayerId,
            );
            if (targetLayer) {
              selectLayerFromCanvas(directLayerId, {
                additive: isAdditiveLayerSelection,
                includeGroup: !isAdditiveLayerSelection,
                openPanel: false,
              });
              setSelectedFreeLinePointIndex(null);
              setSelectedLineId(null);
              setSelectedAngleId(null);
              setSelectedCircleId(null);
              setSelectedHkaId(null);
              setSelectedPlanningGuideId(null);
              triggerSelectionPulse("layer", targetLayer.id);
              clearMobileHandleAssist();
              clearMobilePlanningGuideHandleAssist();
              setMobileCanvasMode("edit");
              setMobileToolMode("move");
              syncMobileCanvasSelection("tool", {
                noticeText: "Layer aktif. Geser langsung dengan jari di layar.",
              });
              const selectedMoveLayerIds = selectedCutLayerIdsSet.has(targetLayer.id)
                ? selectedCutLayerIds
                : getRelatedLayerIds(targetLayer.id, { includeGroup: true });
              const movableLayerIds = selectedMoveLayerIds.filter((layerId) =>
                cutLayers.some((item) => item.id === layerId),
              );
              if (movableLayerIds.length > 0) {
                setHistoryPaused(true);
                interactionRef.current = {
                  mode: "move-cut-layer",
                  layerIds: movableLayerIds,
                  startImageX: imagePoint.x,
                  startImageY: imagePoint.y,
                  origins: movableLayerIds.map((layerId) => {
                    const layer = cutLayers.find((item) => item.id === layerId);
                    return {
                      layerId,
                      originCenterX: Number(layer?.centerX || 0),
                      originCenterY: Number(layer?.centerY || 0),
                    };
                  }),
                };
              }
              return;
            }
          }
          if (mobileCanvasLocked) {
            setNotice(
              "Canvas terkunci. Object tetap bisa diedit, pan canvas dinonaktifkan.",
            );
            return;
          }
          interactionRef.current = {
            mode: "pan",
          startX: point.x,
          startY: point.y,
          startPanX: view.panX,
          startPanY: view.panY,
        };
        return;
      }

      if (tool === "annotation") {
        addAnnotationAtPoint(boundedPoint);
        return;
      }

      // Pointer placement mode — next tap sets leader line tip
      if (placingAnnotationPointer !== null) {
        updateAnnotationById(placingAnnotationPointer, {
          px: boundedPoint.x,
          py: boundedPoint.y,
        });
        setPlacingAnnotationPointer(null);
        setMobileObjectSettingsOpen(true);
        return;
      }

      // Hit-test annotation pointer tip (leader line drag)
      const hitPointerAnnotId = findAnnotationPointerByPoint(point);
      if (hitPointerAnnotId !== null) {
        selectAnnotationFromCanvas(hitPointerAnnotId, { openPanel: false });
        setHistoryPaused(true);
        const ann = annotations.find((a) => a.id === hitPointerAnnotId);
        interactionRef.current = {
          mode: "move-annotation-pointer",
          annotationId: hitPointerAnnotId,
          startImageX: imagePoint.x,
          startImageY: imagePoint.y,
          originPx: ann?.px ?? imagePoint.x,
          originPy: ann?.py ?? imagePoint.y,
        };
        return;
      }

      const hitAnnotationId = findAnnotationByPoint(point);
      if (hitAnnotationId !== null) {
        const targetAnnotation = annotations.find(
          (annotation) => annotation.id === hitAnnotationId,
        );
        if (!targetAnnotation) return;
        selectAnnotationFromCanvas(hitAnnotationId, {
          openPanel: isTouchLikePointer,
        });
        setMobileObjectSettingsOpen(true);
        setHistoryPaused(true);
        interactionRef.current = {
          mode: "move-annotation",
          annotationId: hitAnnotationId,
          startImageX: imagePoint.x,
          startImageY: imagePoint.y,
          originX: targetAnnotation.x,
          originY: targetAnnotation.y,
        };
        setNotice("Geser label untuk pindah. Gunakan panel untuk tambah/ubah panah.");
        return;
      }

      if (tool === "freeLine") {
        setSelectedLineId(null);
        setSelectedAngleId(null);
        setSelectedCircleId(null);
        setSelectedHkaId(null);
        setSelectedCutLayerId(null);
        setSelectedAnnotationId(null);
        setSelectedPlanningGuideId(null);

        if (freeLineMode === "point") {
          const closeRadius = FREE_CUT_CLOSE_RADIUS_SCREEN / view.scale;

          if (draftFreeLine?.points?.length) {
            const startPoint = draftFreeLine.points[0];
            if (
              draftFreeLine.points.length < MIN_FREE_CUT_POINTS &&
              getDistance(startPoint, snappedPlacementPoint) <= closeRadius
            ) {
              setNotice(
                `Free Line: pilih ${MIN_FREE_CUT_POINTS - draftFreeLine.points.length} titik lagi.`,
              );
              return;
            }
            if (
              draftFreeLine.points.length >= MIN_FREE_CUT_POINTS &&
              getDistance(startPoint, snappedPlacementPoint) <= closeRadius
            ) {
              completeDraftFreeLine();
              return;
            }

            const lastPoint =
              draftFreeLine.points[draftFreeLine.points.length - 1];
            if (getDistance(lastPoint, snappedPlacementPoint) <= 1.5) {
              return;
            }

            const nextPoints = [...draftFreeLine.points, snappedPlacementPoint];
            setDraftFreeLine((prev) =>
              prev
                ? {
                    ...prev,
                    points: nextPoints,
                    hoverPoint: snappedPlacementPoint,
                  }
                : prev,
            );
            setHistoryPaused(true);
            setNotice(
              nextPoints.length >= MIN_FREE_CUT_POINTS
                ? "Free Line: lanjutkan titik atau klik titik awal untuk selesai."
                : `Free Line: pilih ${MIN_FREE_CUT_POINTS - nextPoints.length} titik lagi.`,
            );
            return;
          }

          setDraftFreeLine({
            points: [snappedPlacementPoint],
            hoverPoint: snappedPlacementPoint,
            fillColor: DEFAULT_FREE_LINE_COLOR,
            drawMode: "point",
          });
          setHistoryPaused(true);
          setNotice(
            "Free Line Point Mode: klik beberapa titik, lalu klik titik awal atau tekan Enter untuk selesai.",
          );
          return;
        }

        setDraftFreeLine({
          points: [snappedPlacementPoint],
          fillColor: DEFAULT_FREE_LINE_COLOR,
          drawMode: "freehand",
        });
        setHistoryPaused(true);
        interactionRef.current = {
          mode: "draw-free-line",
        };
        setNotice("Free Line aktif. Drag untuk menggambar shape bebas.");
        return;
      }

      if (tool === "pan" && isTouchLikePointer) {
        const assistHandleHit = findMobileHandleAssistHit(point);
        if (assistHandleHit) {
          const targetLine = lines.find(
            (line) => line.id === assistHandleHit.lineId,
          );
          if (!targetLine) return;
          if (targetLine.type) {
            setLinePreset(targetLine.type);
          }
          setSelectedLineId(targetLine.id);
          setSelectedAngleId(null);
          setSelectedCircleId(null);
          setSelectedHkaId(null);
          setSelectedCutLayerId(null);
          setSelectedPlanningGuideId(null);
          triggerSelectionPulse("line", targetLine.id);
          if (isLineLocked(targetLine.id)) {
            setNotice("Garis ini terkunci. Unlock dulu sebelum di-adjust.");
            return;
          }
          const assistGeometry = getMobileHandleAssistGeometry(
            targetLine,
            assistHandleHit.handleKey,
          );
          setHistoryPaused(true);
          interactionRef.current = {
            mode: "move-handle",
            lineId: targetLine.id,
            handleKey: assistHandleHit.handleKey,
            pointerOffsetX: assistGeometry
              ? assistGeometry.handleImagePoint.x - boundedPoint.x
              : 0,
            pointerOffsetY: assistGeometry
              ? assistGeometry.handleImagePoint.y - boundedPoint.y
              : 0,
          };
          setNotice(
            "Adjust ujung line aktif. Geser dari area bundaran, titik handle tetap terlihat dan tidak dipaksa ke tengah jari.",
          );
          return;
        }

        const assistAngleHandleHit = findMobileAngleHandleAssistHit(point);
        if (assistAngleHandleHit) {
          const targetAngle = angles.find(
            (angle) => angle.id === assistAngleHandleHit.angleId,
          );
          if (!targetAngle) return;
          setMobilePanelMode("workspace");
          setActiveRightPanel("measure");
          setSelectedAngleId(targetAngle.id);
          setSelectedLineId(null);
          setSelectedFreeLinePointIndex(null);
          setSelectedCircleId(null);
          setSelectedHkaId(null);
          setSelectedCutLayerId(null);
          setSelectedPlanningGuideId(null);
          triggerSelectionPulse("angle", targetAngle.id);
          clearMobileHandleAssist();
          clearMobilePlanningGuideHandleAssist();
          setHistoryPaused(true);
          const assistGeometry = getMobileAngleHandleAssistGeometry(
            targetAngle,
            assistAngleHandleHit.handleKey,
          );
          interactionRef.current = {
            mode: "move-angle-handle",
            angleId: targetAngle.id,
            handleKey: assistAngleHandleHit.handleKey,
            pointerOffsetX: assistGeometry
              ? assistGeometry.handleImagePoint.x - boundedPoint.x
              : 0,
            pointerOffsetY: assistGeometry
              ? assistGeometry.handleImagePoint.y - boundedPoint.y
              : 0,
          };
          setNotice(
            "Adjust titik angle aktif. Geser dari area bundaran agar titik tetap terlihat.",
          );
          return;
        }

        const assistHkaHandleHit = findMobileHkaHandleAssistHit(point);
        if (assistHkaHandleHit) {
          const targetItem = hkaSets.find(
            (item) => item.id === assistHkaHandleHit.hkaId,
          );
          if (!targetItem) return;
          setMobilePanelMode("workspace");
          setActiveRightPanel("measure");
          setSelectedHkaId(targetItem.id);
          setSelectedLineId(null);
          setSelectedFreeLinePointIndex(null);
          setSelectedAngleId(null);
          setSelectedCircleId(null);
          setSelectedCutLayerId(null);
          setSelectedPlanningGuideId(null);
          triggerSelectionPulse("hka", targetItem.id);
          clearMobileHandleAssist();
          clearMobilePlanningGuideHandleAssist();
          setHistoryPaused(true);
          const assistGeometry = getMobileHkaHandleAssistGeometry(
            targetItem,
            assistHkaHandleHit.handleKey,
          );
          interactionRef.current = {
            mode: "move-hka-handle",
            hkaId: targetItem.id,
            handleKey: assistHkaHandleHit.handleKey,
            pointerOffsetX: assistGeometry
              ? assistGeometry.handleImagePoint.x - boundedPoint.x
              : 0,
            pointerOffsetY: assistGeometry
              ? assistGeometry.handleImagePoint.y - boundedPoint.y
              : 0,
          };
          setNotice(
            "Adjust titik HKA aktif. Geser dari area bundaran agar landmark tetap terlihat.",
          );
          return;
        }

        const hitHandle = findClosestHandle(imagePoint);
        if (hitHandle) {
          const targetLine = lines.find((line) => line.id === hitHandle.lineId);
          if (!targetLine) return;
          if (targetLine.type) {
            setLinePreset(targetLine.type);
          }
          setSelectedLineId(targetLine.id);
          setSelectedAngleId(null);
          setSelectedCircleId(null);
          setSelectedHkaId(null);
          setSelectedCutLayerId(null);
          setSelectedPlanningGuideId(null);
          triggerSelectionPulse("line", targetLine.id);
          if (isLineLocked(targetLine.id)) {
            setNotice("Garis ini terkunci. Unlock dulu sebelum di-adjust.");
            return;
          }
          activateMobileHandleAssist(targetLine.id, hitHandle.handleKey);
          if (isMobileViewport) {
            setMobileControlsOpen(false);
          }
          setNotice(
            "Ujung line dipilih. Bundaran assist aktif, sentuh area putih bundaran untuk adjust tanpa menutupi titik handle.",
          );
          return;
        }

        const hitLineId = findClosestLineId(imagePoint);
        if (hitLineId !== null) {
          const targetLine = lines.find((line) => line.id === hitLineId);
          if (!targetLine) return;
          if (targetLine.type) {
            setLinePreset(targetLine.type);
          }
          setSelectedLineId(hitLineId);
          setSelectedAngleId(null);
          setSelectedCircleId(null);
          setSelectedHkaId(null);
          setSelectedCutLayerId(null);
          setSelectedPlanningGuideId(null);
          triggerSelectionPulse("line", hitLineId);
          clearMobileHandleAssist();
          if (isSimpleUiMode && hitLineId === calibrationLineId) {
            openSimpleCalibrationModal();
            return;
          }
          if (isLineLocked(hitLineId)) {
            setNotice("Garis ini terkunci. Unlock dulu sebelum dipindah.");
            return;
          }
          if (isMobileViewport) {
            setMobileControlsOpen(false);
          }
          const shouldMoveLine = isRepeatedMobileLineTap({
            targetType: "line-body",
            lineId: hitLineId,
          });
          if (!shouldMoveLine) {
            setNotice(
              "Garis dipilih. Tap lagi pada badan garis untuk pindah, atau sentuh ujung garis untuk adjust panjang.",
            );
            return;
          }
          setHistoryPaused(true);
          interactionRef.current = {
            mode: "move-line",
            lineId: hitLineId,
            startImageX: imagePoint.x,
            startImageY: imagePoint.y,
            origin: {
              x1: targetLine.x1,
              y1: targetLine.y1,
              x2: targetLine.x2,
              y2: targetLine.y2,
            },
          };
          setNotice("Move line aktif. Geser jari untuk memindahkan garis.");
          return;
        }
      }

      if (tool === "cut") {
        const closeRadius = FREE_CUT_CLOSE_RADIUS_SCREEN / view.scale;
        const activeCutTargetLayer =
          draftCut?.targetLayerId !== null &&
          draftCut?.targetLayerId !== undefined
            ? cutLayers.find((layer) => layer.id === draftCut.targetLayerId) ||
              null
            : selectedCutLayer &&
                !selectedCutLayer.hidden &&
                isImageBackedLayerKind(selectedCutLayer.kind)
              ? selectedCutLayer
              : null;

        setSelectedLineId(null);
        setSelectedFreeLinePointIndex(null);
        setSelectedAngleId(null);
        setSelectedCircleId(null);
        setSelectedHkaId(null);
        setSelectedCutLayerId(null);
        setSelectedPlanningGuideId(null);

        if (draftCut?.points?.length) {
          const startPoint = draftCut.points[0];
          if (
            draftCut.points.length < MIN_FREE_CUT_POINTS &&
            getDistance(startPoint, snappedPlacementPoint) <= closeRadius
          ) {
            setNotice(
              `Free cut: pilih ${MIN_FREE_CUT_POINTS - draftCut.points.length} titik lagi.`,
            );
            return;
          }
          if (
            draftCut.points.length >= MIN_FREE_CUT_POINTS &&
            getDistance(startPoint, snappedPlacementPoint) <= closeRadius
          ) {
            completeDraftCut();
            return;
          }

          const lastPoint = draftCut.points[draftCut.points.length - 1];
          if (getDistance(lastPoint, snappedPlacementPoint) <= 1.5) {
            return;
          }

          const nextPoints = [...draftCut.points, snappedPlacementPoint];
          setDraftCut({
            targetLayerId: draftCut.targetLayerId ?? activeCutTargetLayer?.id ?? null,
            points: nextPoints,
            hoverPoint: snappedPlacementPoint,
          });
          setHistoryPaused(true);
          setNotice(
            nextPoints.length >= MIN_FREE_CUT_POINTS
              ? "Free cut: lanjutkan titik atau klik titik awal untuk selesai."
              : `Free cut: pilih ${MIN_FREE_CUT_POINTS - nextPoints.length} titik lagi.`,
          );
          return;
        }

        setDraftCut({
          targetLayerId: activeCutTargetLayer?.id ?? null,
          points: [snappedPlacementPoint],
          hoverPoint: snappedPlacementPoint,
        });
        setHistoryPaused(true);
        setNotice(
          activeCutTargetLayer
            ? `Free cut layer aktif: ${activeCutTargetLayer.name || `Layer #${activeCutTargetLayer.id}`}. Klik beberapa titik, lalu klik titik awal atau tekan Enter untuk selesai.`
            : "Free cut: klik beberapa titik mengikuti bentuk objek, lalu klik titik awal atau tekan Enter untuk selesai.",
        );
        return;
      }

      if (tool === "pan") {
        const hitFreeLineCurveHandle = findFreeLineCurveHandle(imagePoint);
        if (hitFreeLineCurveHandle) {
          const targetLayer = cutLayers.find(
            (layer) => layer.id === hitFreeLineCurveHandle.layerId,
          );
          if (!targetLayer) return;
          focusLayerCanvas(targetLayer.id);
          setSelectedFreeLinePointIndex(hitFreeLineCurveHandle.pointIndex);
          setSelectedLineId(null);
          setSelectedAngleId(null);
          setSelectedCircleId(null);
          setSelectedHkaId(null);
          setSelectedPlanningGuideId(null);
          triggerSelectionPulse("layer", targetLayer.id);
          clearMobileHandleAssist();
          clearMobilePlanningGuideHandleAssist();
          syncMobileCanvasSelection("tool");
          if (targetLayer.lockScale) {
            setNotice("Layer terkunci. Buka lock dulu untuk edit lengkungan.");
            return;
          }
          setHistoryPaused(true);
          interactionRef.current = {
            mode: "move-free-line-curve-handle",
            layerId: targetLayer.id,
            pointIndex: hitFreeLineCurveHandle.pointIndex,
            handleKey: hitFreeLineCurveHandle.handleKey,
          };
          setNotice(
            "Handle lengkung aktif. Geser bebas 360 derajat untuk mencari rounded yang paling pas.",
          );
          return;
        }

        const hitFreeLinePointHandle = findFreeLinePointHandle(imagePoint);
        if (hitFreeLinePointHandle) {
          const targetLayer = cutLayers.find(
            (layer) => layer.id === hitFreeLinePointHandle.layerId,
          );
          if (!targetLayer) return;
          focusLayerCanvas(targetLayer.id);
          setSelectedFreeLinePointIndex(hitFreeLinePointHandle.pointIndex);
          setSelectedLineId(null);
          setSelectedAngleId(null);
          setSelectedCircleId(null);
          setSelectedHkaId(null);
          setSelectedPlanningGuideId(null);
          triggerSelectionPulse("layer", targetLayer.id);
          clearMobileHandleAssist();
          clearMobilePlanningGuideHandleAssist();
          syncMobileCanvasSelection("tool");
          if (targetLayer.lockScale) {
            setNotice("Layer terkunci. Buka lock dulu untuk edit titik shape.");
            return;
          }
          setHistoryPaused(true);
          interactionRef.current = {
            mode: "move-free-line-point",
            layerId: targetLayer.id,
            pointIndex: hitFreeLinePointHandle.pointIndex,
          };
          setNotice(
            "Edit titik Free Line aktif. Geser vertex untuk membentuk ulang shape.",
          );
          return;
        }

        const allowLayerTransformHandle =
          !(isSimpleUiMode && isMobileViewport && isTouchLikePointer) ||
          mobileToolMode !== "move";
        const hitCutLayerHandle = allowLayerTransformHandle
          ? findCutLayerHandle(imagePoint)
          : null;
        if (hitCutLayerHandle) {
          const targetLayer = cutLayers.find(
            (layer) => layer.id === hitCutLayerHandle.layerId,
          );
          if (!targetLayer) return;
          const isRotateHandle = hitCutLayerHandle.handleKey === "rotate";
          if (shouldBlockTransformHandle({ isTouchLikePointer, isRotateHandle })) {
            setNotice(getTransformHandleGuardNotice());
            return;
          }
          focusLayerCanvas(targetLayer.id);
          setSelectedFreeLinePointIndex(null);
          setSelectedLineId(null);
          setSelectedAngleId(null);
          setSelectedCircleId(null);
          setSelectedHkaId(null);
          setSelectedPlanningGuideId(null);
          triggerSelectionPulse("layer", targetLayer.id);
          clearMobileHandleAssist();
          clearMobilePlanningGuideHandleAssist();
          syncMobileCanvasSelection("tool");
          if (targetLayer.lockScale && !isRotateHandle) {
            setNotice(
              "Scale layer terkunci. Buka Lock Scale dulu untuk resize.",
            );
            return;
          }
          setHistoryPaused(true);
          if (isRotateHandle) {
            interactionRef.current = {
              mode: "rotate-cut-layer",
              layerId: targetLayer.id,
              centerX: targetLayer.centerX,
              centerY: targetLayer.centerY,
              startPointerAngle: Math.atan2(
                imagePoint.y - targetLayer.centerY,
                imagePoint.x - targetLayer.centerX,
              ),
              startRotation: Number(targetLayer.rotation || 0),
            };
            return;
          }
          interactionRef.current = {
            mode: "resize-cut-layer",
            layerId: targetLayer.id,
            centerX: targetLayer.centerX,
            centerY: targetLayer.centerY,
            rotation: targetLayer.rotation,
            handleKey: hitCutLayerHandle.handleKey,
            startFlipX: Boolean(targetLayer.flipX),
            startFlipY: Boolean(targetLayer.flipY),
            startDisplayWidth: Number(targetLayer.displayWidth || 16),
            startDisplayHeight: Number(targetLayer.displayHeight || 16),
          };
          return;
        }

        const hitCutLayerId = findCutLayerByPoint(imagePoint);
        if (hitCutLayerId !== null) {
          const targetLayer = cutLayers.find(
            (layer) => layer.id === hitCutLayerId,
          );
          if (!targetLayer) return;
          selectLayerFromCanvas(hitCutLayerId, {
            additive: isAdditiveLayerSelection,
            includeGroup: !isAdditiveLayerSelection,
          });
          setSelectedFreeLinePointIndex(null);
          setSelectedLineId(null);
          setSelectedAngleId(null);
          setSelectedCircleId(null);
          setSelectedHkaId(null);
          setSelectedPlanningGuideId(null);
          triggerSelectionPulse("layer", targetLayer.id);
          clearMobileHandleAssist();
          clearMobilePlanningGuideHandleAssist();
          syncMobileCanvasSelection("tool");
          if (isAdditiveLayerSelection) {
            setNotice(
              selectedCutLayerIdsSet.has(targetLayer.id)
                ? `Layer #${targetLayer.id} dilepas dari multi-select.`
                : `Layer #${targetLayer.id} ditambahkan ke multi-select.`,
            );
            return;
          }
          if (
            isSimpleUiMode &&
            isMobileViewport &&
            isTouchLikePointer &&
            mobileToolMode === "scale"
          ) {
            if (targetLayer.lockScale) {
              setNotice("Scale layer terkunci. Buka Lock Scale dulu.");
              return;
            }
            setHistoryPaused(true);
            interactionRef.current = {
              mode: "mobile-scale-cut-layer",
              layerId: targetLayer.id,
              startX: point.x,
              startY: point.y,
              startDisplayWidth: Number(targetLayer.displayWidth || 16),
              startDisplayHeight: Number(targetLayer.displayHeight || 16),
            };
            setNotice(
              "Size layer aktif. Drag kanan/atas untuk membesarkan, kiri/bawah untuk mengecilkan.",
            );
            return;
          }
          if (
            isSimpleUiMode &&
            isMobileViewport &&
            isTouchLikePointer &&
            mobileToolMode === "rotate"
          ) {
            setHistoryPaused(true);
            interactionRef.current = {
              mode: "mobile-rotate-cut-layer",
              layerId: targetLayer.id,
              startX: point.x,
              startY: point.y,
              startRotation: Number(targetLayer.rotation || 0),
            };
            setNotice("Putar layer aktif. Geser kiri/kanan untuk rotasi halus.");
            return;
          }
          const selectedMoveLayerIds = selectedCutLayerIdsSet.has(targetLayer.id)
            ? selectedCutLayerIds
            : getRelatedLayerIds(targetLayer.id, { includeGroup: true });
          const movableLayerIds = selectedMoveLayerIds.filter((layerId) =>
            cutLayers.some((item) => item.id === layerId),
          );
          if (!movableLayerIds.length) {
            setNotice("Layer terkait tidak ditemukan.");
            return;
          }
          setHistoryPaused(true);
          interactionRef.current = {
            mode: "move-cut-layer",
            layerIds: movableLayerIds,
            startImageX: imagePoint.x,
            startImageY: imagePoint.y,
            origins: movableLayerIds.map((layerId) => {
              const layer = cutLayers.find((item) => item.id === layerId);
              return {
                layerId,
                originCenterX: Number(layer?.centerX || 0),
                originCenterY: Number(layer?.centerY || 0),
              };
            }),
          };
          return;
        }
      }

      const hitPlanningGuideLabelId = findPlanningGuideLabelByPoint(point);
      if (hitPlanningGuideLabelId !== null) {
        const targetGuide = planningGuides.find(
          (guide) => guide.id === hitPlanningGuideLabelId,
        );
        if (!targetGuide) return;
        if (isTouchLikePointer) {
          focusPlanningGuideCanvas(targetGuide.id, {
            openPanel: true,
            showNotice: true,
          });
          clearMobileHandleAssist();
        } else {
          selectPlanningGuideForEdit(targetGuide.id);
        }
        setSelectedLineId(null);
        setSelectedFreeLinePointIndex(null);
        setSelectedAngleId(null);
        setSelectedCircleId(null);
        setSelectedHkaId(null);
        setSelectedCutLayerId(null);
        triggerSelectionPulse("planning", targetGuide.id);
        clearMobilePlanningGuideHandleAssist();
        setHistoryPaused(true);
        interactionRef.current = {
          mode: "move-planning-guide-label",
          guideId: targetGuide.id,
          startX: point.x,
          startY: point.y,
          originOffsetX: Number.isFinite(targetGuide.labelOffsetX)
            ? targetGuide.labelOffsetX
            : DEFAULT_GUIDE_LABEL_OFFSET_X,
          originOffsetY: Number.isFinite(targetGuide.labelOffsetY)
            ? targetGuide.labelOffsetY
            : DEFAULT_GUIDE_LABEL_OFFSET_Y,
        };
        return;
      }

      const assistPlanningGuideHandleHit =
        findMobilePlanningGuideHandleAssistHit(point);
      if (assistPlanningGuideHandleHit) {
        const targetGuide = planningGuides.find(
          (guide) => guide.id === assistPlanningGuideHandleHit.guideId,
        );
        if (!targetGuide) return;
        focusPlanningGuideCanvas(targetGuide.id);
        triggerSelectionPulse("planning", targetGuide.id);
        clearMobileHandleAssist();
        setSelectedLineId(null);
        setSelectedFreeLinePointIndex(null);
        setSelectedAngleId(null);
        setSelectedCircleId(null);
        setSelectedHkaId(null);
        setSelectedCutLayerId(null);
        clearMobilePlanningGuideHandleAssist();
        const assistGeometry = getMobilePlanningGuideHandleAssistGeometry(
          targetGuide,
          assistPlanningGuideHandleHit.handleKey,
        );
        setHistoryPaused(true);
        interactionRef.current = {
          mode: "move-planning-guide-handle",
          guideId: targetGuide.id,
          handleKey: assistPlanningGuideHandleHit.handleKey,
          pointerOffsetX: assistGeometry
            ? assistGeometry.handleImagePoint.x - boundedPoint.x
            : 0,
          pointerOffsetY: assistGeometry
            ? assistGeometry.handleImagePoint.y - boundedPoint.y
            : 0,
        };
        setNotice(
          "Adjust planning guide aktif. Geser dari area bundaran, titik handle tetap terlihat.",
        );
        return;
      }

      const hitPlanningGuideHandle = findClosestPlanningGuideHandle(imagePoint);
      if (hitPlanningGuideHandle) {
        const targetGuide = planningGuides.find(
          (guide) => guide.id === hitPlanningGuideHandle.guideId,
        );
        if (!targetGuide) return;
        if (isTouchLikePointer) {
          focusPlanningGuideCanvas(targetGuide.id);
          triggerSelectionPulse("planning", targetGuide.id);
          clearMobileHandleAssist();
          activateMobilePlanningGuideHandleAssist(
            targetGuide.id,
            hitPlanningGuideHandle.handleKey,
          );
          if (isMobileViewport) {
            setMobileControlsOpen(false);
          }
          setNotice(
            "Ujung planning guide dipilih. Bundaran assist aktif untuk Distal Cut, Tibial Cut, dan Tibial Slope.",
          );
          return;
        }
        selectPlanningGuideForEdit(targetGuide.id);
        triggerSelectionPulse("planning", targetGuide.id);
        setSelectedLineId(null);
        setSelectedFreeLinePointIndex(null);
        setSelectedAngleId(null);
        setSelectedCircleId(null);
        setSelectedHkaId(null);
        setSelectedCutLayerId(null);
        clearMobilePlanningGuideHandleAssist();
        interactionRef.current = {
          mode: "move-planning-guide-handle",
          guideId: targetGuide.id,
          handleKey: hitPlanningGuideHandle.handleKey,
        };
        return;
      }

      const hitPlanningGuideId = findClosestPlanningGuideId(imagePoint);
      if (hitPlanningGuideId !== null) {
        const targetGuide = planningGuides.find(
          (guide) => guide.id === hitPlanningGuideId,
        );
        if (!targetGuide) return;
        if (isTouchLikePointer) {
          focusPlanningGuideCanvas(targetGuide.id, {
            openPanel: true,
            showNotice: true,
          });
          triggerSelectionPulse("planning", targetGuide.id);
          clearMobileHandleAssist();
          clearMobilePlanningGuideHandleAssist();
        } else {
          selectPlanningGuideForEdit(targetGuide.id);
          triggerSelectionPulse("planning", targetGuide.id);
        }
        setSelectedLineId(null);
        setSelectedFreeLinePointIndex(null);
        setSelectedAngleId(null);
        setSelectedCircleId(null);
        setSelectedHkaId(null);
        setSelectedCutLayerId(null);
        clearMobilePlanningGuideHandleAssist();
        interactionRef.current = {
          mode: "move-planning-guide",
          guideId: targetGuide.id,
          startImageX: imagePoint.x,
          startImageY: imagePoint.y,
          origin: {
            startX: targetGuide.anchorStart.x,
            startY: targetGuide.anchorStart.y,
            endX: targetGuide.anchorEnd.x,
            endY: targetGuide.anchorEnd.y,
          },
        };
        return;
      }

      const hitLineLabelId = findLineLabelByPoint(point);
      if (hitLineLabelId !== null) {
        const targetLine = lines.find((line) => line.id === hitLineLabelId);
        if (!targetLine) return;
        if (targetLine.type) {
          setLinePreset(targetLine.type);
        }
        setMobilePanelMode("workspace");
        setActiveRightPanel("measure");
        setSelectedLineId(targetLine.id);
        setSelectedPlanningGuideId(null);
        setSelectedAngleId(null);
        setSelectedCircleId(null);
        setSelectedHkaId(null);
        setSelectedCutLayerId(null);
        setSelectedFreeLinePointIndex(null);
        triggerSelectionPulse("line", targetLine.id);
        clearMobileHandleAssist();
        clearMobilePlanningGuideHandleAssist();
        syncMobileCanvasSelection("measure");
        if (isLineLocked(targetLine.id)) {
          setNotice(
            "Garis ini terkunci. Buka lock dulu untuk memindahkan label.",
          );
          return;
        }
        setHistoryPaused(true);
        interactionRef.current = {
          mode: "move-line-label",
          lineId: targetLine.id,
          startX: point.x,
          startY: point.y,
          originOffsetX: Number.isFinite(targetLine.labelOffsetX)
            ? targetLine.labelOffsetX
            : DEFAULT_LINE_LABEL_OFFSET_X,
          originOffsetY: Number.isFinite(targetLine.labelOffsetY)
            ? targetLine.labelOffsetY
            : DEFAULT_LINE_LABEL_OFFSET_Y,
        };
        return;
      }

      const hitAngleLabelId = findAngleLabelByPoint(point);
      if (hitAngleLabelId !== null) {
        const targetAngle = angles.find((angle) => angle.id === hitAngleLabelId);
        if (!targetAngle) return;
        setMobilePanelMode("workspace");
        setActiveRightPanel("measure");
        setSelectedAngleId(targetAngle.id);
        setSelectedLineId(null);
        setSelectedFreeLinePointIndex(null);
        setSelectedCircleId(null);
        setSelectedHkaId(null);
        setSelectedCutLayerId(null);
        setSelectedPlanningGuideId(null);
        triggerSelectionPulse("angle", targetAngle.id);
        clearMobileHandleAssist();
        clearMobileAngleHandleAssist();
        clearMobilePlanningGuideHandleAssist();
        if (isMobileViewport) {
          setMobileControlsOpen(false);
        }
        setHistoryPaused(true);
        interactionRef.current = {
          mode: "move-angle-label",
          angleId: targetAngle.id,
          startX: point.x,
          startY: point.y,
          originOffsetX: Number.isFinite(targetAngle.labelOffsetX)
            ? targetAngle.labelOffsetX
            : DEFAULT_ANGLE_LABEL_OFFSET_X,
          originOffsetY: Number.isFinite(targetAngle.labelOffsetY)
            ? targetAngle.labelOffsetY
            : DEFAULT_ANGLE_LABEL_OFFSET_Y,
        };
        setNotice("Hasil angle aktif. Geser label hasil untuk memindahkannya.");
        return;
      }

      const hitHkaLabelId = findHkaLabelByPoint(point);
      if (hitHkaLabelId !== null) {
        const targetItem = hkaSets.find((item) => item.id === hitHkaLabelId);
        if (!targetItem) return;
        setMobilePanelMode("workspace");
        setActiveRightPanel("measure");
        setSelectedHkaId(targetItem.id);
        setSelectedLineId(null);
        setSelectedFreeLinePointIndex(null);
        setSelectedAngleId(null);
        setSelectedCircleId(null);
        setSelectedCutLayerId(null);
        setSelectedPlanningGuideId(null);
        triggerSelectionPulse("hka", targetItem.id);
        clearMobileHandleAssist();
        clearMobileHkaHandleAssist();
        clearMobilePlanningGuideHandleAssist();
        if (isMobileViewport) {
          setMobileControlsOpen(false);
        }
        setHistoryPaused(true);
        interactionRef.current = {
          mode: "move-hka-label",
          hkaId: targetItem.id,
          startX: point.x,
          startY: point.y,
          originOffsetX: Number.isFinite(targetItem.labelOffsetX)
            ? targetItem.labelOffsetX
            : DEFAULT_HKA_LABEL_OFFSET_X,
          originOffsetY: Number.isFinite(targetItem.labelOffsetY)
            ? targetItem.labelOffsetY
            : DEFAULT_HKA_LABEL_OFFSET_Y,
        };
        setNotice("Hasil HKA aktif. Geser label hasil untuk memindahkannya.");
        return;
      }

      const hitCircleLabelId = findCircleLabelByPoint(point);
      if (hitCircleLabelId !== null) {
        const targetCircle = circles.find((c) => c.id === hitCircleLabelId);
        if (!targetCircle) return;
        setMobilePanelMode("workspace");
        setActiveRightPanel("measure");
        setSelectedCircleId(targetCircle.id);
        setSelectedLineId(null);
        setSelectedFreeLinePointIndex(null);
        setSelectedAngleId(null);
        setSelectedHkaId(null);
        setSelectedCutLayerId(null);
        setSelectedPlanningGuideId(null);
        triggerSelectionPulse("circle", targetCircle.id);
        clearMobileHandleAssist();
        clearMobilePlanningGuideHandleAssist();
        setHistoryPaused(true);
        interactionRef.current = {
          mode: "move-circle-label",
          circleId: targetCircle.id,
          startX: point.x,
          startY: point.y,
          originOffsetX: targetCircle.labelOffsetX ?? 0,
          originOffsetY: targetCircle.labelOffsetY ?? 0,
        };
        return;
      }

      const genericHitHandle = findClosestHandle(imagePoint);
      if (genericHitHandle) {
        const targetLine = lines.find(
          (line) => line.id === genericHitHandle.lineId,
        );
        if (targetLine?.type) {
          setLinePreset(targetLine.type);
        }
        setMobilePanelMode("workspace");
        setActiveRightPanel("measure");
        setSelectedLineId(genericHitHandle.lineId);
        setSelectedPlanningGuideId(null);
        setSelectedAngleId(null);
        setSelectedCircleId(null);
        setSelectedHkaId(null);
        setSelectedCutLayerId(null);
        setSelectedFreeLinePointIndex(null);
        triggerSelectionPulse("line", genericHitHandle.lineId);
        clearMobilePlanningGuideHandleAssist();
        syncMobileCanvasSelection("measure");
        if (isLineLocked(genericHitHandle.lineId)) {
          setNotice(
            "Garis ini terkunci. Buka lock dulu untuk mengubah ukuran/posisi.",
          );
          return;
        }
        setHistoryPaused(true);
        interactionRef.current = {
          mode: "move-handle",
          lineId: genericHitHandle.lineId,
          handleKey: genericHitHandle.handleKey,
        };
        return;
      }

      const genericHitLineId = findClosestLineId(imagePoint);
      if (genericHitLineId !== null) {
        const targetLine = lines.find((line) => line.id === genericHitLineId);
        if (!targetLine) return;
        if (targetLine.type) {
          setLinePreset(targetLine.type);
        }
        setMobilePanelMode("workspace");
        setActiveRightPanel("measure");
        setSelectedLineId(genericHitLineId);
        setSelectedPlanningGuideId(null);
        setSelectedAngleId(null);
        setSelectedCircleId(null);
        setSelectedHkaId(null);
        setSelectedCutLayerId(null);
        setSelectedFreeLinePointIndex(null);
        triggerSelectionPulse("line", genericHitLineId);
        clearMobileHandleAssist();
        clearMobilePlanningGuideHandleAssist();
        syncMobileCanvasSelection("measure");
        if (isLineLocked(genericHitLineId)) {
          setNotice(
            "Garis ini terkunci. Buka lock dulu untuk mengubah ukuran/posisi.",
          );
          return;
        }
        setHistoryPaused(true);
        interactionRef.current = {
          mode: "move-line",
          lineId: genericHitLineId,
          startImageX: imagePoint.x,
          startImageY: imagePoint.y,
          origin: {
            x1: targetLine.x1,
            y1: targetLine.y1,
            x2: targetLine.x2,
            y2: targetLine.y2,
          },
        };
        return;
      }

      const genericAngleHandle = findClosestAngleHandle(boundedPoint);
      if (genericAngleHandle) {
        const targetAngle = angles.find(
          (angle) => angle.id === genericAngleHandle.angleId,
        );
        if (!targetAngle) return;
        setMobilePanelMode("workspace");
        setActiveRightPanel("measure");
        setSelectedAngleId(targetAngle.id);
        setSelectedLineId(null);
        setSelectedFreeLinePointIndex(null);
        setSelectedCircleId(null);
        setSelectedHkaId(null);
        setSelectedCutLayerId(null);
        setSelectedPlanningGuideId(null);
        triggerSelectionPulse("angle", targetAngle.id);
        clearMobileHandleAssist();
        clearMobilePlanningGuideHandleAssist();
        if (isTouchLikePointer) {
          activateMobileAngleHandleAssist(
            targetAngle.id,
            genericAngleHandle.handleKey,
          );
          syncMobileCanvasSelection("measure", {
            noticeText:
              "Titik angle dipilih. Bundaran assist aktif untuk adjust yang lebih presisi.",
          });
          return;
        }
        syncMobileCanvasSelection("measure");
        if (tool === "pan" || tool === "angle") {
          setHistoryPaused(true);
          interactionRef.current = {
            mode: "move-angle-handle",
            angleId: genericAngleHandle.angleId,
            handleKey: genericAngleHandle.handleKey,
          };
        }
        return;
      }

      const genericAngleId = findClosestAngleId(imagePoint);
      if (genericAngleId !== null) {
        setMobilePanelMode("workspace");
        setActiveRightPanel("measure");
        setSelectedAngleId(genericAngleId);
        setSelectedLineId(null);
        setSelectedFreeLinePointIndex(null);
        setSelectedCircleId(null);
        setSelectedHkaId(null);
        setSelectedCutLayerId(null);
        setSelectedPlanningGuideId(null);
        triggerSelectionPulse("angle", genericAngleId);
        clearMobileHandleAssist();
        clearMobileAngleHandleAssist();
        clearMobilePlanningGuideHandleAssist();
        syncMobileCanvasSelection("measure", {
          noticeText: "Angle aktif. Tap titik atau drag untuk atur ulang.",
        });
        return;
      }

      const genericCircleHandle = findClosestCircleHandle(boundedPoint);
      if (genericCircleHandle) {
        const targetCircle = circles.find(
          (circle) => circle.id === genericCircleHandle.circleId,
        );
        if (!targetCircle) return;
        setMobilePanelMode("workspace");
        setActiveRightPanel("measure");
        setSelectedCircleId(targetCircle.id);
        setSelectedLineId(null);
        setSelectedFreeLinePointIndex(null);
        setSelectedAngleId(null);
        setSelectedHkaId(null);
        setSelectedCutLayerId(null);
        setSelectedPlanningGuideId(null);
        triggerSelectionPulse("circle", targetCircle.id);
        clearMobileHandleAssist();
        clearMobilePlanningGuideHandleAssist();
        syncMobileCanvasSelection("measure", {
          noticeText: "Circle dipilih. Drag pusat atau tepi untuk adjust.",
        });
        if (tool === "pan" || tool === "circle") {
          setHistoryPaused(true);
          if (
            genericCircleHandle.handleKey === "center" ||
            genericCircleHandle.handleKey === "move"
          ) {
            interactionRef.current = {
              mode: "move-circle-center",
              circleId: genericCircleHandle.circleId,
              startImageX: boundedPoint.x,
              startImageY: boundedPoint.y,
              originCenterX: targetCircle.cx,
              originCenterY: targetCircle.cy,
            };
          } else if (genericCircleHandle.handleKey === "diameter") {
            interactionRef.current = {
              mode: "move-circle-diameter",
              circleId: genericCircleHandle.circleId,
            };
          } else {
            interactionRef.current = {
              mode: "move-circle-radius",
              circleId: genericCircleHandle.circleId,
            };
          }
        }
        return;
      }

      const genericCircleId = findClosestCircleId(imagePoint);
      if (genericCircleId !== null) {
        setMobilePanelMode("workspace");
        setActiveRightPanel("measure");
        setSelectedCircleId(genericCircleId);
        setSelectedLineId(null);
        setSelectedFreeLinePointIndex(null);
        setSelectedAngleId(null);
        setSelectedHkaId(null);
        setSelectedCutLayerId(null);
        setSelectedPlanningGuideId(null);
        triggerSelectionPulse("circle", genericCircleId);
        clearMobileHandleAssist();
        clearMobilePlanningGuideHandleAssist();
        syncMobileCanvasSelection("measure", {
          noticeText:
            "Circle aktif. Drag area dalam untuk move atau tepi untuk resize.",
        });
        return;
      }

      const genericHkaHandle = findClosestHkaHandle(boundedPoint);
      if (genericHkaHandle) {
        setMobilePanelMode("workspace");
        setActiveRightPanel("measure");
        setSelectedHkaId(genericHkaHandle.hkaId);
        setSelectedLineId(null);
        setSelectedFreeLinePointIndex(null);
        setSelectedAngleId(null);
        setSelectedCircleId(null);
        setSelectedCutLayerId(null);
        setSelectedPlanningGuideId(null);
        triggerSelectionPulse("hka", genericHkaHandle.hkaId);
        clearMobileHandleAssist();
        clearMobilePlanningGuideHandleAssist();
        if (isTouchLikePointer) {
          activateMobileHkaHandleAssist(
            genericHkaHandle.hkaId,
            genericHkaHandle.handleKey,
          );
          syncMobileCanvasSelection("measure", {
            noticeText:
              "Titik HKA dipilih. Bundaran assist aktif untuk adjust landmark lebih mudah.",
          });
          return;
        }
        syncMobileCanvasSelection("measure");
        if (tool === "pan" || tool === "hkaAuto") {
          setHistoryPaused(true);
          interactionRef.current = {
            mode: "move-hka-handle",
            hkaId: genericHkaHandle.hkaId,
            handleKey: genericHkaHandle.handleKey,
          };
        }
        return;
      }

      const genericHkaId = findClosestHkaId(imagePoint);
      if (genericHkaId !== null) {
        setMobilePanelMode("workspace");
        setActiveRightPanel("measure");
        setSelectedHkaId(genericHkaId);
        setSelectedLineId(null);
        setSelectedFreeLinePointIndex(null);
        setSelectedAngleId(null);
        setSelectedCircleId(null);
        setSelectedCutLayerId(null);
        setSelectedPlanningGuideId(null);
        triggerSelectionPulse("hka", genericHkaId);
        clearMobileHandleAssist();
        clearMobileHkaHandleAssist();
        clearMobilePlanningGuideHandleAssist();
        syncMobileCanvasSelection("measure", {
          noticeText: "HKA aktif. Tap titik landmark untuk mengubah posisi.",
        });
        return;
      }

      const allowGenericLayerTransformHandle =
        !(isSimpleUiMode && isMobileViewport && isTouchLikePointer) ||
        mobileToolMode !== "move";
      const genericCutLayerHandle = allowGenericLayerTransformHandle
        ? findCutLayerHandle(imagePoint)
        : null;
      if (genericCutLayerHandle) {
        const targetLayer = cutLayers.find(
          (layer) => layer.id === genericCutLayerHandle.layerId,
        );
        if (!targetLayer) return;
        const isRotateHandle = genericCutLayerHandle.handleKey === "rotate";
        if (shouldBlockTransformHandle({ isTouchLikePointer, isRotateHandle })) {
          setNotice(getTransformHandleGuardNotice());
          return;
        }
        focusLayerCanvas(targetLayer.id, { openPanel: false });
        triggerSelectionPulse("layer", targetLayer.id);
        setSelectedFreeLinePointIndex(null);
        setSelectedLineId(null);
        setSelectedAngleId(null);
        setSelectedCircleId(null);
        setSelectedHkaId(null);
        setSelectedPlanningGuideId(null);
        clearMobileHandleAssist();
        clearMobilePlanningGuideHandleAssist();
        syncMobileCanvasSelection("tool", {
          noticeText:
            "Layer dipilih. Drag handle untuk resize atau rotate langsung di canvas.",
        });
        if (targetLayer.lockScale && !isRotateHandle) {
          setNotice("Scale layer terkunci. Buka Lock Scale dulu untuk resize.");
          return;
        }
        if (tool === "pan") {
          setHistoryPaused(true);
          if (isRotateHandle) {
            interactionRef.current = {
              mode: "rotate-cut-layer",
              layerId: targetLayer.id,
              centerX: targetLayer.centerX,
              centerY: targetLayer.centerY,
              startPointerAngle: Math.atan2(
                imagePoint.y - targetLayer.centerY,
                imagePoint.x - targetLayer.centerX,
              ),
              startRotation: Number(targetLayer.rotation || 0),
            };
          } else {
            interactionRef.current = {
              mode: "resize-cut-layer",
              layerId: targetLayer.id,
              centerX: targetLayer.centerX,
              centerY: targetLayer.centerY,
              rotation: targetLayer.rotation,
              handleKey: genericCutLayerHandle.handleKey,
              startFlipX: Boolean(targetLayer.flipX),
              startFlipY: Boolean(targetLayer.flipY),
              startDisplayWidth: Number(targetLayer.displayWidth || 16),
              startDisplayHeight: Number(targetLayer.displayHeight || 16),
            };
          }
        }
        return;
      }

      const genericCutLayerId = findCutLayerByPoint(imagePoint);
      if (genericCutLayerId !== null) {
        const targetLayer = cutLayers.find(
          (layer) => layer.id === genericCutLayerId,
        );
        if (!targetLayer) return;
        selectLayerFromCanvas(genericCutLayerId, {
          additive: isAdditiveLayerSelection,
          includeGroup: !isAdditiveLayerSelection,
          openPanel: false,
        });
        triggerSelectionPulse("layer", genericCutLayerId);
        setSelectedFreeLinePointIndex(null);
        setSelectedLineId(null);
        setSelectedAngleId(null);
        setSelectedCircleId(null);
        setSelectedHkaId(null);
        setSelectedPlanningGuideId(null);
        clearMobileHandleAssist();
        clearMobilePlanningGuideHandleAssist();
        syncMobileCanvasSelection("tool", {
          noticeText: "Layer aktif. Geser layer atau pilih handle untuk edit.",
        });
        if (isAdditiveLayerSelection) {
          setNotice(
            selectedCutLayerIdsSet.has(targetLayer.id)
              ? `Layer #${targetLayer.id} dilepas dari multi-select.`
              : `Layer #${targetLayer.id} ditambahkan ke multi-select.`,
          );
          return;
        }
        if (tool === "pan") {
          if (
            isSimpleUiMode &&
            isMobileViewport &&
            isTouchLikePointer &&
            mobileToolMode === "scale"
          ) {
            if (targetLayer.lockScale) {
              setNotice("Scale layer terkunci. Buka Lock Scale dulu.");
              return;
            }
            setHistoryPaused(true);
            interactionRef.current = {
              mode: "mobile-scale-cut-layer",
              layerId: targetLayer.id,
              startX: point.x,
              startY: point.y,
              startDisplayWidth: Number(targetLayer.displayWidth || 16),
              startDisplayHeight: Number(targetLayer.displayHeight || 16),
            };
            setNotice(
              "Size layer aktif. Drag kanan/atas untuk membesarkan, kiri/bawah untuk mengecilkan.",
            );
            return;
          }
          if (
            isSimpleUiMode &&
            isMobileViewport &&
            isTouchLikePointer &&
            mobileToolMode === "rotate"
          ) {
            setHistoryPaused(true);
            interactionRef.current = {
              mode: "mobile-rotate-cut-layer",
              layerId: targetLayer.id,
              startX: point.x,
              startY: point.y,
              startRotation: Number(targetLayer.rotation || 0),
            };
            setNotice("Putar layer aktif. Geser kiri/kanan untuk rotasi halus.");
            return;
          }
          const selectedMoveLayerIds = selectedCutLayerIdsSet.has(targetLayer.id)
            ? selectedCutLayerIds
            : getRelatedLayerIds(targetLayer.id, { includeGroup: true });
          const movableLayerIds = selectedMoveLayerIds.filter((layerId) =>
            cutLayers.some((item) => item.id === layerId),
          );
          if (!movableLayerIds.length) {
            setNotice("Layer terkait tidak ditemukan.");
            return;
          }
          setHistoryPaused(true);
          interactionRef.current = {
            mode: "move-cut-layer",
            layerIds: movableLayerIds,
            startImageX: imagePoint.x,
            startImageY: imagePoint.y,
            origins: movableLayerIds.map((layerId) => {
              const layer = cutLayers.find((item) => item.id === layerId);
              return {
                layerId,
                originCenterX: Number(layer?.centerX || 0),
                originCenterY: Number(layer?.centerY || 0),
              };
            }),
          };
        }
        return;
      }

      if (
        selectedLineId !== null ||
        selectedAngleId !== null ||
        selectedCircleId !== null ||
        selectedHkaId !== null ||
        selectedCutLayerId !== null ||
        selectedPlanningGuideId !== null
      ) {
        clearActiveCanvasSelection();
      }
      setHkaResultPanelOpen(false);

        if (tool === "pan") {
          if (
            isSimpleUiMode &&
            isMobileViewport &&
            isTouchLikePointer &&
            (mobileCanvasLocked || mobileCanvasMode === "edit")
          ) {
            setNotice(
              mobileCanvasLocked
                ? "Canvas terkunci. Tap object/template untuk edit tanpa menggeser canvas."
                : "Edit Object aktif. Tap object atau titik; aktifkan Pan Canvas untuk menggeser canvas.",
            );
            return;
          }
          interactionRef.current = {
            mode: "pan",
          startX: point.x,
          startY: point.y,
          startPanX: view.panX,
          startPanY: view.panY,
        };
        return;
      }

      if (
        !hasCalibration &&
        (tool === "angle" ||
          (tool === "circle" && calibrationModeRef.current !== "magnification") ||
          tool === "hkaAuto")
      ) {
        focusCalibrationStep(
          "Kalibrasi wajib sebelum memakai Angle/Circle/HKA.",
        );
        return;
      }

      if (tool === "centerFinder") {
        setSelectedLineId(null);
        setSelectedAngleId(null);
        setSelectedCircleId(null);
        setSelectedHkaId(null);
        setSelectedCutLayerId(null);
        setSelectedPlanningGuideId(null);
        setDraftCenterFinderPoints((prev) => {
          const next = [...prev, snappedPlacementPoint];
          if (next.length < 3) {
            setNotice(`Center Finder: pilih ${3 - next.length} titik lagi.`);
            return next;
          }
          const circumcircle = getCircumcircleFromThreePoints(
            next[0],
            next[1],
            next[2],
          );
          if (!circumcircle) {
            setNotice(
              "Center Finder gagal. Tiga titik terlalu segaris. Ulangi dengan titik tepi yang lebih menyebar.",
            );
            return [];
          }
          appendCenterFinderCircle({
            cx: circumcircle.center.x,
            cy: circumcircle.center.y,
            radius: circumcircle.radius,
            points: [
              { ...circumcircle.center },
              {
                x: circumcircle.center.x + circumcircle.radius,
                y: circumcircle.center.y,
              },
            ],
            source: "centerFinder",
          });
          setNotice(
            "Center Finder selesai. Center dan circle referensi berhasil dibuat.",
          );
          setTool(getIdleTool());
          if (shouldUseMobileOneShotTool) {
            setMobileControlsOpen(false);
          }
          return [];
        });
        return;
      }

      if (tool === "axisBuilder") {
        setSelectedLineId(null);
        setSelectedAngleId(null);
        setSelectedCircleId(null);
        setSelectedHkaId(null);
        setSelectedCutLayerId(null);
        setSelectedPlanningGuideId(null);
        setDraftAxisBuilderPoints((prev) => {
          const next = [...prev, snappedPlacementPoint];
          if (next.length < 4) {
            const phase =
              next.length < 2
                ? `proximal ${next.length}/2`
                : `distal ${next.length - 2}/2`;
            setNotice(
              `Axis Builder: lanjutkan titik ${phase}. Axis dibuat dari midpoint kedua segmen.`,
            );
            return next;
          }
          const nextAxisLine = buildAxisLineFromPoints(next);
          if (!nextAxisLine) {
            setNotice(
              "Axis Builder gagal. Pastikan dua segmen cukup terpisah agar midpoint membentuk axis.",
            );
            return [];
          }
          appendLineMeasurement(
            {
              ...nextAxisLine,
              type: "axis",
            },
            { mobileHandleAssistEnd: true },
          );
          setNotice(
            "Axis Builder selesai. Axis dibuat dari midpoint segmen proximal dan distal.",
          );
          setTool(getIdleTool());
          if (shouldUseMobileOneShotTool) {
            setMobileControlsOpen(false);
          }
          return [];
        });
        return;
      }

      if (tool === "guideBuilder") {
        if (!guideBuilderReference?.line) {
          setNotice(
            "Guide Builder butuh satu line atau planning guide terpilih sebagai acuan.",
          );
          return;
        }
        const nextGuideLine = buildGuideLineFromReference(
          guideBuilderReference.line,
          snappedPlacementPoint,
          guideBuilderMode,
        );
        if (!nextGuideLine) {
          setNotice("Guide Builder gagal. Acuan guide tidak valid.");
          return;
        }
        appendLineMeasurement(
          {
            ...nextGuideLine,
            type:
              guideBuilderMode === "parallel"
                ? "parallelGuide"
                : "perpendicularGuide",
          },
          { mobileHandleAssistEnd: true },
        );
        setNotice(
          `${guideBuilderMode === "parallel" ? "Parallel" : "Perpendicular"} guide dibuat dari ${guideBuilderReference.label}.`,
        );
        setTool(getIdleTool());
        if (shouldUseMobileOneShotTool) {
          setMobileControlsOpen(false);
        }
        return;
      }

      if (tool === "angle") {
        const hitAngleHandle = findClosestAngleHandle(boundedPoint);
        if (hitAngleHandle) {
          setSelectedAngleId(hitAngleHandle.angleId);
          setSelectedLineId(null);
          setSelectedFreeLinePointIndex(null);
          setSelectedCircleId(null);
          setSelectedHkaId(null);
          setSelectedCutLayerId(null);
          triggerSelectionPulse("angle", hitAngleHandle.angleId);
          if (isTouchLikePointer) {
            activateMobileAngleHandleAssist(
              hitAngleHandle.angleId,
              hitAngleHandle.handleKey,
            );
            syncMobileCanvasSelection("measure", {
              noticeText:
                "Titik angle dipilih. Bundaran assist aktif untuk adjust yang lebih presisi.",
            });
            return;
          }
          setHistoryPaused(true);
          interactionRef.current = {
            mode: "move-angle-handle",
            angleId: hitAngleHandle.angleId,
            handleKey: hitAngleHandle.handleKey,
          };
          return;
        }

        setSelectedAngleId(null);
        setSelectedLineId(null);
        setSelectedCircleId(null);
        setSelectedHkaId(null);
        setSelectedCutLayerId(null);
        setDraftAnglePoints((prev) => {
          const next = [
            ...prev,
            { x: snappedPlacementPoint.x, y: snappedPlacementPoint.y },
          ];
          if (next.length < 3) {
            setNotice(`Angle: pilih ${3 - next.length} titik lagi.`);
            return next;
          }

          const nextAngle = {
            id: nextAngleIdRef.current,
            p1: next[0],
            p2: next[1],
            p3: next[2],
            color: DEFAULT_ANGLE_COLOR,
            labelOffsetX: DEFAULT_ANGLE_LABEL_OFFSET_X,
            labelOffsetY: DEFAULT_ANGLE_LABEL_OFFSET_Y,
            resultOpacity: DEFAULT_LABEL_OPACITY,
            strokeWidth: DEFAULT_ANGLE_STROKE_WIDTH,
          };
          nextAngleIdRef.current += 1;
          setAngles((items) => [...items, nextAngle]);
          setSelectedAngleId(nextAngle.id);
          setNotice("Angle measurement dibuat.");
          setTool(getIdleTool());
          if (shouldUseMobileOneShotTool) {
            setMobileControlsOpen(false);
          }
          return [];
        });
        return;
      }

      if (tool === "circle") {
        const hitCircleHandle = findClosestCircleHandle(boundedPoint);
        if (hitCircleHandle) {
          setSelectedCircleId(hitCircleHandle.circleId);
          setSelectedLineId(null);
          setSelectedAngleId(null);
          setSelectedHkaId(null);
          setSelectedCutLayerId(null);
          setHistoryPaused(true);

          if (
            hitCircleHandle.handleKey === "center" ||
            hitCircleHandle.handleKey === "move"
          ) {
            const targetCircle = circles.find(
              (item) => item.id === hitCircleHandle.circleId,
            );
            if (!targetCircle) return;
            interactionRef.current = {
              mode: "move-circle-center",
              circleId: hitCircleHandle.circleId,
              startImageX: boundedPoint.x,
              startImageY: boundedPoint.y,
              originCenterX: targetCircle.cx,
              originCenterY: targetCircle.cy,
            };
          } else {
            interactionRef.current = {
              mode: "move-circle-radius",
              circleId: hitCircleHandle.circleId,
            };
          }
          return;
        }

        setSelectedCircleId(null);
        setSelectedLineId(null);
        setSelectedAngleId(null);
        setSelectedHkaId(null);
        setSelectedCutLayerId(null);

        if ((isSimpleUiMode || isTouchLikePointer) && draftCirclePoints.length) {
          const center = draftCirclePoints[0];
          const edge = { x: snappedPlacementPoint.x, y: snappedPlacementPoint.y };
          const radius = getDistance(center, edge);
          if (radius < 3) {
            setNotice("Circle terlalu kecil. Tap tepi yang lebih jauh dari pusat.");
            return;
          }
          const nextCircle = appendCircleMeasurement({
            cx: center.x,
            cy: center.y,
            radius,
            points: [center, edge],
            source: calibrationModeRef.current === "magnification" ? "headCalibration" : "diameter",
            calibrationHeadCircle: calibrationModeRef.current === "magnification",
            color: calibrationModeRef.current === "magnification" ? "#ec4899" : undefined,
            targetMm:
              calibrationModeRef.current === "magnification"
                ? Number(anatomicalRefSizeMm)
                : undefined,
            targetApparentMm:
              calibrationModeRef.current === "magnification"
                ? Number(anatomicalRefSizeMm)
                : undefined,
          });
          if (calibrationModeRef.current === "magnification" && nextCircle) {
            setCalibrationCircleId(nextCircle.id);
            setCalibrationLineId(null);
          }
          setDraftCirclePoints([]);
          setHistoryPaused(false);
          setNotice(
            "Circle dibuat. Edit: tap object lalu geser pusat atau tepi circle.",
          );
          setTool(getIdleTool());
          if (shouldUseMobileOneShotTool) {
            setMobileControlsOpen(false);
          }
          return;
        }

        if (isSimpleUiMode || isTouchLikePointer) {
          setHistoryPaused(true);
          setDraftCirclePoints([
            { x: snappedPlacementPoint.x, y: snappedPlacementPoint.y },
          ]);
          setNotice("Circle: pusat tersimpan. Tap tepi circle untuk menentukan diameter.");
          return;
        }

        setHistoryPaused(true);
        setDraftCirclePoints([
          { x: snappedPlacementPoint.x, y: snappedPlacementPoint.y },
          { x: snappedPlacementPoint.x, y: snappedPlacementPoint.y },
        ]);
        interactionRef.current = {
          mode: "draw-circle-radius",
          centerX: snappedPlacementPoint.x,
          centerY: snappedPlacementPoint.y,
        };
        setNotice("Circle: klik/drag dari pusat ke tepi diameter, lalu lepas.");
        return;
      }

      if (tool === "hkaAuto") {
        const hitHkaHandle = findClosestHkaHandle(boundedPoint);
        if (hitHkaHandle) {
          setSelectedHkaId(hitHkaHandle.hkaId);
          setSelectedLineId(null);
          setSelectedFreeLinePointIndex(null);
          setSelectedAngleId(null);
          setSelectedCircleId(null);
          setSelectedCutLayerId(null);
          triggerSelectionPulse("hka", hitHkaHandle.hkaId);
          if (isTouchLikePointer) {
            activateMobileHkaHandleAssist(
              hitHkaHandle.hkaId,
              hitHkaHandle.handleKey,
            );
            syncMobileCanvasSelection("measure", {
              noticeText:
                "Titik HKA dipilih. Bundaran assist aktif untuk adjust landmark lebih mudah.",
            });
            return;
          }
          setHistoryPaused(true);
          interactionRef.current = {
            mode: "move-hka-handle",
            hkaId: hitHkaHandle.hkaId,
            handleKey: hitHkaHandle.handleKey,
          };
          return;
        }

        setSelectedHkaId(null);
        setSelectedLineId(null);
        setSelectedAngleId(null);
        setSelectedCircleId(null);
        setSelectedCutLayerId(null);
        hkaCompletionFiredRef.current = false;
        setDraftHkaPoints((prev) => {
          const next = [
            ...prev,
            { x: snappedPlacementPoint.x, y: snappedPlacementPoint.y },
          ];
          const definition = getHkaModeDefinition(hkaInputMode);
          if (next.length < definition.points.length) {
            setNotice(getHkaDraftNotice(hkaInputMode, next.length));
            return next;
          }
          // Guard: prevent double-fire from React StrictMode functional updater invocations
          if (hkaCompletionFiredRef.current) return [];
          hkaCompletionFiredRef.current = true;

          // If updating an existing HKA item, overwrite its points instead of creating new
          if (pendingHkaUpdateIdRef.current !== null) {
            const updateId = pendingHkaUpdateIdRef.current;
            pendingHkaUpdateIdRef.current = null;
            const pointFields = definition.points.reduce(
              (accumulator, pointDef, index) => {
                accumulator[pointDef.key] = next[index];
                return accumulator;
              },
              {},
            );
            if (hkaInputMode === "full") {
              pointFields.direction = inferHkaDirectionFromPoints(
                pointFields.hip,
                pointFields.knee,
                pointFields.ankle,
                hkaSide,
                "varus",
              );
            }
            updateHkaById(updateId, pointFields);
            setSelectedHkaId(updateId);
            setNotice(`${definition.label} diperbarui (${getHkaSideLabel(hkaSide)}).`);
            setTool(getIdleTool());
            if (shouldUseMobileOneShotTool) {
              setMobileControlsOpen(false);
            }
            return [];
          }

          const nextHka = definition.points.reduce(
            (accumulator, pointDef, index) => {
              accumulator[pointDef.key] = next[index];
              return accumulator;
            },
            {
              id: nextHkaIdRef.current,
              mode: hkaInputMode,
              direction: "varus",
              side: hkaSide,
              lineColor: DEFAULT_HKA_LINE_COLOR,
              strokeWidth: DEFAULT_HKA_STROKE_WIDTH,
              labelOffsetX: DEFAULT_HKA_LABEL_OFFSET_X,
              labelOffsetY: DEFAULT_HKA_LABEL_OFFSET_Y,
              showArc: hkaInputMode === "full",
            },
          );
          if (hkaInputMode === "full") {
            nextHka.direction = inferHkaDirectionFromPoints(
              nextHka.hip,
              nextHka.knee,
              nextHka.ankle,
              hkaSide,
              "varus",
            );
          }
          nextHkaIdRef.current += 1;
          setHkaSets((items) => {
            if (items.some((item) => item.id === nextHka.id)) return items;
            return [...items, nextHka];
          });
          setSelectedHkaId(nextHka.id);
          setNotice(
            `${definition.label} dibuat dari landmarks${
              hkaInputMode === "full" ? ` (${getHkaSideLabel(hkaSide)})` : ""
            }.`,
          );
          setTool(getIdleTool());
          if (shouldUseMobileOneShotTool) {
            setMobileControlsOpen(false);
          }
          return [];
        });
        return;
      }

      if (tool !== "draw") return;

      setSelectedLineId(null);
      setSelectedAngleId(null);
      setSelectedCircleId(null);
      setSelectedHkaId(null);
      setSelectedCutLayerId(null);

      const start = snappedPlacementPoint;
      if (isSimpleUiMode || isTouchLikePointer) {
        if (draftLine) {
          const resolvedType = draftLine.type || linePreset;
          const nextLineInput = constrainLineByPreset({
            ...draftLine,
            x2: start.x,
            y2: start.y,
            type: resolvedType,
          }, resolvedType);
          const length = getLineLength(nextLineInput);
          if (length < 2) {
            setNotice("Line terlalu pendek. Tap titik akhir yang lebih jauh.");
            return;
          }
          appendLineMeasurement(nextLineInput, { mobileHandleAssistEnd: true });
          setDraftLine(null);
          setHistoryPaused(false);
          setTool(getIdleTool());
          if (!hasCalibration) {
            const calibrationMessage =
              'Line dibuat. Buka "Kalibrasi", pilih marker/garis referensi, isi nilai real, lalu tekan "Simpan Kalibrasi".';
            setActionToast({
              id: Date.now(),
              type: "success",
              text: calibrationMessage,
            });
            focusCalibrationStep(calibrationMessage);
          } else {
            setNotice(
              "Line dibuat. Edit: tap object lalu geser titik awal/akhir.",
            );
            if (shouldUseMobileOneShotTool) {
              setMobileControlsOpen(false);
            }
          }
          return;
        }

        setDraftLine({
          x1: start.x,
          y1: start.y,
          x2: start.x,
          y2: start.y,
          type: linePreset,
          strokeWidth: calibrationDraftStrokeWidth,
        });
        setHistoryPaused(true);
        setNotice("Line: titik awal tersimpan. Tap titik akhir.");
        return;
      }

      setDraftLine({
        x1: start.x,
        y1: start.y,
        x2: start.x,
        y2: start.y,
        type: linePreset,
        strokeWidth: calibrationDraftStrokeWidth,
      });
      setHistoryPaused(true);
      interactionRef.current = {
        mode: "draw",
        startX: point.x,
        startY: point.y,
      };
    },
    [
      activateMobileHandleAssist,
      activateMobileAngleHandleAssist,
      activateMobileHkaHandleAssist,
      activateMobilePlanningGuideHandleAssist,
      addAnnotationAtPoint,
      annotations,
      clampToImageBounds,
      clearMobileLongPress,
      clearMobileAngleHandleAssist,
      clearMobileHandleAssist,
      clearMobileHkaHandleAssist,
      clearMobilePlanningGuideHandleAssist,
      completeDraftCut,
      completeDraftFreeLine,
      circles,
      draftCut,
      draftCirclePoints,
      draftFreeLine,
      draftLine,
      angles,
      appendCenterFinderCircle,
      appendCircleMeasurement,
      appendLineMeasurement,
      captureMobilePointer,
      findClosestAngleHandle,
      findClosestAngleId,
      findAngleLabelByPoint,
      findClosestCircleHandle,
      findClosestCircleId,
      findClosestHandle,
      findClosestHkaHandle,
      findClosestHkaId,
      findCircleLabelByPoint,
      findHkaLabelByPoint,
      findClosestLineId,
      findMobileHandleAssistHit,
      findMobileAngleHandleAssistHit,
      findMobileHkaHandleAssistHit,
      findMobilePlanningGuideHandleAssistHit,
      getMobileAngleHandleAssistGeometry,
      getMobileHandleAssistGeometry,
      getMobileHkaHandleAssistGeometry,
      getMobilePlanningGuideHandleAssistGeometry,
      clearActiveCanvasSelection,
      findAnnotationByPoint,
      findAnnotationPointerByPoint,
      findLineLabelByPoint,
      findClosestPlanningGuideHandle,
      findClosestPlanningGuideId,
      findFreeLineCurveHandle,
      findFreeLinePointHandle,
      findPlanningGuideLabelByPoint,
      findCutLayerByPoint,
      findCutLayerHandle,
      fitImageToViewport,
      focusLayerCanvas,
      focusPlanningGuideCanvas,
      clearMobileGesturePointers,
      consumeMobileDoubleTap,
      getIdleTool,
      getRelatedLayerIds,
      getLocalPoint,
      getMobileGestureSnapshot,
      getTransformHandleGuardNotice,
      image,
      focusCalibrationStep,
      freeLineMode,
      guideBuilderMode,
      guideBuilderReference,
      hasCalibration,
      hkaSide,
      calibrationDraftStrokeWidth,
      isCoarsePointer,
      isMobileViewport,
      isSimpleUiMode,
      isLineLocked,
      isRepeatedMobileLineTap,
      cutLayers,
      lines,
      mobileCanvasLocked,
      mobileCanvasMode,
      mobileToolMode,
      planningGuides,
      linePreset,
      resolveSnappedImagePoint,
      selectLayerFromCanvas,
      selectAnnotationFromCanvas,
      selectPlanningGuideForEdit,
      selectedCutLayer,
      selectedCutLayerIds,
      selectedCutLayerIdsSet,
      setHistoryPaused,
      shouldBlockTransformHandle,
      screenToImagePoint,
      startMobileLongPress,
      startMobilePinchGesture,
      syncMobileCanvasSelection,
      trackMobileGesturePointer,
      shouldUseMobileOneShotTool,
      cropToolActive,
      tool,
      toLayerLocal,
      triggerSelectionPulse,
      view.panX,
      view.panY,
      view.scale,
      showCupAssessment,
      canvasCup,
      imageToScreenPoint,
      brushMode,
      brushSize,
      brushStrength,
      brushColor,
      selectedCutLayerId,
      placingAnnotationPointer,
      setPlacingAnnotationPointer,
      updateAnnotationById,
    ],
  );

  const handlePointerMove = useCallback(
    (event) => {
      if (!image) return;

      // ── Cup Assessment drag update ──────────────────────────────────────────
      if (interactionRef.current?.mode === "cupDrag" && canvasCupDragRef.current) {
        const point = getLocalPoint(event);
        const drag = canvasCupDragRef.current;
        const sc = view.scale;
        const dScrX = point.x - drag.startScrX;
        const dScrY = point.y - drag.startScrY;
        const dImgX = dScrX / sc;
        const dImgY = dScrY / sc;
        const { cx, cy, a, b, angle } = drag.startCup;
        const cosA = Math.cos(angle);
        const sinA = Math.sin(angle);

        if (drag.handle === "center") {
          setCanvasCup(prev => ({ ...prev, cx: cx + dImgX, cy: cy + dImgY }));
        } else if (drag.handle === "top" || drag.handle === "bottom") {
          const sign = drag.handle === "top" ? -1 : 1;
          const tipX = cx + sign * cosA * a + dImgX;
          const tipY = cy + sign * sinA * a + dImgY;
          const dx = tipX - cx;
          const dy = tipY - cy;
          const newA = Math.max(8, Math.sqrt(dx * dx + dy * dy));
          const newAngle = drag.handle === "top" ? Math.atan2(dy, dx) + Math.PI : Math.atan2(dy, dx);
          setCanvasCup(prev => ({
            ...prev,
            a: newA,
            b: Math.min(prev.b, newA * 0.9),
            angle: newAngle,
          }));
        } else if (drag.handle === "sideR" || drag.handle === "sideL") {
          const sign = drag.handle === "sideR" ? 1 : -1;
          const tipX = cx + sign * sinA * b + dImgX;
          const tipY = cy - sign * cosA * b + dImgY;
          const dx = tipX - cx;
          const dy = tipY - cy;
          const proj = Math.abs(dx * sinA - dy * cosA);
          setCanvasCup(prev => ({ ...prev, b: Math.max(4, Math.min(a * 0.9, proj)) }));
        }
        return;
      }

      // ── Crop drag update ────────────────────────────────────────────────────
      if (interactionRef.current?.mode === "cropSelect") {
        const point = getLocalPoint(event);
        const imagePoint = screenToImagePoint(point.x, point.y);
        interactionRef.current.endX = imagePoint.x;
        interactionRef.current.endY = imagePoint.y;
        setCropDraftPoints({
          startX: interactionRef.current.startX,
          startY: interactionRef.current.startY,
          endX: imagePoint.x,
          endY: imagePoint.y,
        });
        return;
      }

      const point = getLocalPoint(event);
      if (
        isSimpleUiMode &&
        isMobileViewport &&
        Number.isFinite(event.pointerId) &&
        mobileGesturePointersRef.current.has(event.pointerId)
      ) {
        captureMobilePointer(event);
        trackMobileGesturePointer(event.pointerId, point);
        if (interactionRef.current.mode !== "mobile-long-press-pending") {
          cancelMobileLongPressIfMoved(event.pointerId, point);
        }
      }

      if (interactionRef.current.mode === "gesture") {
        event.preventDefault();
        const gestureSnapshot = getMobileGestureSnapshot();
        const gestureStart = mobileGestureRef.current;
        if (!gestureSnapshot || !gestureStart) return;
        const nextScale = clamp(
          gestureStart.startScale *
            (gestureSnapshot.distance / gestureStart.startDistance),
          MIN_SCALE,
          MAX_SCALE,
        );
        scheduleViewportUpdate((prev) =>
          clampViewport(
            {
              ...normalizeViewportState(prev),
              scale: nextScale,
              x: gestureSnapshot.centerX - gestureStart.anchorX * nextScale,
              y: gestureSnapshot.centerY - gestureStart.anchorY * nextScale,
            },
            { relaxed: true },
          ),
        );
        return;
      }

      if (interactionRef.current.mode === "layer-gesture") {
        event.preventDefault();
        clearSnapPreview();
        const gestureSnapshot = getMobileGestureSnapshot();
        const {
          layerIds = [],
          origins = [],
          startCenterImageX,
          startCenterImageY,
          startDistance,
          startAngle,
        } = interactionRef.current;
        if (!gestureSnapshot || !layerIds.length) return;
        const currentCenterImage = screenToImagePoint(
          gestureSnapshot.centerX,
          gestureSnapshot.centerY,
        );
        const dx = currentCenterImage.x - startCenterImageX;
        const dy = currentCenterImage.y - startCenterImageY;
        const scaleFactor =
          Number.isFinite(startDistance) && startDistance > 0
            ? clamp(gestureSnapshot.distance / startDistance, 0.08, 8)
            : 1;
        const rotationDeltaDeg =
          Number.isFinite(startAngle) && Number.isFinite(gestureSnapshot.angle)
            ? ((gestureSnapshot.angle - startAngle) * 180) / Math.PI
            : 0;

        scheduleCutLayersUpdate((prev) =>
          prev.map((layer) => {
            if (!layerIds.includes(layer.id)) return layer;
            const origin = origins.find((item) => item.layerId === layer.id);
            if (!origin) return layer;
            const canScale = !origin.lockScale && !layer.lockScale;
            const nextCenterX = Number(origin.originCenterX || layer.centerX || 0) + dx;
            const nextCenterY = Number(origin.originCenterY || layer.centerY || 0) + dy;
            const nextDisplayWidth = canScale
              ? clamp(
                  Number(origin.originDisplayWidth || layer.displayWidth || 16) *
                    scaleFactor,
                  16,
                  Math.max(16, modelWidth * 3),
                )
              : layer.displayWidth;
            const nextDisplayHeight = canScale
              ? clamp(
                  Number(origin.originDisplayHeight || layer.displayHeight || 16) *
                    scaleFactor,
                  16,
                  Math.max(16, modelHeight * 3),
                )
              : layer.displayHeight;
            const nextRotation =
              Math.round(
                normalizeRotationDegrees(
                  Number(origin.originRotation || 0) + rotationDeltaDeg,
                ) * 10,
              ) / 10;
            if (
              Object.is(layer.centerX, nextCenterX) &&
              Object.is(layer.centerY, nextCenterY) &&
              Object.is(layer.displayWidth, nextDisplayWidth) &&
              Object.is(layer.displayHeight, nextDisplayHeight) &&
              Object.is(layer.rotation, nextRotation)
            ) {
              return layer;
            }
            return {
              ...layer,
              centerX: nextCenterX,
              centerY: nextCenterY,
              displayWidth: nextDisplayWidth,
              displayHeight: nextDisplayHeight,
              rotation: nextRotation,
            };
          }),
        );
        return;
      }

      if (interactionRef.current.mode === "mobile-long-press-pending") {
        event.preventDefault();
        return;
      }

      if (!interactionRef.current.mode) {
        const moveImagePoint = clampToImageBounds(
          screenToImagePoint(point.x, point.y),
        );
        let shouldKeepSnapPreview = false;
        const now = Date.now();
        if (!isCoarsePointer && now - hoverScanLastRef.current >= 50) {
          hoverScanLastRef.current = now;
          const hoveredHkaLabelId = findHkaLabelByPoint(point);
          const hoveredHkaId =
            hoveredHkaLabelId ?? findClosestHkaId(moveImagePoint);
          const hoveredAngleLabelId = findAngleLabelByPoint(point);
          const hoveredAngleId =
            hoveredAngleLabelId ?? findClosestAngleId(moveImagePoint);
          const hoveredCircleLabelId = findCircleLabelByPoint(point);
          const hoveredCircleId =
            hoveredCircleLabelId ?? findClosestCircleId(moveImagePoint);
          const hoveredLineLabelId = findLineLabelByPoint(point);
          setLineLabelHoverInfo((cur) => {
            if (!hoveredLineLabelId) return cur ? null : cur;
            if (cur?.lineId === hoveredLineLabelId && cur.screenX === Math.round(point.x) && cur.screenY === Math.round(point.y)) return cur;
            return { lineId: hoveredLineLabelId, screenX: point.x, screenY: point.y };
          });
          setHoveredMeasurementInfo((current) => {
            if (hoveredHkaId !== null) {
              if (current?.type === "hka" && current.id === hoveredHkaId) {
                return current;
              }
              return { type: "hka", id: hoveredHkaId };
            }
            if (hoveredAngleId !== null) {
              if (
                current?.type === "angle" &&
                current.id === hoveredAngleId
              ) {
                return current;
              }
              return { type: "angle", id: hoveredAngleId };
            }
            if (hoveredCircleId !== null) {
              if (
                current?.type === "circle" &&
                current.id === hoveredCircleId
              ) {
                return current;
              }
              return { type: "circle", id: hoveredCircleId };
            }
            if (
              hoveredHkaId === null &&
              hoveredAngleId === null &&
              hoveredCircleId === null
            ) {
              return current ? null : current;
            }
            return current;
          });
        } else if (isCoarsePointer && hoveredMeasurementInfo) {
          setHoveredMeasurementInfo(null);
          setLineLabelHoverInfo(null);
        }

        if (tool === "cut" && draftCut?.points?.length) {
          shouldKeepSnapPreview = true;
          const { point: movePoint } = resolveSnapWithPreview(moveImagePoint);
          setDraftCut((prev) =>
            prev
              ? {
                  ...prev,
                  hoverPoint: movePoint,
                }
              : prev,
          );
        }
        if (
          tool === "freeLine" &&
          freeLineMode === "point" &&
          draftFreeLine?.points?.length
        ) {
          shouldKeepSnapPreview = true;
          const { point: movePoint } = resolveSnapWithPreview(moveImagePoint);
          setDraftFreeLine((prev) =>
            prev
              ? {
                  ...prev,
                  hoverPoint: movePoint,
                }
              : prev,
          );
        } else if (tool === "draw" && draftLine) {
          shouldKeepSnapPreview = true;
          const { point: movePoint } = resolveSnapWithPreview(moveImagePoint);
          setDraftLine((prev) => {
            if (!prev) return prev;
            const updated = { ...prev, x2: movePoint.x, y2: movePoint.y };
            return constrainLineByPreset(updated, prev.type || linePreset);
          });
        } else if (tool === "circle" && draftCirclePoints.length > 0) {
          shouldKeepSnapPreview = true;
          const { point: movePoint } = resolveSnapWithPreview(moveImagePoint);
          setDraftCirclePoints((prev) =>
            prev.length > 0 ? [prev[0], movePoint] : prev,
          );
        } else if (
          tool === "draw" ||
          tool === "centerFinder" ||
          tool === "axisBuilder" ||
          tool === "angle" ||
          tool === "circle" ||
          tool === "hkaAuto" ||
          (tool === "freeLine" && freeLineMode === "point")
        ) {
          shouldKeepSnapPreview = true;
          resolveSnapWithPreview(moveImagePoint);
        } else if (tool === "guideBuilder" && guideBuilderReference?.line) {
          shouldKeepSnapPreview = true;
          const { point: movePoint } = resolveSnapWithPreview(moveImagePoint);
          setGuideBuilderPreviewPoint(movePoint);
        }

        if (!shouldKeepSnapPreview) {
          clearSnapPreview();
          if (guideBuilderPreviewPoint) {
            setGuideBuilderPreviewPoint(null);
          }
        }
        return;
      }

      const activeInteractionMode = interactionRef.current.mode;
      if (
        activeInteractionMode &&
        isMobilePrecisionInteractionMode(activeInteractionMode)
      ) {
        const precisionImagePoint = clampToImageBounds(
          screenToImagePoint(point.x, point.y),
        );
        const precisionLabel = getMobileInteractionLabel(activeInteractionMode);
        if (
          shouldAutoZoomMobilePrecisionInteractionMode(activeInteractionMode)
        ) {
          beginMobilePrecisionEdit(point, precisionImagePoint, precisionLabel);
        }
        updateMobilePrecisionOverlay(point, precisionImagePoint, precisionLabel);
      }

      event.preventDefault();

      if (activeInteractionMode === "pan") {
        const dx = point.x - interactionRef.current.startX;
        const dy = point.y - interactionRef.current.startY;
        scheduleViewportUpdate((prev) =>
          clampViewport(
            {
              ...normalizeViewportState(prev),
              x: interactionRef.current.startPanX + dx,
              y: interactionRef.current.startPanY + dy,
            },
            { relaxed: true },
          ),
        );
        return;
      }

      if (interactionRef.current.mode === "brush-stroke") {
        const { layerId, layer: strokeLayer } = interactionRef.current;
        const workCanvas = brushWorkCanvasRef.current;
        if (workCanvas && layerId && strokeLayer) {
          const imgPt = screenToImagePoint(point.x, point.y);
          const canvasPt = imagePointToLayerCanvasPoint(imgPt, strokeLayer);
          const radiusInImage = brushSize / view.scale;
          const canvasRadius = radiusInImage * (strokeLayer.sourceWidth / Math.max(1, getLayerDisplaySize(strokeLayer).width));
          applyBrushToCanvas(workCanvas, canvasPt, canvasRadius, brushMode, brushStrength, brushColor);
          scheduleCutLayersUpdate((prev) => {
            if (interactionRef.current.mode !== "brush-stroke" || interactionRef.current.layerId !== layerId) {
              return prev;
            }
            return prev.map((l) => {
              if (l.id !== layerId) return l;
              const copyCanvas = document.createElement("canvas");
              copyCanvas.width = workCanvas.width;
              copyCanvas.height = workCanvas.height;
              copyCanvas.getContext("2d").drawImage(workCanvas, 0, 0);
              return { ...l, image: copyCanvas, sourceX: 0, sourceY: 0 };
            });
          });
        }
        return;
      }

      if (interactionRef.current.mode === "draw") {
        const rawMovePoint = clampToImageBounds(
          screenToImagePoint(point.x, point.y),
        );
        const { point: movePoint } = resolveSnapWithPreview(rawMovePoint);
        setDraftLine((prev) => {
          if (!prev) return prev;
          return { ...prev, x2: movePoint.x, y2: movePoint.y };
        });
        return;
      }

      if (interactionRef.current.mode === "draw-free-line") {
        clearSnapPreview();
        const movePoint = clampToImageBounds(
          screenToImagePoint(point.x, point.y),
        );
        setDraftFreeLine((prev) => {
          if (!prev?.points?.length) return prev;
          const lastPoint = prev.points[prev.points.length - 1];
          if (getDistance(lastPoint, movePoint) < 2.5) {
            return prev;
          }
          return {
            ...prev,
            points: [...prev.points, movePoint],
          };
        });
        return;
      }

      if (interactionRef.current.mode === "move-annotation-pointer") {
        const movePoint = clampToImageBounds(screenToImagePoint(point.x, point.y));
        const { annotationId, startImageX, startImageY, originPx, originPy } = interactionRef.current;
        const dx = movePoint.x - startImageX;
        const dy = movePoint.y - startImageY;
        scheduleAnnotationsUpdate((prev) =>
          prev.map((ann) =>
            ann.id === annotationId
              ? { ...ann, px: clamp(originPx + dx, 0, modelWidth), py: clamp(originPy + dy, 0, modelHeight) }
              : ann,
          ),
        );
        return;
      }

      if (interactionRef.current.mode === "move-annotation") {
        clearSnapPreview();
        const movePoint = clampToImageBounds(
          screenToImagePoint(point.x, point.y),
        );
        const {
          annotationId,
          startImageX,
          startImageY,
          originX,
          originY,
        } = interactionRef.current;
        const dx = movePoint.x - startImageX;
        const dy = movePoint.y - startImageY;
        scheduleAnnotationsUpdate((prev) =>
          prev.map((annotation) =>
            annotation.id === annotationId
              ? {
                  ...annotation,
                  x: clamp(originX + dx, 0, modelWidth),
                  y: clamp(originY + dy, 0, modelHeight),
                }
              : annotation,
          ),
        );
        return;
      }

      if (interactionRef.current.mode === "move-free-line-point") {
        const movePoint = clampToImageBounds(
          screenToImagePoint(point.x, point.y),
        );
        const { layerId, pointIndex } = interactionRef.current;
        scheduleCutLayersUpdate((prev) =>
          prev.map((layer) => {
            if (layer.id !== layerId || !isEditableMaskLayer(layer)) {
              return layer;
            }
            const nextMaskPoint = toLayerMaskPoint(movePoint, layer, {
              clampToBounds: false,
            });
            const nextMaskPoints = Array.isArray(layer.maskPoints)
              ? layer.maskPoints.map((pointItem, index) => {
                  if (index !== pointIndex) return pointItem;
                  const deltaX = nextMaskPoint.x - (Number(pointItem.x) || 0);
                  const deltaY = nextMaskPoint.y - (Number(pointItem.y) || 0);
                  const nextPointItem = {
                    ...pointItem,
                    x: nextMaskPoint.x,
                    y: nextMaskPoint.y,
                  };
                  if (
                    Number.isFinite(pointItem.handleInX) &&
                    Number.isFinite(pointItem.handleInY)
                  ) {
                    nextPointItem.handleInX = pointItem.handleInX + deltaX;
                    nextPointItem.handleInY = pointItem.handleInY + deltaY;
                  }
                  if (
                    Number.isFinite(pointItem.handleOutX) &&
                    Number.isFinite(pointItem.handleOutY)
                  ) {
                    nextPointItem.handleOutX = pointItem.handleOutX + deltaX;
                    nextPointItem.handleOutY = pointItem.handleOutY + deltaY;
                  }
                  return nextPointItem;
                })
              : [];
            const nextLayer = {
              ...layer,
              maskPoints: nextMaskPoints,
            };
            return layer.kind === "free-line"
              ? normalizeFreeLineLayerBounds(nextLayer)
              : nextLayer;
          }),
        );
        return;
      }

      if (interactionRef.current.mode === "move-free-line-curve-handle") {
        const movePoint = clampToImageBounds(
          screenToImagePoint(point.x, point.y),
        );
        const { layerId, pointIndex, handleKey } = interactionRef.current;
        scheduleCutLayersUpdate((prev) =>
          prev.map((layer) => {
            if (layer.id !== layerId || !isEditableMaskLayer(layer)) {
              return layer;
            }
            const nextMaskPoints = Array.isArray(layer.maskPoints)
              ? layer.maskPoints.map((pointItem, index) => {
                  if (index !== pointIndex) return pointItem;
                  const anchorX = Number(pointItem.x) || 0;
                  const anchorY = Number(pointItem.y) || 0;
                  const nextHandlePoint = toLayerMaskPoint(movePoint, layer, {
                    clampToBounds: false,
                  });
                  const vectorX = nextHandlePoint.x - anchorX;
                  const vectorY = nextHandlePoint.y - anchorY;
                  const nextPointItem = { ...pointItem };
                  if (handleKey === "in") {
                    nextPointItem.handleInX = nextHandlePoint.x;
                    nextPointItem.handleInY = nextHandlePoint.y;
                    nextPointItem.handleOutX = anchorX - vectorX;
                    nextPointItem.handleOutY = anchorY - vectorY;
                  } else {
                    nextPointItem.handleOutX = nextHandlePoint.x;
                    nextPointItem.handleOutY = nextHandlePoint.y;
                    nextPointItem.handleInX = anchorX - vectorX;
                    nextPointItem.handleInY = anchorY - vectorY;
                  }
                  return nextPointItem;
                })
              : [];
            const nextLayer = {
              ...layer,
              maskPoints: nextMaskPoints,
            };
            return layer.kind === "free-line"
              ? normalizeFreeLineLayerBounds(nextLayer)
              : nextLayer;
          }),
        );
        return;
      }

      if (interactionRef.current.mode === "draw-circle-radius") {
        const rawMovePoint = clampToImageBounds(
          screenToImagePoint(point.x, point.y),
        );
        const { point: movePoint } = resolveSnapWithPreview(rawMovePoint);
        const { centerX, centerY } = interactionRef.current;
        setDraftCirclePoints([
          { x: centerX, y: centerY },
          { x: movePoint.x, y: movePoint.y },
        ]);
        return;
      }

      if (interactionRef.current.mode === "move-cut-layer") {
        clearSnapPreview();
        const { layerIds = [], origins = [], startImageX, startImageY } =
          interactionRef.current;
        if (!layerIds.length) return;
        const nextImagePoint = screenToImagePoint(point.x, point.y);
        const dx = nextImagePoint.x - startImageX;
        const dy = nextImagePoint.y - startImageY;

        scheduleCutLayersUpdate((prev) =>
          prev.map((layer) => {
            if (!layerIds.includes(layer.id)) return layer;
            const origin = origins.find((item) => item.layerId === layer.id);
            const nextCenterX =
              Number(origin?.originCenterX || layer.centerX || 0) + dx;
            const nextCenterY =
              Number(origin?.originCenterY || layer.centerY || 0) + dy;
            if (
              Object.is(layer.centerX, nextCenterX) &&
              Object.is(layer.centerY, nextCenterY)
            ) {
              return layer;
            }
            return {
              ...layer,
              centerX: nextCenterX,
              centerY: nextCenterY,
            };
          }),
        );
        return;
      }

      if (interactionRef.current.mode === "mobile-scale-cut-layer") {
        clearSnapPreview();
        const {
          layerId,
          startX,
          startY,
          startDisplayWidth = 16,
          startDisplayHeight = 16,
        } = interactionRef.current;
        const deltaX = point.x - startX;
        const deltaY = point.y - startY;
        const scaleDelta = (deltaX - deltaY) / 180;
        const scaleFactor = clamp(1 + scaleDelta, 0.08, 8);
        const nextDisplayWidth = clamp(
          startDisplayWidth * scaleFactor,
          16,
          Math.max(16, modelWidth * 2),
        );
        const nextDisplayHeight = clamp(
          startDisplayHeight * scaleFactor,
          16,
          Math.max(16, modelHeight * 2),
        );

        scheduleCutLayersUpdate((prev) =>
          prev.map((layer) =>
            layer.id === layerId
              ? layer.lockScale
                ? layer
                : {
                    ...layer,
                    displayWidth: nextDisplayWidth,
                    displayHeight: nextDisplayHeight,
                  }
              : layer,
          ),
        );
        return;
      }

      if (interactionRef.current.mode === "move-planning-guide-handle") {
        const movePoint = screenToImagePoint(point.x, point.y);
        const {
          guideId,
          handleKey,
          pointerOffsetX = 0,
          pointerOffsetY = 0,
        } = interactionRef.current;
        const rawAdjustedPoint = clampToImageBounds({
          x: movePoint.x + pointerOffsetX,
          y: movePoint.y + pointerOffsetY,
        });
        const { point: adjustedPoint } = resolveSnapWithPreview(
          rawAdjustedPoint,
          {
            excludeRefs: [`guide:${guideId}`],
          },
        );
        schedulePlanningGuidesUpdate((prev) =>
          prev.map((guide) => {
            if (guide.id !== guideId) return guide;
            if (handleKey === "start") {
              return {
                ...guide,
                anchorStart: { x: adjustedPoint.x, y: adjustedPoint.y },
              };
            }
            return {
              ...guide,
              anchorEnd: { x: adjustedPoint.x, y: adjustedPoint.y },
            };
          }),
        );
        return;
      }

      if (interactionRef.current.mode === "move-planning-guide") {
        clearSnapPreview();
        const { guideId, startImageX, startImageY, origin } =
          interactionRef.current;
        const nextImagePoint = screenToImagePoint(point.x, point.y);
        let dx = nextImagePoint.x - startImageX;
        let dy = nextImagePoint.y - startImageY;

        const minX = Math.min(origin.startX, origin.endX);
        const maxX = Math.max(origin.startX, origin.endX);
        const minY = Math.min(origin.startY, origin.endY);
        const maxY = Math.max(origin.startY, origin.endY);

        dx = clamp(dx, -minX, modelWidth - maxX);
        dy = clamp(dy, -minY, modelHeight - maxY);

        schedulePlanningGuidesUpdate((prev) =>
          prev.map((guide) =>
            guide.id === guideId
              ? {
                  ...guide,
                  anchorStart: { x: origin.startX + dx, y: origin.startY + dy },
                  anchorEnd: { x: origin.endX + dx, y: origin.endY + dy },
                }
              : guide,
          ),
        );
        return;
      }

      if (interactionRef.current.mode === "move-planning-guide-label") {
        clearSnapPreview();
        const { guideId, startX, startY, originOffsetX, originOffsetY } =
          interactionRef.current;
        const dx = point.x - startX;
        const dy = point.y - startY;
        schedulePlanningGuidesUpdate((prev) =>
          prev.map((guide) =>
            guide.id === guideId
              ? {
                  ...guide,
                  labelOffsetX: clamp(originOffsetX + dx, -320, 320),
                  labelOffsetY: clamp(originOffsetY + dy, -220, 220),
                }
              : guide,
          ),
        );
        return;
      }

      if (interactionRef.current.mode === "resize-cut-layer") {
        clearSnapPreview();
        const {
          layerId,
          centerX,
          centerY,
          rotation: layerRotation,
          handleKey,
          startFlipX = false,
          startFlipY = false,
          startDisplayWidth = 16,
          startDisplayHeight = 16,
        } = interactionRef.current;
        const nextImagePoint = screenToImagePoint(point.x, point.y);
        const dx = nextImagePoint.x - centerX;
        const dy = nextImagePoint.y - centerY;
        const rad = (layerRotation * Math.PI) / 180;
        const cos = Math.cos(rad);
        const sin = Math.sin(rad);
        const localX = dx * cos + dy * sin;
        const localY = -dx * sin + dy * cos;
        const halfStartW = startDisplayWidth / 2;
        const halfStartH = startDisplayHeight / 2;
        let nextDisplayWidth = startDisplayWidth;
        let nextDisplayHeight = startDisplayHeight;
        let nextCenterX = centerX;
        let nextCenterY = centerY;
        let nextFlipX = startFlipX;
        let nextFlipY = startFlipY;

        if (
          handleKey === "tl" ||
          handleKey === "tr" ||
          handleKey === "br" ||
          handleKey === "bl"
        ) {
          const signX = handleKey === "tr" || handleKey === "br" ? 1 : -1;
          const signY = handleKey === "br" || handleKey === "bl" ? 1 : -1;
          const fixedLocalX = -signX * halfStartW;
          const fixedLocalY = -signY * halfStartH;
          const crossedX = signX * (localX - fixedLocalX) < 0;
          const crossedY = signY * (localY - fixedLocalY) < 0;
          const candidateWidth = Math.max(16, Math.abs(localX - fixedLocalX));
          const candidateHeight = Math.max(16, Math.abs(localY - fixedLocalY));
          const scale = Math.max(
            candidateWidth / Math.max(1, startDisplayWidth),
            candidateHeight / Math.max(1, startDisplayHeight),
          );

          nextDisplayWidth = clamp(
            scale * startDisplayWidth,
            16,
            modelWidth * 2,
          );
          nextDisplayHeight = clamp(
            scale * startDisplayHeight,
            16,
            modelHeight * 2,
          );

          const effectiveSignX = crossedX ? -signX : signX;
          const effectiveSignY = crossedY ? -signY : signY;
          const draggedLocalX = fixedLocalX + effectiveSignX * nextDisplayWidth;
          const draggedLocalY =
            fixedLocalY + effectiveSignY * nextDisplayHeight;
          const midpointLocal = {
            x: (fixedLocalX + draggedLocalX) / 2,
            y: (fixedLocalY + draggedLocalY) / 2,
          };
          const centerOffset = rotateVector(
            midpointLocal.x,
            midpointLocal.y,
            layerRotation,
          );
          nextCenterX = centerX + centerOffset.x;
          nextCenterY = centerY + centerOffset.y;
          nextFlipX = crossedX ? !startFlipX : startFlipX;
          nextFlipY = crossedY ? !startFlipY : startFlipY;
        } else if (handleKey === "ml" || handleKey === "mr") {
          const signX = handleKey === "mr" ? 1 : -1;
          const fixedLocalX = -signX * halfStartW;
          const crossedX = signX * (localX - fixedLocalX) < 0;
          nextDisplayWidth = clamp(
            Math.max(16, Math.abs(localX - fixedLocalX)),
            16,
            modelWidth * 2,
          );
          const effectiveSignX = crossedX ? -signX : signX;
          const draggedLocalX = fixedLocalX + effectiveSignX * nextDisplayWidth;
          const midpointLocalX = (fixedLocalX + draggedLocalX) / 2;
          const centerOffset = rotateVector(midpointLocalX, 0, layerRotation);
          nextCenterX = centerX + centerOffset.x;
          nextCenterY = centerY + centerOffset.y;
          nextFlipX = crossedX ? !startFlipX : startFlipX;
        } else if (handleKey === "tm" || handleKey === "bm") {
          const signY = handleKey === "bm" ? 1 : -1;
          const fixedLocalY = -signY * halfStartH;
          const crossedY = signY * (localY - fixedLocalY) < 0;
          nextDisplayHeight = clamp(
            Math.max(16, Math.abs(localY - fixedLocalY)),
            16,
            modelHeight * 2,
          );
          const effectiveSignY = crossedY ? -signY : signY;
          const draggedLocalY =
            fixedLocalY + effectiveSignY * nextDisplayHeight;
          const midpointLocalY = (fixedLocalY + draggedLocalY) / 2;
          const centerOffset = rotateVector(0, midpointLocalY, layerRotation);
          nextCenterX = centerX + centerOffset.x;
          nextCenterY = centerY + centerOffset.y;
          nextFlipY = crossedY ? !startFlipY : startFlipY;
        }

        scheduleCutLayersUpdate((prev) =>
          prev.map((layer) =>
            layer.id === layerId
              ? layer.lockScale
                ? layer
                : {
                    ...layer,
                    centerX: nextCenterX,
                    centerY: nextCenterY,
                    displayWidth: nextDisplayWidth,
                    displayHeight: nextDisplayHeight,
                    flipX: nextFlipX,
                    flipY: nextFlipY,
                  }
              : layer,
          ),
        );
        return;
      }

      if (interactionRef.current.mode === "mobile-rotate-cut-layer") {
        clearSnapPreview();
        const {
          layerId,
          startX,
          startY,
          startRotation,
        } = interactionRef.current;
        const dx = point.x - startX;
        const dy = point.y - startY;
        const deltaDeg = dx * 0.45 + dy * 0.12;
        const nextRotation =
          Math.round(
            normalizeRotationDegrees(Number(startRotation || 0) + deltaDeg) *
              10,
          ) / 10;
        if (
          Number.isFinite(interactionRef.current.lastRotation) &&
          Math.abs(
            getSignedAngleDeltaDegrees(
              interactionRef.current.lastRotation,
              nextRotation,
            ),
          ) < 0.15
        ) {
          return;
        }
        interactionRef.current.lastRotation = nextRotation;
        scheduleCutLayersUpdate((prev) =>
          prev.map((layer) =>
            layer.id === layerId
              ? {
                  ...layer,
                  rotation: nextRotation,
                }
              : layer,
          ),
        );
        return;
      }

      if (interactionRef.current.mode === "rotate-cut-layer") {
        clearSnapPreview();
        const {
          layerId,
          centerX,
          centerY,
          startPointerAngle,
          startRotation,
        } =
          interactionRef.current;
        if (!Number.isFinite(centerX) || !Number.isFinite(centerY)) return;
        const nextImagePoint = screenToImagePoint(point.x, point.y);
        const nextPointerAngle = Math.atan2(
          nextImagePoint.y - centerY,
          nextImagePoint.x - centerX,
        );
        const deltaDeg = getSignedAngleDeltaDegrees(
          startPointerAngle,
          nextPointerAngle,
        );
        const nextRotation = Math.round(
          normalizeRotationDegrees(startRotation + deltaDeg) * 10,
        ) / 10;
        if (
          Number.isFinite(interactionRef.current.lastRotation) &&
          Math.abs(
            getSignedAngleDeltaDegrees(
              interactionRef.current.lastRotation,
              nextRotation,
            ),
          ) < 0.15
        ) {
          return;
        }
        interactionRef.current.lastRotation = nextRotation;
        scheduleCutLayersUpdate((prev) =>
          prev.map((layer) =>
            layer.id === layerId
              ? {
                  ...layer,
                  rotation: nextRotation,
                }
              : layer,
          ),
        );
        return;
      }

      if (interactionRef.current.mode === "move-handle") {
        const movePoint = screenToImagePoint(point.x, point.y);
        const {
          lineId,
          handleKey,
          pointerOffsetX = 0,
          pointerOffsetY = 0,
        } = interactionRef.current;
        if (isLineLocked(lineId)) return;
        const rawAdjustedPoint = clampToImageBounds({
          x: movePoint.x + pointerOffsetX,
          y: movePoint.y + pointerOffsetY,
        });
        const { point: adjustedPoint } = resolveSnapWithPreview(
          rawAdjustedPoint,
          {
            excludeRefs: [`line:${lineId}`],
          },
        );

        scheduleLinesUpdate((prev) =>
          prev.map((line) => {
            if (line.id !== lineId) return line;
            if (handleKey === "start") {
              return { ...line, x1: adjustedPoint.x, y1: adjustedPoint.y };
            }
            return { ...line, x2: adjustedPoint.x, y2: adjustedPoint.y };
          }),
        );
        return;
      }

      if (interactionRef.current.mode === "move-line") {
        clearSnapPreview();
        const { lineId, startImageX, startImageY, origin } =
          interactionRef.current;
        if (isLineLocked(lineId)) return;
        const nextImagePoint = screenToImagePoint(point.x, point.y);
        let dx = nextImagePoint.x - startImageX;
        let dy = nextImagePoint.y - startImageY;

        const minX = Math.min(origin.x1, origin.x2);
        const maxX = Math.max(origin.x1, origin.x2);
        const minY = Math.min(origin.y1, origin.y2);
        const maxY = Math.max(origin.y1, origin.y2);

        dx = clamp(dx, -minX, modelWidth - maxX);
        dy = clamp(dy, -minY, modelHeight - maxY);

        scheduleLinesUpdate((prev) =>
          prev.map((line) =>
            line.id === lineId
              ? {
                  ...line,
                  x1: origin.x1 + dx,
                  y1: origin.y1 + dy,
                  x2: origin.x2 + dx,
                  y2: origin.y2 + dy,
                }
              : line,
          ),
        );
        return;
      }

      if (interactionRef.current.mode === "move-line-label") {
        clearSnapPreview();
        const { lineId, startX, startY, originOffsetX, originOffsetY } =
          interactionRef.current;
        if (isLineLocked(lineId)) return;
        const dx = point.x - startX;
        const dy = point.y - startY;
        scheduleLinesUpdate((prev) =>
          prev.map((line) =>
            line.id === lineId
              ? {
                  ...line,
                  labelOffsetX: clamp(originOffsetX + dx, -320, 320),
                  labelOffsetY: clamp(originOffsetY + dy, -220, 220),
                }
              : line,
          ),
        );
        return;
      }

      if (interactionRef.current.mode === "move-angle-handle") {
        const movePoint = screenToImagePoint(point.x, point.y);
        const {
          angleId,
          handleKey,
          pointerOffsetX = 0,
          pointerOffsetY = 0,
        } = interactionRef.current;
        const rawAdjustedPoint = clampToImageBounds({
          x: movePoint.x + pointerOffsetX,
          y: movePoint.y + pointerOffsetY,
        });
        const { point: adjustedPoint } = resolveSnapWithPreview(
          rawAdjustedPoint,
          {
            excludeRefs: [`angle:${angleId}`],
          },
        );
        scheduleAnglesUpdate((prev) =>
          prev.map((item) => {
            if (item.id !== angleId) return item;
            if (handleKey === "p1")
              return { ...item, p1: { x: adjustedPoint.x, y: adjustedPoint.y } };
            if (handleKey === "p2")
              return { ...item, p2: { x: adjustedPoint.x, y: adjustedPoint.y } };
            return { ...item, p3: { x: adjustedPoint.x, y: adjustedPoint.y } };
          }),
        );
        return;
      }

      if (interactionRef.current.mode === "move-angle-label") {
        clearSnapPreview();
        const { angleId, startX, startY, originOffsetX, originOffsetY } =
          interactionRef.current;
        const dx = point.x - startX;
        const dy = point.y - startY;
        scheduleAnglesUpdate((prev) =>
          prev.map((item) =>
            item.id === angleId
              ? {
                  ...item,
                  labelOffsetX: clamp(originOffsetX + dx, -320, 320),
                  labelOffsetY: clamp(originOffsetY + dy, -220, 220),
                }
              : item,
          ),
        );
        return;
      }

      if (interactionRef.current.mode === "move-hka-label") {
        clearSnapPreview();
        const { hkaId, startX, startY, originOffsetX, originOffsetY } =
          interactionRef.current;
        const dx = point.x - startX;
        const dy = point.y - startY;
        if (!interactionRef.current.hasMoved && (Math.abs(dx) > 4 || Math.abs(dy) > 4)) {
          interactionRef.current.hasMoved = true;
          setHkaResultPanelOpen(false);
        }
        scheduleHkaUpdate((prev) =>
          prev.map((item) =>
            item.id === hkaId
              ? {
                  ...item,
                  labelOffsetX: clamp(originOffsetX + dx, -320, 320),
                  labelOffsetY: clamp(originOffsetY + dy, -220, 220),
                }
              : item,
          ),
        );
        return;
      }

      if (interactionRef.current.mode === "move-circle-center") {
        clearSnapPreview();
        const {
          circleId,
          startImageX,
          startImageY,
          originCenterX,
          originCenterY,
        } = interactionRef.current;
        const nextImagePoint = screenToImagePoint(point.x, point.y);
        const dx = nextImagePoint.x - startImageX;
        const dy = nextImagePoint.y - startImageY;
        const nextCenterPoint = clampToImageBounds({
          x: originCenterX + dx,
          y: originCenterY + dy,
        });
        scheduleCirclesUpdate((prev) =>
          prev.map((item) =>
            item.id === circleId
              ? { ...item, cx: nextCenterPoint.x, cy: nextCenterPoint.y }
              : item,
          ),
        );
        return;
      }

      if (interactionRef.current.mode === "move-circle-radius") {
        const { circleId } = interactionRef.current;
        const rawNextImagePoint = screenToImagePoint(point.x, point.y);
        const { point: nextImagePoint } = resolveSnapWithPreview(
          clampToImageBounds(rawNextImagePoint),
          {
            excludeRefs: [`circle:${circleId}`],
          },
        );
        scheduleCirclesUpdate((prev) =>
          prev.map((item) => {
            if (item.id !== circleId) return item;
            const nextRadius = clamp(
              Math.hypot(
                nextImagePoint.x - item.cx,
                nextImagePoint.y - item.cy,
              ),
              3,
              Math.max(modelWidth, modelHeight) * 1.5,
            );
            return { ...item, radius: nextRadius };
          }),
        );
        return;
      }

      if (interactionRef.current.mode === "move-circle-diameter") {
        const { circleId } = interactionRef.current;
        const nextImagePoint = screenToImagePoint(point.x, point.y);
        scheduleCirclesUpdate((prev) =>
          prev.map((item) => {
            if (item.id !== circleId) return item;
            const dx = nextImagePoint.x - item.cx;
            const dy = nextImagePoint.y - item.cy;
            const newAngleDeg = (Math.atan2(dy, dx) * 180) / Math.PI;
            return { ...item, diameterAngle: newAngleDeg };
          }),
        );
        return;
      }

      if (interactionRef.current.mode === "move-circle-label") {
        clearSnapPreview();
        const { circleId, startX, startY, originOffsetX, originOffsetY } =
          interactionRef.current;
        const dx = point.x - startX;
        const dy = point.y - startY;
        scheduleCirclesUpdate((prev) =>
          prev.map((item) =>
            item.id === circleId
              ? {
                  ...item,
                  labelOffsetX: clamp(originOffsetX + dx, -320, 320),
                  labelOffsetY: clamp(originOffsetY + dy, -220, 220),
                }
              : item,
          ),
        );
        return;
      }

      if (interactionRef.current.mode === "move-hka-handle") {
        const movePoint = screenToImagePoint(point.x, point.y);
        const {
          hkaId,
          handleKey,
          pointerOffsetX = 0,
          pointerOffsetY = 0,
        } = interactionRef.current;
        const rawAdjustedPoint = clampToImageBounds({
          x: movePoint.x + pointerOffsetX,
          y: movePoint.y + pointerOffsetY,
        });
        const { point: adjustedPoint } = resolveSnapWithPreview(
          rawAdjustedPoint,
          {
            excludeRefs: [`hka:${hkaId}`],
          },
        );
        scheduleHkaUpdate((prev) =>
          prev.map((item) => {
            if (item.id !== hkaId) return item;
            const nextItem = {
              ...item,
              [handleKey]: { x: adjustedPoint.x, y: adjustedPoint.y },
            };
            if (nextItem.mode === "full") {
              nextItem.direction = inferHkaDirectionFromPoints(
                nextItem.hip,
                nextItem.knee,
                nextItem.ankle,
                nextItem.side,
                nextItem.direction || "varus",
              );
            }
            return nextItem;
          }),
        );
        return;
      }
    },
    [
      angles,
      cancelMobileLongPressIfMoved,
      captureMobilePointer,
      clampViewport,
      clampToImageBounds,
      circles,
      clearMobileLongPress,
      clearSnapPreview,
      beginMobilePrecisionEdit,
      draftCirclePoints,
      draftCut,
      draftFreeLine,
      draftLine,
      findClosestAngleId,
      findClosestCircleId,
      findClosestHkaId,
      findAngleLabelByPoint,
      findCircleLabelByPoint,
      findHkaLabelByPoint,
      freeLineMode,
      guideBuilderPreviewPoint,
      guideBuilderReference,
      getLocalPoint,
      getMobileGestureSnapshot,
      hoveredMeasurementInfo,
      image,
      isMobileViewport,
      isSimpleUiMode,
      isLineLocked,
      setHoveredMeasurementInfo,
      modelHeight,
      modelWidth,
      resolveSnapWithPreview,
      scheduleAnnotationsUpdate,
      scheduleAnglesUpdate,
      scheduleCirclesUpdate,
      scheduleCutLayersUpdate,
      scheduleHkaUpdate,
      scheduleLinesUpdate,
      schedulePlanningGuidesUpdate,
      scheduleViewportUpdate,
      screenToImagePoint,
      cropToolActive,
      tool,
      trackMobileGesturePointer,
      updateMobilePrecisionOverlay,
      view.scale,
      brushMode,
      brushSize,
      brushStrength,
      brushColor,
    ],
  );

  const handlePointerUp = useCallback((event) => {
    removeMobileGesturePointer(event?.pointerId);
    clearMobileLongPress();
    const completedInteractionMode = interactionRef.current.mode;

    // ── Cup Assessment drag end ──────────────────────────────────────────────
    if (completedInteractionMode === "cupDrag") {
      canvasCupDragRef.current = null;
      interactionRef.current = { mode: null, startX: 0, startY: 0 };
      return;
    }

    // ── Apply crop selection ─────────────────────────────────────────────────
    if (completedInteractionMode === "cropSelect") {
      const { startX, startY, endX, endY } = interactionRef.current;
      interactionRef.current = { mode: null };
      setCropDraftPoints(null);
      setCropToolActive(false);

      const mx1 = Math.min(startX, endX);
      const my1 = Math.min(startY, endY);
      const mx2 = Math.max(startX, endX);
      const my2 = Math.max(startY, endY);
      const w = mx2 - mx1;
      const h = my2 - my1;

      if (w > 5 && h > 5) {
        const baseX = cropRect?.x || 0;
        const baseY = cropRect?.y || 0;
        const newX = Math.max(0, Math.round(baseX + mx1));
        const newY = Math.max(0, Math.round(baseY + my1));
        const newW = Math.min(Math.round(w), imageWidth - newX);
        const newH = Math.min(Math.round(h), imageHeight - newY);
        setCropRect({ x: newX, y: newY, width: newW, height: newH });
        setTimeout(() => fitImageToViewport(), 0);
        setNotice("Crop diterapkan. Klik 'Reset Crop' untuk kembali ke gambar penuh.");
      }
      return;
    }

    // ── Brush stroke end ────────────────────────────────────────────────────
    if (completedInteractionMode === "brush-stroke") {
      const { layerId } = interactionRef.current;
      const workCanvas = brushWorkCanvasRef.current;
      interactionRef.current = { mode: null };
      brushWorkCanvasRef.current = null;
      brushWorkLayerIdRef.current = null;
      setHistoryPaused(false);
      if (workCanvas && layerId) {
        const dataUrl = workCanvas.toDataURL("image/png");
        setCutLayers((prev) => prev.map((l) => {
          if (l.id !== layerId) return l;
          const finalCanvas = document.createElement("canvas");
          finalCanvas.width = workCanvas.width;
          finalCanvas.height = workCanvas.height;
          finalCanvas.getContext("2d").drawImage(workCanvas, 0, 0);
          return { ...l, image: finalCanvas, imageSrc: dataUrl, sourceX: 0, sourceY: 0 };
        }));
        const targetLayer = cutLayers.find((l) => l.id === layerId);
        if (targetLayer?.kind === "free-cut") {
          saveCutLayersToIDB(cutLayers.map((l) => l.id === layerId ? { ...l, imageSrc: dataUrl } : l));
        }
      }
      return;
    }

    if (interactionRef.current.mode === "draw" && draftLine) {
      const constrainedDraft = constrainLineByPreset(draftLine, draftLine.type || linePreset);
      const length = getLineLength(constrainedDraft);
      if (length >= 2) {
        const nextLine = {
          ...constrainedDraft,
          id: nextLineIdRef.current,
          labelOffsetX: DEFAULT_LINE_LABEL_OFFSET_X,
          labelOffsetY: DEFAULT_LINE_LABEL_OFFSET_Y,
          labelOpacity: DEFAULT_LABEL_OPACITY,
          strokeWidth: Number.isFinite(constrainedDraft.strokeWidth)
            ? constrainedDraft.strokeWidth
            : calibrationDraftStrokeWidth,
        };
        nextLineIdRef.current += 1;
        setLines((prev) => [...prev, nextLine]);
        setSelectedLineId(nextLine.id);
        if (isCoarsePointer) {
          setMobileHandleAssist({ lineId: nextLine.id, handleKey: "end" });
        }
        if (!hasCalibration) {
          const calibrationMessage =
            calibrationModeRef.current === "magnification"
              ? 'Circle siap. Tekan "Terapkan Kalibrasi" di panel Head Ref untuk menerapkan.'
              : 'Garis dibuat. Buka menu "Kalibrasi", pakai tab "Garis Real", isi nilai referensi, lalu tekan "Simpan Kalibrasi".';
          setActionToast({
            id: Date.now(),
            type: "success",
            text: calibrationMessage,
          });
          focusCalibrationStep(calibrationMessage);
        } else {
          setNotice(
            shouldUseMobileOneShotTool
              ? "Line dibuat. Bundaran assist aktif di ujung garis, sentuh area itu untuk adjust panjang."
              : "Line dibuat. Drag ujung atau garis untuk adjust.",
          );
        }
      }
      setDraftLine(null);
      setTool(getIdleTool());
      if (shouldUseMobileOneShotTool) {
        if (hasCalibration) {
          setMobileControlsOpen(false);
        }
      }
    }

    if (interactionRef.current.mode === "draw-free-line" && draftFreeLine) {
      const points = Array.isArray(draftFreeLine.points)
        ? draftFreeLine.points
        : [];
      if (points.length >= MIN_FREE_CUT_POINTS) {
        completeDraftFreeLine();
      } else {
        setDraftFreeLine(null);
        setHistoryPaused(false);
        setNotice("Free Line butuh area minimal 3 titik.");
      }
      setTool(getIdleTool());
      if (shouldUseMobileOneShotTool) {
        setMobileControlsOpen(false);
      }
    }

    if (
      interactionRef.current.mode === "draw-circle-radius" &&
      draftCirclePoints.length >= 2
    ) {
      const center = draftCirclePoints[0];
      const edge = draftCirclePoints[1];
      const radius = getDistance(center, edge);
      if (radius >= 3) {
        const nextCircle = appendCircleMeasurement({
          cx: center.x,
          cy: center.y,
          radius,
          points: [center, edge],
          strokeWidth: DEFAULT_CIRCLE_STROKE_WIDTH,
          source: calibrationModeRef.current === "magnification" ? "headCalibration" : "diameter",
          calibrationHeadCircle: calibrationModeRef.current === "magnification",
          color: calibrationModeRef.current === "magnification" ? "#ec4899" : undefined,
          targetMm:
            calibrationModeRef.current === "magnification"
              ? Number(anatomicalRefSizeMm)
              : undefined,
          targetApparentMm:
            calibrationModeRef.current === "magnification"
              ? Number(anatomicalRefSizeMm)
              : undefined,
        });
        if (calibrationModeRef.current === "magnification" && nextCircle) {
          setCalibrationCircleId(nextCircle.id);
          setCalibrationLineId(null);
        }
        setNotice(
          "Circle/diameter berhasil dibuat. Drag area dalam untuk pindah, drag tepi untuk resize.",
        );
      } else {
        setNotice("Diameter terlalu kecil. Ulangi circle.");
      }
      setDraftCirclePoints([]);
      setTool(getIdleTool());
      if (shouldUseMobileOneShotTool) {
        setMobileControlsOpen(false);
      }
    }

    if (completedInteractionMode === "pan") {
      setView((prev) =>
        clampViewToViewport(prev, {
          relaxed: isSimpleUiMode && isMobileViewport,
        }),
      );
    }
    if (completedInteractionMode === "gesture") {
      clearMobileGesturePointers();
      clearMobilePinchGesture();
      setView((prev) => clampViewToViewport(prev, { relaxed: true }));
    }

    if (completedInteractionMode === "move-hka-label" && !interactionRef.current.hasMoved && isSimpleUiMode) {
      setHkaResultPanelOpen(true);
    }
    if (
      calibrationMode === "magnification" &&
      hasCalibration &&
      ["move-circle-center", "move-circle-radius", "move-circle-diameter"].includes(
        completedInteractionMode,
      ) &&
      interactionRef.current.circleId === calibrationCircleId
    ) {
      if (isSimpleUiMode) {
        setSimpleCalibrationModalOpen(true);
      } else {
        setActionToast({
          id: Date.now(),
          type: "success",
          text: "Circle head diubah. Klik Terapkan Kalibrasi untuk menyimpan ulang skala.",
        });
      }
    }
    interactionRef.current = { mode: null, startX: 0, startY: 0 };
    interactionStartedAtRef.current = 0;
    interactionCanvasRectRef.current = null;
    releaseActivePointerCapture();
    resetMobileLineTapTarget();
    setHistoryPaused(false);
    setGuideBuilderPreviewPoint(null);
    clearSnapPreview();
    restoreMobilePrecisionView();
  }, [
    appendCircleMeasurement,
    applyMagnificationCircleCalibration,
    anatomicalRefSizeMm,
    calibrationCircleId,
    calibrationMode,
    clampViewToViewport,
    clearMobileGesturePointers,
    clearMobilePinchGesture,
    clearMobileLongPress,
    clearSnapPreview,
    completeDraftFreeLine,
    calibrationDraftStrokeWidth,
    cropRect,
    cropToolActive,
    draftCirclePoints,
    draftFreeLine,
    draftLine,
    fitImageToViewport,
    focusCalibrationStep,
    getIdleTool,
    hasCalibration,
    imageHeight,
    imageWidth,
    isMobileViewport,
    isSimpleUiMode,
    isCoarsePointer,
    releaseActivePointerCapture,
    removeMobileGesturePointer,
    resetMobileLineTapTarget,
    restoreMobilePrecisionView,
    setGuideBuilderPreviewPoint,
    shouldUseMobileOneShotTool,
    cutLayers,
  ]);

  const handleTouchFallbackEnd = useCallback(
    (event) => {
      const activePointerId = activePointerIdRef.current;
      const canvas = overlayCanvasRef.current;
      const hasActivePointer =
        activePointerId !== null &&
        (mobileGesturePointersRef.current.has(activePointerId) ||
          canvas?.hasPointerCapture?.(activePointerId));

      if (isSimpleUiMode && isMobileViewport && hasActivePointer) {
        return;
      }

      handlePointerUp(event);
    },
    [handlePointerUp, isMobileViewport, isSimpleUiMode],
  );

  const handlePointerLeave = useCallback(() => {
    setHoveredMeasurementInfo(null);
    setLineLabelHoverInfo(null);
    if (interactionRef.current.mode && activePointerIdRef.current !== null) {
      return;
    }
    handlePointerUp();
  }, [handlePointerUp]);

  const handleCanvasPointerMove = useCallback((e) => {
    if (tool === "brush") {
      const rect = e.currentTarget.getBoundingClientRect();
      const x = String(e.clientX - rect.left);
      const y = String(e.clientY - rect.top);
      if (brushCursorOuterRef.current) {
        brushCursorOuterRef.current.setAttribute("cx", x);
        brushCursorOuterRef.current.setAttribute("cy", y);
        brushCursorOuterRef.current.style.display = "";
      }
      if (brushCursorDotRef.current) {
        brushCursorDotRef.current.setAttribute("cx", x);
        brushCursorDotRef.current.setAttribute("cy", y);
        brushCursorDotRef.current.style.display = "";
      }
    }
    handlePointerMove(e);
  }, [tool, handlePointerMove]);

  const handleCanvasPointerLeave = useCallback((e) => {
    if (brushCursorOuterRef.current) brushCursorOuterRef.current.style.display = "none";
    if (brushCursorDotRef.current) brushCursorDotRef.current.style.display = "none";
    handlePointerLeave(e);
  }, [handlePointerLeave]);

  useEffect(() => {
    const finishPointerInteraction = (event) => {
      if (!interactionRef.current.mode) return;
      if (
        activePointerIdRef.current !== null &&
        Number.isFinite(event?.pointerId) &&
        event.pointerId !== activePointerIdRef.current
      ) {
        return;
      }
      handlePointerUp();
    };
    const finishPointerCancel = (event) => {
      if (
        isSimpleUiMode &&
        isMobileViewport &&
        activePointerIdRef.current !== null &&
        Number.isFinite(event?.pointerId) &&
        event.pointerId === activePointerIdRef.current &&
        mobileGesturePointersRef.current.has(event.pointerId)
      ) {
        return;
      }
      finishPointerInteraction(event);
    };
    const finishAnyInteraction = () => {
      const activePointerId = activePointerIdRef.current;
      const canvas = overlayCanvasRef.current;
      if (
        isSimpleUiMode &&
        isMobileViewport &&
        activePointerId !== null &&
        (mobileGesturePointersRef.current.has(activePointerId) ||
          canvas?.hasPointerCapture?.(activePointerId))
      ) {
        return;
      }
      if (interactionRef.current.mode) {
        handlePointerUp();
      }
    };
    const handleVisibilityChange = () => {
      if (document.visibilityState === "hidden") {
        finishAnyInteraction();
      }
    };

    window.addEventListener("pointerup", finishPointerInteraction, true);
    window.addEventListener("pointercancel", finishPointerCancel, true);
    window.addEventListener("touchend", finishAnyInteraction, true);
    window.addEventListener("touchcancel", finishAnyInteraction, true);
    window.addEventListener("blur", finishAnyInteraction);
    document.addEventListener("visibilitychange", handleVisibilityChange);
    return () => {
      window.removeEventListener("pointerup", finishPointerInteraction, true);
      window.removeEventListener(
        "pointercancel",
        finishPointerCancel,
        true,
      );
      window.removeEventListener("touchend", finishAnyInteraction, true);
      window.removeEventListener("touchcancel", finishAnyInteraction, true);
      window.removeEventListener("blur", finishAnyInteraction);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [handlePointerUp, isMobileViewport, isSimpleUiMode]);

  useEffect(() => {
    if (!isSimpleUiMode || !isMobileViewport) return undefined;

    const intervalId = window.setInterval(() => {
      const currentMode = interactionRef.current.mode;
      if (!currentMode) return;
      const activePointerId = activePointerIdRef.current;
      const canvas = overlayCanvasRef.current;
      const hasCapture =
        activePointerId !== null && canvas?.hasPointerCapture?.(activePointerId);
      const hasTrackedPointer =
        activePointerId !== null &&
        mobileGesturePointersRef.current.has(activePointerId);

      if (!hasCapture && !hasTrackedPointer) {
        resetCanvasInteractionState(
          "Canvas otomatis di-unlock karena pointer interaction terlihat macet.",
        );
      }
    }, 1200);

    return () => window.clearInterval(intervalId);
  }, [isMobileViewport, isSimpleUiMode, resetCanvasInteractionState]);

  const handleWheel = useCallback(
    (event) => {
      if (!image) return;

      event.preventDefault();
      const point = getLocalPoint(event);
      const zoomFactor = Math.exp(-event.deltaY * 0.0015);
      zoomAtPoint(zoomFactor, point, { relaxed: true });
    },
    [getLocalPoint, image, zoomAtPoint],
  );

  useEffect(() => {
    const canvas = overlayCanvasRef.current;
    if (!canvas) return;
    canvas.addEventListener("wheel", handleWheel, { passive: false });
    return () => {
      canvas.removeEventListener("wheel", handleWheel);
    };
  }, [handleWheel]);

  const applyCalibration = useCallback(() => {
    const referenceLine =
      selectedLine ||
      lines.find((line) => line.type === "ruler") ||
      lines.find((line) => line.id === calibrationLineId) ||
      null;
    const zoomPercent = Number(sourceZoomPercent);
    if (!Number.isFinite(zoomPercent) || zoomPercent <= 0) {
      setNotice("Zoom source harus angka > 0.");
      return false;
    }

    if (calibrationMode === "zoom") {
      const baseFactorAt100 = Number(mmPerPixelAt100Input);
      if (!Number.isFinite(baseFactorAt100) || baseFactorAt100 <= 0) {
        setNotice("Isi nilai mm/px pada zoom 100% dengan angka valid.");
        return false;
      }
      const factorFromZoom = baseFactorAt100 * (100 / zoomPercent);
      setMmPerPixel(factorFromZoom);
      setCalibrationLineId(null);
      setNotice(
        `Kalibrasi zoom aktif (${zoomPercent.toFixed(2)}%). Faktor: ${factorFromZoom.toFixed(6)} mm/px. QC: verifikasi lagi dengan ruler jika tersedia.`,
      );
      return true;
    }

    if (calibrationMode === "magnification") {
      const referenceMagCircle =
        selectedCircle ||
        circles.find((circle) => circle.id === calibrationCircleId) ||
        circles.find((circle) => circle.calibrationHeadCircle) ||
        null;
      if (referenceMagCircle) {
        return applyMagnificationCircleCalibration(referenceMagCircle);
      }

      const referenceMagLine =
        selectedLine ||
        lines.find((line) => line.id === calibrationLineId) ||
        null;
      if (!referenceMagLine) {
        setNotice("Buat circle head, sesuaikan dengan foto, lalu simpan.");
        return false;
      }
      const magFactor = Number(magnificationFactorInput);
      const realSizeMm = Number(anatomicalRefSizeMm);
      if (!Number.isFinite(magFactor) || magFactor <= 0) {
        setNotice("Isi faktor magnifikasi (%) dengan angka valid.");
        return false;
      }
      if (!Number.isFinite(realSizeMm) || realSizeMm <= 0) {
        setNotice("Isi estimasi ukuran anatomi (mm) dengan angka valid.");
        return false;
      }
      const lenPx = getLineLength(referenceMagLine);
      if (!Number.isFinite(lenPx) || lenPx <= 0) {
        setNotice("Garis referensi tidak valid.");
        return false;
      }
      const apparentSizeMm = realSizeMm * (magFactor / 100);
      const factor = apparentSizeMm / lenPx;
      const normalizedAt100Mag = factor * (Number(sourceZoomPercent) / 100);
      setMmPerPixel(factor);
      setCalibrationLineId(referenceMagLine.id);
      setCalibrationCircleId(null);
      if (Number.isFinite(normalizedAt100Mag) && normalizedAt100Mag > 0) {
        setMmPerPixelAt100Input(normalizedAt100Mag.toFixed(6));
      }
      setNotice(
        `Kalibrasi magnifikasi ${magFactor}% aktif. Real: ${realSizeMm}mm → Tampak: ${apparentSizeMm.toFixed(1)}mm. Faktor: ${factor.toFixed(6)} mm/px.`,
      );
      return true;
    }

    if (!referenceLine) {
      setNotice("Pilih satu garis dulu untuk dijadikan referensi kalibrasi.");
      return false;
    }

    const actualMm = Number(actualMmInput);
    if (!Number.isFinite(actualMm) || actualMm <= 0) {
      setNotice("Nilai referensi harus angka positif.");
      return false;
    }

    const lengthPx = getLineLength(referenceLine);
    if (lengthPx <= 0) {
      setNotice("Garis referensi tidak valid.");
      return false;
    }

    const actualMmValue = actualUnit === "cm" ? actualMm * 10 : actualMm;
    const factor = actualMmValue / lengthPx;
    const normalizedAt100 = factor * (zoomPercent / 100);
    const endpointTolerancePx = 2;
    const estimatedErrorPct = (endpointTolerancePx / lengthPx) * 100;
    const qcText =
      estimatedErrorPct > 3.5
        ? "QC rendah"
        : estimatedErrorPct > 1.8
          ? "QC sedang"
          : "QC baik";

    setMmPerPixel(factor);
    setCalibrationLineId(referenceLine.id);
    if (Number.isFinite(normalizedAt100) && normalizedAt100 > 0) {
      setMmPerPixelAt100Input(normalizedAt100.toFixed(6));
    }
    setNotice(
      `Kalibrasi garis berhasil (zoom source ${zoomPercent.toFixed(2)}%). ${qcText}: estimasi error ±${estimatedErrorPct.toFixed(2)}%.`,
    );
    return true;
  }, [
    actualMmInput,
    actualUnit,
    applyMagnificationCircleCalibration,
    calibrationCircleId,
    calibrationMode,
    calibrationLineId,
    circles,
    lines,
    mmPerPixelAt100Input,
    magnificationFactorInput,
    anatomicalRefSizeMm,
    selectedCircle,
    selectedLine,
    sourceZoomPercent,
  ]);

  const deleteSelectedFreeLinePoint = useCallback(() => {
    if (
      !selectedCutLayer ||
      selectedCutLayer.kind !== "free-line" ||
      selectedFreeLinePointIndex === null
    ) {
      return false;
    }

    const pointCount = Array.isArray(selectedCutLayer.maskPoints)
      ? selectedCutLayer.maskPoints.length
      : 0;
    if (pointCount <= MIN_FREE_CUT_POINTS) {
      setNotice("Free Line minimal harus memiliki 3 titik.");
      return true;
    }

    const deletedIndex = selectedFreeLinePointIndex;
    setCutLayers((prev) =>
      prev.map((layer) => {
        if (layer.id !== selectedCutLayer.id || layer.kind !== "free-line") {
          return layer;
        }
        return {
          ...layer,
          maskPoints: layer.maskPoints.filter(
            (_, index) => index !== deletedIndex,
          ),
        };
      }),
    );
    setSelectedFreeLinePointIndex(
      Math.max(0, Math.min(deletedIndex, pointCount - 2)),
    );
    setNotice(`Titik #${deletedIndex + 1} pada Free Line dihapus.`);
    return true;
  }, [selectedCutLayer, selectedFreeLinePointIndex]);

  const insertFreeLinePointAfterSelection = useCallback(() => {
    if (
      !selectedCutLayer ||
      selectedCutLayer.kind !== "free-line" ||
      selectedFreeLinePointIndex === null ||
      !Array.isArray(selectedCutLayer.maskPoints) ||
      selectedCutLayer.maskPoints.length < 2
    ) {
      setNotice("Pilih satu titik Free Line dulu untuk menambah point.");
      return;
    }

    const pointCount = selectedCutLayer.maskPoints.length;
    const insertAfterIndex = selectedFreeLinePointIndex;
    const nextIndex = (insertAfterIndex + 1) % pointCount;
    const currentPoint = selectedCutLayer.maskPoints[insertAfterIndex];
    const nextPoint = selectedCutLayer.maskPoints[nextIndex];
    const insertedPoint = {
      x: ((Number(currentPoint?.x) || 0) + (Number(nextPoint?.x) || 0)) / 2,
      y: ((Number(currentPoint?.y) || 0) + (Number(nextPoint?.y) || 0)) / 2,
    };
    const insertedIndex = insertAfterIndex + 1;

    setCutLayers((prev) =>
      prev.map((layer) => {
        if (layer.id !== selectedCutLayer.id || layer.kind !== "free-line") {
          return layer;
        }
        return {
          ...layer,
          maskPoints: [
            ...layer.maskPoints.slice(0, insertedIndex),
            insertedPoint,
            ...layer.maskPoints.slice(insertedIndex),
          ],
        };
      }),
    );
    setSelectedFreeLinePointIndex(insertedIndex);
    setNotice(
      `Point baru ditambahkan setelah titik #${selectedFreeLinePointIndex + 1}.`,
    );
  }, [selectedCutLayer, selectedFreeLinePointIndex]);

  const adjustSelectedFreeLinePointRound = useCallback(
    (delta) => {
      if (
        !selectedCutLayer ||
        selectedCutLayer.kind !== "free-line" ||
        selectedFreeLinePointIndex === null
      ) {
        setNotice("Pilih satu titik Free Line dulu untuk atur rounded.");
        return;
      }

      updateLayerById(selectedCutLayer.id, (item) => {
        if (item.kind !== "free-line") return item;
        const currentRadius = getFreeLineCurveRadius(
          item,
          selectedFreeLinePointIndex,
        );
        return applyFreeLineCurveRadiusToPoint(
          item,
          selectedFreeLinePointIndex,
          currentRadius + delta,
        );
      });
      setNotice("Rounded point diperbarui.");
    },
    [selectedCutLayer, selectedFreeLinePointIndex, updateLayerById],
  );

  const removeSelectedLine = useCallback(() => {
    if (deleteSelectedFreeLinePoint()) {
      return;
    }

    if (selectedLine) {
      if (isLineLocked(selectedLine.id)) {
        setNotice("Garis terkunci. Unlock dulu sebelum dihapus.");
        return;
      }

      setLines((prev) => prev.filter((line) => line.id !== selectedLine.id));
      setLockedLineIds((prev) => {
        if (!prev.has(selectedLine.id)) return prev;
        const next = new Set(prev);
        next.delete(selectedLine.id);
        return next;
      });

      if (selectedLine.id === calibrationLineId) {
        setCalibrationLineId(null);
        setMmPerPixel(null);
        setNotice("Garis kalibrasi dihapus. Silakan kalibrasi ulang.");
      } else {
        setNotice("Garis terpilih dihapus.");
      }

      setSelectedLineId(null);
      return;
    }

    if (selectedAngle) {
      setAngles((prev) => prev.filter((item) => item.id !== selectedAngle.id));
      setSelectedAngleId(null);
      setNotice("Angle terpilih dihapus.");
      return;
    }

    if (selectedCircle) {
      setCircles((prev) =>
        prev.filter((item) => item.id !== selectedCircle.id),
      );
      setSelectedCircleId(null);
      if (selectedCircle.id === calibrationCircleId) {
        setCalibrationCircleId(null);
        setMmPerPixel(null);
        setNotice("Circle kalibrasi dihapus. Silakan kalibrasi ulang.");
      } else {
        setNotice("Circle terpilih dihapus.");
      }
      return;
    }

    if (selectedHka) {
      setHkaSets((prev) => prev.filter((item) => item.id !== selectedHka.id));
      setSelectedHkaId(null);
      setNotice("HKA terpilih dihapus.");
      return;
    }

    if (selectedAnnotation) {
      removeSelectedAnnotation();
      return;
    }

    if (selectedCutLayer) {
      setCutLayers((prev) =>
        prev.filter((item) => item.id !== selectedCutLayer.id),
      );
      setSelectedCutLayerId(null);
      setNotice("Layer terpilih dihapus.");
      return;
    }

    setNotice("Tidak ada measurement yang dipilih.");
  }, [
    calibrationLineId,
    calibrationCircleId,
    deleteSelectedFreeLinePoint,
    isLineLocked,
    removeSelectedAnnotation,
    selectedAngle,
    selectedAnnotation,
    selectedCircle,
    selectedCutLayer,
    selectedHka,
    selectedLine,
  ]);
  const shouldEmphasizeCalibration =
    highlightCalibrationPanel ||
    (!hasCalibration && calibrationMode === "line" && Boolean(selectedLine));
  const shouldShowCanvasCalibrationPrompt =
    !hasCalibration && calibrationMode === "line" && lines.length > 0;
  const canvasCalibrationPromptText = selectedLine
    ? `Line #${selectedLine.id} belum dikalibrasi. Buka Kalibrasi lalu simpan faktor real.`
    : "Measurement butuh kalibrasi. Pilih satu line referensi lalu simpan kalibrasi.";

  const toggleSelectedLineLock = useCallback(() => {
    if (!selectedLine) {
      setNotice("Pilih garis dulu untuk lock/unlock.");
      return;
    }

    const targetId = selectedLine.id;
    const willUnlock = lockedLineIds.has(targetId);
    setLockedLineIds((prev) => {
      const next = new Set(prev);
      if (next.has(targetId)) {
        next.delete(targetId);
      } else {
        next.add(targetId);
      }
      return next;
    });
    setNotice(
      willUnlock
        ? "Lock dibuka. Garis bisa diubah kembali."
        : "Garis di-lock. Posisi dan ukurannya tidak bisa diubah.",
    );
  }, [lockedLineIds, selectedLine]);

  const clearMeasurementLines = useCallback(() => {
    const keepIds = new Set(lockedLineIds);
    if (calibrationLineId !== null) keepIds.add(calibrationLineId);
    setLines((prev) => prev.filter((line) => keepIds.has(line.id)));
    setAngles([]);
    setCircles((prev) =>
      prev.filter((circle) => circle.id === calibrationCircleId),
    );
    setHkaSets([]);
    setDraftAnglePoints([]);
    setDraftCirclePoints([]);
    setDraftHkaPoints([]);
    setDraftFreeLine(null);
    setLockedLineIds(
      (prev) => new Set([...prev].filter((id) => keepIds.has(id))),
    );
    setDraftLine(null);
    setSelectedAngleId(null);
    setSelectedCircleId(null);
    setSelectedHkaId(null);
    if (selectedLineId !== null) {
      if (!keepIds.has(selectedLineId)) {
        setSelectedLineId(calibrationLineId);
      }
    }
    if (lockedLineIds.size > 0 && calibrationLineId !== null) {
      setNotice("Measurement dihapus, garis lock dan kalibrasi dipertahankan.");
      return;
    }
    if (lockedLineIds.size > 0) {
      setNotice("Measurement dihapus, garis lock dipertahankan.");
      return;
    }
    if (calibrationLineId !== null || calibrationCircleId !== null) {
      setNotice("Measurement dihapus, referensi kalibrasi dipertahankan.");
      return;
    }
    setNotice("Semua measurement dihapus.");
  }, [calibrationCircleId, calibrationLineId, lockedLineIds, selectedLineId]);

  const resetCalibration = useCallback(() => {
    setCalibrationLineId(null);
    setCalibrationCircleId(null);
    setMmPerPixel(null);
    setNotice(
      "Kalibrasi di-reset. Garis/circle tetap ada, silakan pilih referensi baru.",
    );
  }, []);

  const applyTemplateRealSize = useCallback(() => {
    if (!selectedCutLayer) {
      setNotice("Pilih template layer dulu untuk di-scale.");
      return;
    }
    if (!isImageBackedLayerKind(selectedCutLayer.kind)) {
      setNotice("Scale real size hanya untuk layer gambar/template.");
      return;
    }
    if (mmPerPixel === null) {
      setNotice("Kalibrasi garis real dulu sebelum mengatur ukuran template.");
      return;
    }
    if (selectedCutLayer.lockScale) {
      setNotice("Scale template terkunci. Buka Lock Scale dulu.");
      return;
    }

    const inputValue = Number(templateRealSizeInput);
    if (!Number.isFinite(inputValue) || inputValue <= 0) {
      setNotice("Isi ukuran real template dengan angka positif.");
      return;
    }

    const targetMm =
      templateRealSizeUnit === "cm" ? inputValue * 10 : inputValue;
    const targetPixels = targetMm / mmPerPixel;
    const currentSize = getLayerDisplaySize(selectedCutLayer);
    if (
      !Number.isFinite(currentSize.width) ||
      !Number.isFinite(currentSize.height) ||
      currentSize.width <= 0 ||
      currentSize.height <= 0
    ) {
      setNotice("Ukuran template saat ini tidak valid.");
      return;
    }

    const nextWidth =
      templateRealSizeAxis === "width"
        ? clamp(targetPixels, 16, Math.max(16, modelWidth * 3))
        : currentSize.width;
    const nextHeight =
      templateRealSizeAxis === "height"
        ? clamp(targetPixels, 16, Math.max(16, modelHeight * 3))
        : currentSize.height;

    setCutLayers((prev) =>
      prev.map((layer) =>
        layer.id === selectedCutLayer.id
          ? { ...layer, displayWidth: nextWidth, displayHeight: nextHeight }
          : layer,
      ),
    );
    const unitHint =
      templateRealSizeUnit === "mm" && inputValue <= 30
        ? " Jika hasil terlalu kecil dan maksudnya sentimeter, ganti unit ke cm."
        : "";
    const lockedAxisHint =
      templateRealSizeAxis === "width"
        ? " Tinggi tetap memakai ukuran layer sebelumnya."
        : " Lebar tetap memakai ukuran layer sebelumnya.";
    setNotice(
      `Template #${selectedCutLayer.id} di-scale dari ${templateRealSizeAxis === "width" ? "lebar" : "tinggi"} real ${inputValue} ${templateRealSizeUnit}.${lockedAxisHint}${unitHint}`,
    );
  }, [
    mmPerPixel,
    modelHeight,
    modelWidth,
    selectedCutLayer,
    templateRealSizeAxis,
    templateRealSizeInput,
    templateRealSizeUnit,
  ]);

  const trimSelectedTemplateLayer = useCallback(() => {
    if (!selectedCutLayer) {
      setNotice("Pilih template layer dulu untuk trim margin.");
      return;
    }
    if (
      !isImageBackedLayerKind(selectedCutLayer.kind) ||
      !selectedCutLayer.image
    ) {
      setNotice("Trim margin hanya untuk layer gambar/template.");
      return;
    }
    if (selectedCutLayer.lockScale) {
      setNotice(
        "Scale template terkunci. Buka Lock Scale dulu sebelum trim margin.",
      );
      return;
    }

    const bounds = getImageContentBounds(selectedCutLayer.image);
    if (!bounds) {
      setNotice("Tidak ada margin kosong yang bisa di-trim pada template ini.");
      return;
    }

    const oldSourceX = Number(selectedCutLayer.sourceX || 0);
    const oldSourceY = Number(selectedCutLayer.sourceY || 0);
    const oldSourceWidth = Math.max(
      1,
      Number(selectedCutLayer.sourceWidth || bounds.width),
    );
    const oldSourceHeight = Math.max(
      1,
      Number(selectedCutLayer.sourceHeight || bounds.height),
    );
    const isSameBounds =
      Math.abs(bounds.x - oldSourceX) <= 2 &&
      Math.abs(bounds.y - oldSourceY) <= 2 &&
      Math.abs(bounds.width - oldSourceWidth) <= 2 &&
      Math.abs(bounds.height - oldSourceHeight) <= 2;
    if (isSameBounds) {
      setNotice("Template sudah memakai bounding box konten.");
      return;
    }

    const currentSize = getLayerDisplaySize(selectedCutLayer);
    const nextDisplayWidth = clamp(
      currentSize.width * (bounds.width / oldSourceWidth),
      16,
      Math.max(16, modelWidth * 3),
    );
    const nextDisplayHeight = clamp(
      currentSize.height * (bounds.height / oldSourceHeight),
      16,
      Math.max(16, modelHeight * 3),
    );
    const localOffsetX =
      ((bounds.x + bounds.width / 2 - (oldSourceX + oldSourceWidth / 2)) /
        oldSourceWidth) *
      currentSize.width *
      (selectedCutLayer.flipX ? -1 : 1);
    const localOffsetY =
      ((bounds.y + bounds.height / 2 - (oldSourceY + oldSourceHeight / 2)) /
        oldSourceHeight) *
      currentSize.height *
      (selectedCutLayer.flipY ? -1 : 1);
    const rotatedOffset = rotateVector(
      localOffsetX,
      localOffsetY,
      selectedCutLayer.rotation || 0,
    );

    setCutLayers((prev) =>
      prev.map((layer) =>
        layer.id === selectedCutLayer.id
          ? {
              ...layer,
              sourceX: bounds.x,
              sourceY: bounds.y,
              sourceWidth: bounds.width,
              sourceHeight: bounds.height,
              displayWidth: nextDisplayWidth,
              displayHeight: nextDisplayHeight,
              centerX: layer.centerX + rotatedOffset.x,
              centerY: layer.centerY + rotatedOffset.y,
            }
          : layer,
      ),
    );
    setNotice(
      "Margin kosong template di-trim. Scale real sekarang memakai bounding box konten.",
    );
  }, [modelHeight, modelWidth, selectedCutLayer]);

  const applyTemplateRulerScale = useCallback(() => {
    if (!selectedCutLayer) {
      setNotice("Pilih template layer dulu untuk scale dari ruler template.");
      return;
    }
    if (
      !isImageBackedLayerKind(selectedCutLayer.kind) ||
      !selectedCutLayer.image
    ) {
      setNotice("Scale ruler hanya untuk layer gambar/template.");
      return;
    }
    if (mmPerPixel === null) {
      setNotice(
        "Kalibrasi garis real X-ray dulu sebelum memakai ruler template.",
      );
      return;
    }
    if (selectedCutLayer.lockScale) {
      setNotice("Scale template terkunci. Buka Lock Scale dulu.");
      return;
    }

    const physicalWidthMm = Number(selectedCutLayer.physicalWidthMm);
    const physicalHeightMm = Number(selectedCutLayer.physicalHeightMm);
    if (
      Number.isFinite(physicalWidthMm) &&
      physicalWidthMm > 0 &&
      Number.isFinite(physicalHeightMm) &&
      physicalHeightMm > 0
    ) {
      const nextWidth = clamp(
        physicalWidthMm / mmPerPixel,
        16,
        Math.max(16, modelWidth * 3),
      );
      const nextHeight = clamp(
        physicalHeightMm / mmPerPixel,
        16,
        Math.max(16, modelHeight * 3),
      );

      setCutLayers((prev) =>
        prev.map((layer) =>
          layer.id === selectedCutLayer.id
            ? { ...layer, displayWidth: nextWidth, displayHeight: nextHeight }
            : layer,
        ),
      );
      setNotice(
        `Template #${selectedCutLayer.id} disesuaikan sebagai ${selectedCutLayer.physicalSizeLabel || "ukuran fisik"} (${physicalWidthMm} x ${physicalHeightMm} mm).`,
      );
      return;
    }

    const rulerScale = estimateTemplateRulerPxPerMm(selectedCutLayer.image);
    if (!rulerScale) {
      setNotice(
        "Ruler template tidak terbaca otomatis. Gunakan Trim Margin + Scale Real manual.",
      );
      return;
    }

    const sourceWidth = Math.max(1, Number(selectedCutLayer.sourceWidth || 0));
    const sourceHeight = Math.max(
      1,
      Number(selectedCutLayer.sourceHeight || 0),
    );
    const nextWidth = clamp(
      sourceWidth / rulerScale.pxPerMm / mmPerPixel,
      16,
      Math.max(16, modelWidth * 3),
    );
    const nextHeight = clamp(
      sourceHeight / rulerScale.pxPerMm / mmPerPixel,
      16,
      Math.max(16, modelHeight * 3),
    );

    setCutLayers((prev) =>
      prev.map((layer) =>
        layer.id === selectedCutLayer.id
          ? { ...layer, displayWidth: nextWidth, displayHeight: nextHeight }
          : layer,
      ),
    );
    setNotice(
      `Template #${selectedCutLayer.id} disesuaikan dari ruler ${rulerScale.axis}.`,
    );
  }, [mmPerPixel, modelHeight, modelWidth, selectedCutLayer]);

  const copySelectedTemplateScale = useCallback(() => {
    if (!selectedCutLayer || !isImageBackedLayerKind(selectedCutLayer.kind)) {
      setNotice("Pilih template layer dulu untuk copy scale.");
      return;
    }

    const size = getLayerDisplaySize(selectedCutLayer);
    if (
      !Number.isFinite(size.width) ||
      !Number.isFinite(size.height) ||
      size.width <= 0 ||
      size.height <= 0
    ) {
      setNotice("Ukuran template tidak valid untuk copy scale.");
      return;
    }

    setCopiedTemplateScale({
      width: size.width,
      height: size.height,
      copiedFromId: selectedCutLayer.id,
      copiedFromName: selectedCutLayer.name || `Layer #${selectedCutLayer.id}`,
    });
    const text = `Scale template #${selectedCutLayer.id} berhasil dicopy.`;
    setNotice(text);
    setActionToast({ id: Date.now(), type: "success", text });
  }, [selectedCutLayer]);

  const pasteTemplateScaleToSelected = useCallback(() => {
    if (!selectedCutLayer || !isImageBackedLayerKind(selectedCutLayer.kind)) {
      setNotice("Pilih template layer tujuan dulu untuk paste scale.");
      return;
    }
    if (selectedCutLayer.lockScale) {
      setNotice("Scale template tujuan terkunci. Buka Lock Scale dulu.");
      return;
    }
    if (
      !copiedTemplateScale ||
      !Number.isFinite(copiedTemplateScale.width) ||
      !Number.isFinite(copiedTemplateScale.height)
    ) {
      setNotice("Belum ada scale template yang dicopy.");
      return;
    }

    const nextWidth = clamp(
      copiedTemplateScale.width,
      16,
      Math.max(16, modelWidth * 3),
    );
    const nextHeight = clamp(
      copiedTemplateScale.height,
      16,
      Math.max(16, modelHeight * 3),
    );
    setCutLayers((prev) =>
      prev.map((layer) =>
        layer.id === selectedCutLayer.id
          ? { ...layer, displayWidth: nextWidth, displayHeight: nextHeight }
          : layer,
      ),
    );
    const text = `Scale dari ${copiedTemplateScale.copiedFromName} berhasil dipaste ke template #${selectedCutLayer.id}.`;
    setNotice(text);
    setActionToast({ id: Date.now(), type: "success", text });
  }, [copiedTemplateScale, modelHeight, modelWidth, selectedCutLayer]);

  const rotateLeft = useCallback(() => {
    setRotation((prev) => (prev + 270) % 360);
  }, []);

  const rotateRight = useCallback(() => {
    setRotation((prev) => (prev + 90) % 360);
  }, []);

  const moveCutLayerInStack = useCallback((layerId, placement) => {
    setCutLayers((prev) => reorderLayerStack(prev, [layerId], placement));
    setNotice("Urutan layer diperbarui.");
  }, []);

  const moveSelectedCutLayersInStack = useCallback(
    (placement) => {
      if (!selectedCutLayerIds.length) {
        setNotice("Pilih layer dulu untuk mengubah urutan.");
        return;
      }
      setCutLayers((prev) =>
        reorderLayerStack(prev, selectedCutLayerIds, placement),
      );
      setNotice(
        selectedCutLayerIds.length > 1
          ? `Urutan ${selectedCutLayerIds.length} layer diperbarui.`
          : "Urutan layer diperbarui.",
      );
    },
    [selectedCutLayerIds],
  );

  const alignSelectedCutLayers = useCallback(
    (mode) => {
      if (selectedCutLayers.length < 2 || !selectedCutLayer) {
        setNotice("Pilih minimal 2 layer untuk align.");
        return;
      }

      const referenceBounds = getLayerBounds(selectedCutLayer);
      setCutLayers((prev) =>
        prev.map((layer) => {
          if (
            !selectedCutLayerIdsSet.has(layer.id) ||
            layer.id === selectedCutLayer.id ||
            layer.lockScale
          ) {
            return layer;
          }
          const layerBounds = getLayerBounds(layer);
          let dx = 0;
          let dy = 0;
          if (mode === "left") dx = referenceBounds.left - layerBounds.left;
          if (mode === "center")
            dx = referenceBounds.centerX - layerBounds.centerX;
          if (mode === "right") dx = referenceBounds.right - layerBounds.right;
          if (mode === "top") dy = referenceBounds.top - layerBounds.top;
          if (mode === "middle")
            dy = referenceBounds.centerY - layerBounds.centerY;
          if (mode === "bottom")
            dy = referenceBounds.bottom - layerBounds.bottom;
          return {
            ...layer,
            centerX: Number(layer.centerX || 0) + dx,
            centerY: Number(layer.centerY || 0) + dy,
          };
        }),
      );
      setNotice(`Align ${mode} diterapkan ke ${selectedCutLayers.length} layer.`);
    },
    [selectedCutLayer, selectedCutLayerIdsSet, selectedCutLayers.length],
  );

  const distributeSelectedCutLayers = useCallback(
    (axis) => {
      if (selectedCutLayers.length < 3) {
        setNotice("Pilih minimal 3 layer untuk distribute.");
        return;
      }

      const sorted = [...selectedCutLayers].sort((left, right) => {
        const leftBounds = getLayerBounds(left);
        const rightBounds = getLayerBounds(right);
        return axis === "horizontal"
          ? leftBounds.centerX - rightBounds.centerX
          : leftBounds.centerY - rightBounds.centerY;
      });

      const firstBounds = getLayerBounds(sorted[0]);
      const lastBounds = getLayerBounds(sorted[sorted.length - 1]);
      const start = axis === "horizontal" ? firstBounds.centerX : firstBounds.centerY;
      const end = axis === "horizontal" ? lastBounds.centerX : lastBounds.centerY;
      const step = (end - start) / Math.max(1, sorted.length - 1);
      const targets = new Map(
        sorted.map((layer, index) => [layer.id, start + step * index]),
      );

      setCutLayers((prev) =>
        prev.map((layer) => {
          const target = targets.get(layer.id);
          if (target === undefined || layer.lockScale) return layer;
          const bounds = getLayerBounds(layer);
          if (axis === "horizontal") {
            return {
              ...layer,
              centerX: Number(layer.centerX || 0) + (target - bounds.centerX),
            };
          }
          return {
            ...layer,
            centerY: Number(layer.centerY || 0) + (target - bounds.centerY),
          };
        }),
      );
      setNotice(
        `Distribusi ${axis === "horizontal" ? "horizontal" : "vertikal"} diterapkan.`,
      );
    },
    [selectedCutLayers],
  );

  const groupSelectedCutLayers = useCallback(() => {
    if (selectedCutLayerIds.length < 2) {
      setNotice("Pilih minimal 2 layer untuk digroup.");
      return;
    }
    const nextGroupId = createTemplatingId();
    setCutLayers((prev) =>
      prev.map((layer) =>
        selectedCutLayerIdsSet.has(layer.id)
          ? { ...layer, groupId: nextGroupId }
          : layer,
      ),
    );
    setNotice(`Group dibuat untuk ${selectedCutLayerIds.length} layer.`);
  }, [selectedCutLayerIds.length, selectedCutLayerIdsSet]);

  const ungroupSelectedCutLayers = useCallback(() => {
    if (!selectedCutLayerIds.length) {
      setNotice("Pilih layer dulu untuk ungroup.");
      return;
    }
    const targetGroupIds = new Set(
      selectedCutLayers
        .map((layer) => layer.groupId)
        .filter((groupId) => Boolean(groupId)),
    );
    if (!targetGroupIds.size) {
      setNotice("Layer terpilih belum punya group.");
      return;
    }
    setCutLayers((prev) =>
      prev.map((layer) =>
        targetGroupIds.has(layer.groupId)
          ? { ...layer, groupId: null }
          : layer,
      ),
    );
    setNotice("Group layer dibuka.");
  }, [selectedCutLayerIds.length, selectedCutLayers]);

  const duplicateSelectedCutLayer = useCallback(() => {
    if (!selectedCutLayerIds.length) {
      setNotice("Pilih layer dulu untuk diduplikasi.");
      return;
    }

    const orderedSelection = cutLayers.filter((layer) =>
      selectedCutLayerIdsSet.has(layer.id),
    );
    const nextGroupId =
      orderedSelection.length > 1 ? createTemplatingId() : null;
    const duplicatedLayers = orderedSelection.map((layer, index) => {
      const nextId = nextCutLayerIdRef.current + index;
      return {
        ...layer,
        id: nextId,
        groupId: orderedSelection.length > 1 ? nextGroupId : null,
        name: `${layer.name || `Layer #${layer.id}`} Copy`,
        centerX: Number(layer.centerX || 0) + DEFAULT_LAYER_DUPLICATE_OFFSET,
        centerY: Number(layer.centerY || 0) + DEFAULT_LAYER_DUPLICATE_OFFSET,
      };
    });
    nextCutLayerIdRef.current += duplicatedLayers.length;
    setCutLayers((prev) => [...prev, ...duplicatedLayers]);
    if (duplicatedLayers.length) {
      setSelectedCutLayerId(duplicatedLayers[0].id);
      setSelectedCutLayerExtraIds(
        duplicatedLayers.slice(1).map((layer) => layer.id),
      );
    }
    setNotice(
      duplicatedLayers.length > 1
        ? `${duplicatedLayers.length} layer berhasil diduplikasi dengan offset.`
        : `Layer #${orderedSelection[0].id} berhasil diduplikasi dengan offset.`,
    );
  }, [cutLayers, selectedCutLayerIds.length, selectedCutLayerIdsSet]);

  const removeSelectedCutLayer = useCallback(() => {
    if (!selectedCutLayerIds.length) {
      setNotice("Pilih layer dulu untuk dihapus.");
      return;
    }
    const deletedLayerIds = [...selectedCutLayerIds];
    const deletedIdSet = new Set(deletedLayerIds);
    setCutLayers((prev) => {
      prev.forEach((layer) => {
        const stillUsedByRemainingLayer = prev.some(
          (candidate) =>
            !deletedIdSet.has(candidate.id) &&
            candidate.imageSrc &&
            candidate.imageSrc === layer.imageSrc,
        );
        if (
          deletedIdSet.has(layer.id) &&
          layerObjectUrlsRef.current.has(layer.imageSrc) &&
          !stillUsedByRemainingLayer
        ) {
          URL.revokeObjectURL(layer.imageSrc);
          layerObjectUrlsRef.current.delete(layer.imageSrc);
        }
      });
      return prev.filter((layer) => !deletedIdSet.has(layer.id));
    });
    setSelectedCutLayerId(null);
    setSelectedCutLayerExtraIds([]);
    setNotice(
      deletedLayerIds.length > 1
        ? `${deletedLayerIds.length} layer dihapus.`
        : `Layer #${deletedLayerIds[0]} dihapus.`,
    );
  }, [selectedCutLayerIds]);

