                    border: isDark ? "1px solid rgba(255,255,255,0.12)" : "1px solid rgba(255,255,255,0.45)",
                    boxShadow: isDark ? "0 4px 24px rgba(0,5,20,0.60),0 1px 4px rgba(55,80,140,0.16)" : "2px 2px 8px rgba(148,163,184,0.20)",
